import { Enemy, PickupType } from '../types.ts';

export interface EnemyDefeatHost {
  enemies: Enemy[];
  kills: number;
  comboIdleTimer: number;
  isFever: boolean;
  comboMeter: number;
  feverTimer: number;
  pickups: Array<{ id: string; x: number; y: number; type: PickupType; life: number; bobAngle: number }>;
  hasCompoundInterest: boolean;
  damageMultiplier: number;
  elapsedTime: number;
  activeEvent: { effect: { expDropMult?: number } } | null;
  callbacks: {
    onKillsChange: (kills: number) => void;
    onFeverChange?: (meter: number, isFever: boolean, remainingSec: number) => void;
  };
  soundManager: {
    playBoost: () => void;
  };
  particleSystem: {
    emitDeath: (x: number, y: number) => void;
  };
  lootManager: {
    dropEnemyLoot: (e: Enemy, elapsedTime: number, mult?: number) => void;
  };
  playerHp?: number;
  playerMaxHp?: number;
}

export class EnemyDefeatProcessor {
  public static process(host: EnemyDefeatHost, idx: number): void {
    const e = host.enemies[idx];
    host.enemies.splice(idx, 1);
    host.kills++;
    host.callbacks.onKillsChange(host.kills);
    host.particleSystem.emitDeath(e.x, e.y);

    // Charge Fever Bull Run meter
    host.comboIdleTimer = 0;
    if (!host.isFever) {
      host.comboMeter = Math.min(100, host.comboMeter + 4.5);
      if (host.comboMeter >= 100) {
        host.isFever = true;
        host.feverTimer = 8.0;
        host.soundManager.playBoost();
      }
      host.callbacks.onFeverChange?.(host.comboMeter, host.isFever, Math.ceil(host.feverTimer));
    }

    // --- Dynamic Healing HEART Drop with Mercy Clutch Protection ---
    const curHp = host.playerHp ?? (host as any).hp;
    const curMaxHp = host.playerMaxHp ?? (host as any).maxHp;
    const isLowHp =
      curHp !== undefined &&
      curMaxHp !== undefined &&
      curMaxHp > 0 &&
      curHp / curMaxHp < 0.35;

    let heartDropChance = 0.025; // Base 2.5% on normal mobs
    if (e.isElite || e.type === 'BLACK_SWAN' || e.type === 'LIQUIDATION_REAPER' || e.type === 'BEAR') {
      heartDropChance = 0.35; // 35% on elite/heavy mobs
    }
    if (isLowHp) {
      heartDropChance = e.isElite ? 0.80 : 0.08; // 3~4x surge when in critical HP!
    }

    let droppedHeart = false;
    if (Math.random() < heartDropChance && host.pickups.length < 3) {
      host.pickups.push({
        id: `pickup_heart_${Date.now()}_${Math.random()}`,
        x: e.x,
        y: e.y,
        type: 'HEART',
        life: 10000,
        bobAngle: Math.random() * Math.PI * 2,
      });
      droppedHeart = true;
    }

    // Drop Battlefield Pickup (Buff / Offensive items)
    if (!droppedHeart) {
      let dropChance = 0.015;
      if (e.isBoss) dropChance = 1.0;
      else if (e.isElite || e.type === 'BLACK_SWAN' || e.type === 'LIQUIDATION_REAPER' || e.type === 'BEAR') {
        dropChance = 0.055;
      }

      if (Math.random() < dropChance && host.pickups.length < 3) {
        const types: PickupType[] = ['ROCKET', 'NUKE', 'MAGNET', 'PIZZA', 'FREEZE', 'HEART'];
        const pType = types[Math.floor(Math.random() * types.length)];
        host.pickups.push({
          id: `pickup_${Date.now()}_${Math.random()}`,
          x: e.x,
          y: e.y,
          type: pType,
          life: 10000,
          bobAngle: Math.random() * Math.PI * 2,
        });
        if (e.isBoss) {
          const pType2 = types[Math.floor(Math.random() * types.length)];
          host.pickups.push({
            id: `pickup_extra_${Date.now()}_${Math.random()}`,
            x: e.x + 18,
            y: e.y + 18,
            type: pType2,
            life: 10000,
            bobAngle: Math.random() * Math.PI * 2,
          });
        }
      }
    }

    // Compound Interest Growth
    if (host.hasCompoundInterest && host.kills % 15 === 0) {
      host.damageMultiplier = Math.min(3.5, host.damageMultiplier + 0.05);
    }

    // EXP Gem Drops
    host.lootManager.dropEnemyLoot(e, host.elapsedTime, host.activeEvent?.effect.expDropMult);
  }
}
