import { zhTW } from '../i18n/locales/zh-TW.ts';
import { en } from '../i18n/locales/en.ts';

export type Locale = 'zh-TW' | 'en';

export interface ResolveLocaleParams {
  search?: string;
  localStorageVal?: string | null;
  referrer?: string;
  navigatorLang?: string;
}

export class I18nService {
  private static instance: I18nService | null = null;
  private currentLocale: Locale = 'zh-TW';
  private listeners: ((locale: Locale) => void)[] = [];

  private dictionaries: Record<Locale, Record<string, any>> = {
    'zh-TW': zhTW,
    en: en,
  };

  constructor() {
    this.initFromEnvironment();
  }

  public static getInstance(): I18nService {
    if (!I18nService.instance) {
      I18nService.instance = new I18nService();
    }
    return I18nService.instance;
  }

  /**
   * Cascading resolution for language.
   * User's explicit localStorage preference takes highest precedence to prevent URL sticky overrides.
   */
  public resolveLocale(params: ResolveLocaleParams): Locale {
    // 1. Explicit user preference stored in localStorage
    if (params.localStorageVal) {
      const val = params.localStorageVal.toLowerCase();
      if (val === 'en' || val === 'en-us') return 'en';
      if (val === 'zh-tw' || val === 'zh_tw' || val === 'zh' || val === 'zh-hant') return 'zh-TW';
    }

    // 2. URL search query: ?lang=en or ?lang=zh-TW or ?lang=zh_TW (for first-time link entries)
    if (params.search) {
      try {
        const query = new URLSearchParams(params.search);
        const lang = query.get('lang')?.toLowerCase();
        if (lang === 'en' || lang === 'en-us') return 'en';
        if (lang === 'zh-tw' || lang === 'zh_tw' || lang === 'zh' || lang === 'zh-hant') return 'zh-TW';
      } catch {
        // Ignore parse error
      }
    }

    // 3. Referrer detection: from https://www.snek.com.tw/en/...
    if (params.referrer && params.referrer.includes('/en/')) {
      return 'en';
    }

    // 4. Default site locale matches www.snek.com.tw defaultLocale (zh-Hant)
    return 'zh-TW';
  }

  private initFromEnvironment(): void {
    if (typeof window === 'undefined') return;

    let storageVal: string | null = null;
    try {
      storageVal =
        localStorage.getItem('snek_locale') ||
        localStorage.getItem('snek_lang') ||
        localStorage.getItem('snek_arcade:locale');
    } catch {
      // Ignored
    }

    const resolved = this.resolveLocale({
      search: window.location.search,
      localStorageVal: storageVal,
      referrer: document.referrer,
      navigatorLang: navigator.language,
    });

    this.currentLocale = resolved;
  }

  public getLocale(): Locale {
    return this.currentLocale;
  }

  public setLocale(locale: Locale): void {
    this.currentLocale = locale;

    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem('snek_locale', locale);
        localStorage.setItem('snek_arcade:locale', locale);
        localStorage.setItem('snek_lang', locale);

        // Keep URL query synchronized to prevent URL params from overriding user change
        if (window.location.search && window.location.search.includes('lang=')) {
          const url = new URL(window.location.href);
          url.searchParams.set('lang', locale === 'zh-TW' ? 'zh-tw' : 'en');
          window.history.replaceState(null, '', url.toString());
        }
      } catch {
        // Ignored
      }
    }

    for (const listener of this.listeners) {
      listener(locale);
    }
  }

  public onLocaleChange(callback: (locale: Locale) => void): () => void {
    this.listeners.push(callback);
    return () => {
      this.listeners = this.listeners.filter(cb => cb !== callback);
    };
  }

  /**
   * Translate a key with optional interpolation: t('boss.stageClear', { stage: 3 })
   */
  public t(key: string, params?: Record<string, string | number>): string {
    const dict = this.dictionaries[this.currentLocale] || this.dictionaries['zh-TW'];
    const parts = key.split('.');

    let current: any = dict;
    for (const part of parts) {
      if (current && typeof current === 'object' && part in current) {
        current = current[part];
      } else {
        return key; // Fallback to raw key
      }
    }

    if (Array.isArray(current)) {
      return current.join(', ');
    }

    if (typeof current !== 'string') {
      return key;
    }

    let text = current;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
      }
    }

    return text;
  }

  /**
   * Translate a key into a string array, or empty array if not found
   */
  public tArray(key: string): string[] {
    const dict = this.dictionaries[this.currentLocale] || this.dictionaries['zh-TW'];
    const parts = key.split('.');

    let current: any = dict;
    for (const part of parts) {
      if (current && typeof current === 'object' && part in current) {
        current = current[part];
      } else {
        return [];
      }
    }

    return Array.isArray(current) ? [...current] : [];
  }
}
