export interface PlayerMotionHost {
  px: number;
  py: number;
  pvx: number;
  pvy: number;
  speed: number;
  playerSize: number;
  width: number;
  height: number;
  invulnerableTimer: number;
  rocketTimer: number;
  freezeTimer: number;
  nukeFlashTimer: number;
  magnetAllTimer: number;
  stageAlert: { timer: number } | null;
  isFever: boolean;
  feverTimer: number;
  comboMeter: number;
  comboIdleTimer: number;
  activeEvent: { effect: { playerSpeedMult?: number } } | null;
  particleSystem: {
    emitBurnDash: (x: number, y: number, angle: number) => void;
  };
  bossCombatController?: {
    getPlayerSpeedModifier: (x: number, y: number) => number;
  };
  callbacks: {
    onFeverChange?: (meter: number, isFever: boolean, remainingSec: number) => void;
  };
}

export class PlayerMotionManager {
  public static update(host: PlayerMotionHost, dt: number): void {
    if (host.invulnerableTimer > 0) {
      host.invulnerableTimer -= dt;
    }

    // Active Pickup Timers
    if (host.rocketTimer > 0) {
      host.rocketTimer -= dt / 1000;
      host.invulnerableTimer = Math.max(host.invulnerableTimer, 200);
      if (Math.random() < 0.5) {
        host.particleSystem.emitBurnDash(host.px, host.py, Math.random() * Math.PI * 2);
      }
    }
    if (host.freezeTimer > 0) {
      host.freezeTimer -= dt / 1000;
    }
    if (host.nukeFlashTimer > 0) {
      host.nukeFlashTimer -= dt / 1000;
    }
    if (host.magnetAllTimer > 0) {
      host.magnetAllTimer -= dt / 1000;
    }
    if (host.stageAlert) {
      host.stageAlert.timer -= dt / 1000;
      if (host.stageAlert.timer <= 0) {
        host.stageAlert = null;
      }
    }

    // Fever Bull Run Mode Timer & Decay
    if (host.isFever) {
      host.feverTimer -= dt / 1000;
      host.comboMeter = Math.max(0, (host.feverTimer / 8.0) * 100);
      if (host.feverTimer <= 0) {
        host.isFever = false;
        host.comboMeter = 0;
      }
      host.callbacks.onFeverChange?.(host.comboMeter, host.isFever, Math.ceil(host.feverTimer));
    } else {
      host.comboIdleTimer += dt / 1000;
      if (host.comboIdleTimer > 2.0 && host.comboMeter > 0) {
        host.comboMeter = Math.max(0, host.comboMeter - (dt / 1000) * 16);
        host.callbacks.onFeverChange?.(host.comboMeter, false, 0);
      }
    }

    // Move Player (Frame-rate Independent with dtScale)
    const dtScale = Math.min(2.0, Math.max(0.1, dt / 16.6667));
    let currentSpeed = host.speed * dtScale;
    if (host.activeEvent?.effect.playerSpeedMult) {
      currentSpeed *= host.activeEvent.effect.playerSpeedMult;
    }
    if (host.bossCombatController) {
      currentSpeed *= host.bossCombatController.getPlayerSpeedModifier(host.px, host.py);
    }
    if (host.rocketTimer > 0) {
      currentSpeed *= 1.6;
    }
    if (host.isFever) {
      currentSpeed *= 1.35;
    }

    host.px = Math.max(
      host.playerSize,
      Math.min(host.width - host.playerSize, host.px + host.pvx * currentSpeed)
    );
    host.py = Math.max(
      host.playerSize,
      Math.min(host.height - host.playerSize, host.py + host.pvy * currentSpeed)
    );

    // Rocket Particle Trail
    if (Math.hypot(host.pvx, host.pvy) > 0.1 && (Math.random() < 0.25 || host.rocketTimer > 0)) {
      host.particleSystem.emitBurnDash(host.px, host.py, Math.random() * Math.PI * 2);
    }
  }
}
