export interface StorageServiceOptions {
  prefix?: string;
}

export class StorageService {
  private prefix: string;
  private memoryFallback: Map<string, string> = new Map();
  private useFallback: boolean = false;

  constructor(options: StorageServiceOptions = {}) {
    this.prefix = options.prefix ?? 'snek_arcade:';
    this.testLocalStorage();
  }

  private testLocalStorage(): void {
    try {
      if (typeof window === 'undefined' || !window.localStorage) {
        this.useFallback = true;
        return;
      }
      const testKey = `__${this.prefix}test__`;
      window.localStorage.setItem(testKey, '1');
      window.localStorage.removeItem(testKey);
    } catch {
      this.useFallback = true;
    }
  }

  private getFullKey(key: string): string {
    return `${this.prefix}${key}`;
  }

  public getItem<T>(key: string, defaultValue: T): T {
    const fullKey = this.getFullKey(key);

    try {
      let raw: string | null = null;
      if (this.useFallback) {
        raw = this.memoryFallback.get(fullKey) ?? null;
      } else {
        raw = window.localStorage.getItem(fullKey);
      }

      if (raw === null || raw === undefined) {
        return defaultValue;
      }

      return JSON.parse(raw) as T;
    } catch {
      return defaultValue;
    }
  }

  public setItem<T>(key: string, value: T): boolean {
    const fullKey = this.getFullKey(key);
    const serialized = JSON.stringify(value);

    if (this.useFallback) {
      this.memoryFallback.set(fullKey, serialized);
      return true;
    }

    try {
      window.localStorage.setItem(fullKey, serialized);
      return true;
    } catch {
      // Graceful degradation on QuotaExceededError or security block
      this.useFallback = true;
      this.memoryFallback.set(fullKey, serialized);
      return true;
    }
  }

  public removeItem(key: string): void {
    const fullKey = this.getFullKey(key);
    if (this.useFallback) {
      this.memoryFallback.delete(fullKey);
      return;
    }

    try {
      window.localStorage.removeItem(fullKey);
    } catch {
      this.useFallback = true;
      this.memoryFallback.delete(fullKey);
    }
  }

  public hasItem(key: string): boolean {
    const fullKey = this.getFullKey(key);
    if (this.useFallback) {
      return this.memoryFallback.has(fullKey);
    }

    try {
      return window.localStorage.getItem(fullKey) !== null;
    } catch {
      return this.memoryFallback.has(fullKey);
    }
  }

  public clear(prefixOnly: boolean = true): void {
    if (this.useFallback) {
      if (prefixOnly) {
        for (const k of Array.from(this.memoryFallback.keys())) {
          if (k.startsWith(this.prefix)) {
            this.memoryFallback.delete(k);
          }
        }
      } else {
        this.memoryFallback.clear();
      }
      return;
    }

    try {
      if (prefixOnly) {
        const keysToRemove: string[] = [];
        for (let i = 0; i < window.localStorage.length; i++) {
          const k = window.localStorage.key(i);
          if (k && k.startsWith(this.prefix)) {
            keysToRemove.push(k);
          }
        }
        for (const k of keysToRemove) {
          window.localStorage.removeItem(k);
        }
      } else {
        window.localStorage.clear();
      }
    } catch {
      this.useFallback = true;
      this.memoryFallback.clear();
    }
  }

  public isUsingFallback(): boolean {
    return this.useFallback;
  }
}
