import { Projectile } from '../types.ts';

export interface SpawnProjectileOptions {
  x: number;
  y: number;
  vx: number;
  vy: number;
  damage: number;
  life: number;
}

export interface SpawnSpreadOptions {
  originX: number;
  originY: number;
  targetX: number;
  targetY: number;
  count: number;
  speed: number;
  damage: number;
  life: number;
  spreadAngle?: number;
}

export class ProjectileSystem {
  public activeProjectiles: Projectile[] = [];

  /**
   * Spawns a single projectile.
   */
  public spawn(options: SpawnProjectileOptions): Projectile {
    const p: Projectile = {
      x: options.x,
      y: options.y,
      vx: options.vx,
      vy: options.vy,
      damage: options.damage,
      life: options.life,
    };
    this.activeProjectiles.push(p);
    return p;
  }

  /**
   * Spawns a spread of projectiles aimed at target coordinates.
   */
  public spawnSpread(options: SpawnSpreadOptions): void {
    const {
      originX,
      originY,
      targetX,
      targetY,
      count,
      speed,
      damage,
      life,
      spreadAngle = 0.22,
    } = options;

    const baseAngle = Math.atan2(targetY - originY, targetX - originX);

    for (let i = 0; i < count; i++) {
      const spread = (i - (count - 1) / 2) * spreadAngle;
      const angle = baseAngle + spread;
      this.spawn({
        x: originX,
        y: originY,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        damage,
        life,
      });
    }
  }

  /**
   * Update all active projectiles coordinates and lifespans.
   */
  public update(dt: number): void {
    const dtScale = dt / 16.667;

    for (let i = this.activeProjectiles.length - 1; i >= 0; i--) {
      const p = this.activeProjectiles[i];
      p.x += p.vx * dtScale;
      p.y += p.vy * dtScale;
      p.life -= dt;

      if (p.life <= 0) {
        this.activeProjectiles.splice(i, 1);
      }
    }
  }

  /**
   * Clear all active projectiles.
   */
  public clear(): void {
    this.activeProjectiles = [];
  }
}
