import {
  BossBullet,
  BossEntity,
  BossFloatingText,
  Enemy,
  SiphonOrb,
  BossCloneEntity,
  BossHazardZone,
  CandlestickBarricade,
  CrossLaser,
  VerticalWickStrike,
} from '../types.ts';
import { BossMotionController } from './BossMotionController.ts';
import { BossCloneSystem } from './BossCloneSystem.ts';

export interface BossCombatControllerOptions {
  arenaWidth: number;
  arenaHeight: number;
  onBossDefeated?: (boss: BossEntity) => void;
  onPlayerDamage?: (damage: number) => void;
  onPlaySound?: (sound: 'boost' | 'die') => void;
  onSpawnRetailMob?: (count: number) => void;
  onDropHeart?: (x: number, y: number) => void;
}

export class BossCombatController {
  public arenaWidth: number;
  public arenaHeight: number;
  public currentBoss: BossEntity | null = null;
  public bossBullets: BossBullet[] = [];
  public siphonOrbs: SiphonOrb[] = [];
  public bossFloatingTexts: BossFloatingText[] = [];
  public motionController: BossMotionController = new BossMotionController();
  public cloneSystem: BossCloneSystem = new BossCloneSystem();
  public phaseHeartDrops: Record<string, boolean> = { '75': false, '50': false, '25': false };

  // Advanced Meme Boss Hazard Zones, Barricades, Lasers & Strikes
  public hazardZones: BossHazardZone[] = [];
  public barricades: CandlestickBarricade[] = [];
  public crossLaser: CrossLaser | null = null;
  public wickStrike: VerticalWickStrike | null = null;

  private onBossDefeated?: (boss: BossEntity) => void;
  private onPlayerDamage?: (damage: number) => void;
  private onPlaySound?: (sound: 'boost' | 'die') => void;
  private onSpawnRetailMob?: (count: number) => void;
  private onDropHeart?: (x: number, y: number) => void;

  constructor(options: BossCombatControllerOptions) {
    this.arenaWidth = options.arenaWidth;
    this.arenaHeight = options.arenaHeight;
    this.onBossDefeated = options.onBossDefeated;
    this.onPlayerDamage = options.onPlayerDamage;
    this.onPlaySound = options.onPlaySound;
    this.onSpawnRetailMob = options.onSpawnRetailMob;
    this.onDropHeart = options.onDropHeart;
  }

  public setBoss(boss: BossEntity | null): void {
    this.currentBoss = boss;
  }

  public checkBossDefeat(): boolean {
    if (this.currentBoss && this.currentBoss.hp <= 0) {
      const boss = this.currentBoss;
      this.currentBoss = null;
      this.cloneSystem.clear();
      this.onBossDefeated?.(boss);
      return true;
    }
    return false;
  }

  public deflectBossDamage(boss: BossEntity, hitX?: number, hitY?: number, damage?: number): void {
    this.onPlaySound?.('boost');
    const label = damage !== undefined ? `🛡️ -${Math.round(damage)}` : 'IMMUNE 🛡️';
    this.bossFloatingTexts.push({
      id: `immune_${Date.now()}_${Math.random()}`,
      x: hitX || boss.x,
      y: (hitY || boss.y) - 15,
      text: label,
      color: '#00e5ff',
      life: 800,
      maxLife: 800,
      vy: -32,
    });
  }

  public getPlayerSpeedModifier(px: number, py: number): number {
    let speedMod = 1.0;
    for (const zone of this.hazardZones) {
      const dist = Math.hypot(px - zone.x, py - zone.y);
      if (dist < zone.radius) {
        if (zone.type === 'STICKY_YARN') {
          speedMod = Math.min(speedMod, 0.55); // -45% slow
        } else if (zone.type === 'WATER_PUDDLE') {
          speedMod = Math.min(speedMod, 0.85); // -15% slippery control
        }
      }
    }
    return speedMod;
  }

  public handleWallImpact(
    boss: BossEntity,
    impactX: number,
    impactY: number,
    normalX: number,
    normalY: number
  ): void {
    const dmgMult = boss.damageMultiplier || 1.0;
    // 5 fan-shaped tidal water splash bullets pointing inwards towards center
    const baseAngle = Math.atan2(normalY, normalX);
    const count = 5;
    const speed = 4.5;
    for (let i = 0; i < count; i++) {
      const spread = (i - (count - 1) / 2) * 0.28;
      const angle = baseAngle + spread;
      const b: BossBullet = {
        id: `bb_tidal_${Date.now()}_${i}`,
        type: 'WATER_SPLASH',
        x: impactX,
        y: impactY,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        radius: 10,
        damage: Math.round(24 * dmgMult),
        color: '#00e5ff',
        glowColor: '#00b0ff',
        life: 3600,
      };
      this.bossBullets.push(b);
    }

    // Leave a water puddle hazard zone
    this.hazardZones.push({
      id: `puddle_${Date.now()}`,
      type: 'WATER_PUDDLE',
      x: impactX,
      y: impactY,
      radius: 36,
      life: 4000,
      maxLife: 4000,
    });
    this.onPlaySound?.('boost');
  }

  public triggerVerticalWickStrike(boss: BossEntity, player: { x: number; y: number }): void {
    const dmgMult = boss.damageMultiplier || 1.0;
    this.wickStrike = {
      id: `wick_${Date.now()}`,
      x: player.x,
      phase: 'AIMING',
      timer: 0.8,
      damage: Math.round(28 * dmgMult),
    };
    if (!boss.telegraphs) boss.telegraphs = [];
    boss.telegraphs.push({
      id: `tel_wick_${Date.now()}`,
      type: 'LINE',
      x: player.x,
      y: 0,
      targetX: player.x,
      targetY: this.arenaHeight,
      width: 8,
      radius: 8,
      duration: 0.8,
      maxDuration: 0.8,
      color: 'rgba(255, 23, 68, 0.45)',
    });
    this.onPlaySound?.('boost');
  }

  public updateWickStrike(
    dt: number,
    player: { x: number; y: number; size?: number },
    onPlayerHit?: (damage: number) => void
  ): void {
    if (!this.wickStrike) return;
    const dtSec = dt / 1000;
    this.wickStrike.timer -= dtSec;

    if (this.wickStrike.phase === 'AIMING') {
      if (this.wickStrike.timer <= 0) {
        this.wickStrike.phase = 'STRIKING';
        this.wickStrike.timer = 0.35;
        this.onPlaySound?.('die');

        // Focused needle column (14px precision hitbox, easily dodged)
        if (Math.abs(player.x - this.wickStrike.x) < 14) {
          onPlayerHit?.(this.wickStrike.damage);
          this.onPlayerDamage?.(this.wickStrike.damage);
        }
      }
    } else if (this.wickStrike.phase === 'STRIKING') {
      if (this.wickStrike.timer <= 0) {
        this.wickStrike = null;
      }
    }
  }

  public triggerCrossLaser(boss: BossEntity): void {
    const dmgMult = boss.damageMultiplier || 1.0;
    this.crossLaser = {
      active: true,
      phase: 'AIMING',
      timer: 0.8,
      centerX: this.arenaWidth / 2,
      centerY: this.arenaHeight / 2,
      angle1: Math.PI / 4,
      angle2: (3 * Math.PI) / 4,
      damage: Math.round(25 * dmgMult),
      color: '#ffd700',
    };
    this.onPlaySound?.('boost');
  }

  public triggerMoggingBarrier(boss: BossEntity): void {
    boss.isDeflectingProjectiles = true;
    boss.gravityPullActive = true;
    boss.specialCooldown = 2.0; // 2 seconds duration
    this.bossFloatingTexts.push({
      id: `ft_mog_${Date.now()}`,
      x: boss.x,
      y: boss.y - 35,
      text: 'MOGGED! 🗿 霸體金身!',
      color: '#ffd700',
      life: 1800,
      maxLife: 1800,
      vy: -0.5,
    });
    this.onPlaySound?.('boost');
  }

  public applyGravityPull(
    boss: BossEntity,
    player: { x: number; y: number },
    dt: number
  ): void {
    if (!boss.gravityPullActive) return;
    const dtSec = dt / 1000;
    const dx = boss.x - player.x;
    const dy = boss.y - player.y;
    const dist = Math.hypot(dx, dy);
    if (dist > 30) {
      const pullSpeed = 15; // Very subtle gentle drift (player moves freely)
      player.x += (dx / dist) * pullSpeed * dtSec;
      player.y += (dy / dist) * pullSpeed * dtSec;
    }
  }

  public checkCrossLaserCollision(player: { x: number; y: number; size?: number }): void {
    if (!this.crossLaser || this.crossLaser.phase !== 'FIRING') return;
    const { centerX, centerY, angle1, angle2, damage } = this.crossLaser;
    for (const angle of [angle1, angle2]) {
      const nx = -Math.sin(angle);
      const ny = Math.cos(angle);
      const dist = Math.abs(nx * (player.x - centerX) + ny * (player.y - centerY));
      // Sharp razor line hitbox (8px), leaving four spacious quadrants for safe maneuvering
      if (dist < 8) {
        this.onPlayerDamage?.(damage);
        this.onPlaySound?.('die');
        break;
      }
    }
  }

  public fireCloneAttack(clone: BossCloneEntity, player: { x: number; y: number }): void {
    const bx = clone.x;
    const by = clone.y + clone.size * 0.6;
    const speed = 4.0;
    const baseAngle = Math.atan2(player.y - by, player.x - bx);
    for (const spread of [-0.2, 0.2]) {
      const angle = baseAngle + spread;
      this.bossBullets.push({
        id: `clone_b_${Date.now()}_${Math.random()}`,
        type: 'STINGER',
        x: bx,
        y: by,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        radius: 6,
        damage: 16,
        color: '#00e5ff',
        glowColor: '#00b0ff',
        life: 3500,
      });
    }
  }

  public triggerLaserAttack(boss: BossEntity, player: { x: number; y: number }): void {
    const startX = boss.x;
    const startY = boss.y + boss.size * 0.7;
    const angle = Math.atan2(player.y - startY, player.x - startX);

    if (!boss.laser) {
      boss.laser = {
        active: true,
        phase: 'AIMING',
        startX,
        startY,
        angle,
        targetAngle: angle,
        sweepSpeed: 0,
        timer: 1.2,
        width: 28,
        damage: 45,
        color: '#00e5ff',
        glowColor: '#00b0ff',
      };
    } else {
      boss.laser.active = true;
      boss.laser.phase = 'AIMING';
      boss.laser.timer = 1.2;
      boss.laser.startX = startX;
      boss.laser.startY = startY;
      boss.laser.angle = angle;
      boss.laser.width = 28;
    }
    this.onPlaySound?.('boost');
  }

  public calculateSlashDamage(stage: number = 1, bossType?: string): number {
    const scale = 0.35 + Math.max(0, stage - 1) * 0.08;
    if (stage === 1 || bossType === 'DOGE_KING') {
      return Math.max(5, Math.min(8, Math.round(18 * scale)));
    }
    return Math.max(8, Math.round(18 * scale));
  }

  public fireBossAttack(boss: BossEntity, player: { x: number; y: number }): BossBullet[] {
    boss.animState = 'ATTACK';
    boss.frameIndex = 2;
    boss.animTimer = 0.45;

    const bullets: BossBullet[] = [];
    const bx = boss.x;
    const by = boss.y + boss.size * 0.6;
    const dmgMult = boss.damageMultiplier || 1.0;

    if (boss.type === 'SHORT_WASP' || boss.type === 'DOGE_KING') {
      const angle = Math.atan2(player.y - by, player.x - bx);
      const speed = 4.6;
      for (const offset of [-0.22, 0.22]) {
        const slashAngle = angle + offset;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'CRESCENT_SLASH',
          x: bx,
          y: by,
          vx: Math.cos(slashAngle) * speed,
          vy: Math.sin(slashAngle) * speed,
          radius: 12,
          damage: Math.round(this.calculateSlashDamage(boss.stage || 1, boss.type) * dmgMult),
          color: '#ff1744',
          glowColor: '#ff9100',
          life: 4000,
          angle: slashAngle + Math.PI / 2,
          rotationSpeed: 3.5,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'WHALE_KING' || boss.type === 'WHALE_GOD') {
      // 16-way radial flower spread bullets with lifesteal
      const count = 16;
      const speed = 3.8;
      for (let i = 0; i < count; i++) {
        const angle = (i * Math.PI * 2) / count;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'SPREAD_ORB',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 7.5,
          damage: Math.round(24 * dmgMult),
          color: '#00e5ff',
          glowColor: '#00b0ff',
          life: 4200,
          isLifesteal: true,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
      boss.spreadWaveTimer = 0.35; // Trigger Wave 2 delayed
    } else if (boss.type === 'REAPER_UFO' || boss.type === 'PEPE_FROG') {
      const speed = 4.5;
      for (const spread of [-0.35, 0, 0.35]) {
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'STINGER',
          x: bx,
          y: by,
          vx: Math.sin(spread) * speed,
          vy: Math.cos(spread) * speed,
          radius: 6,
          damage: Math.round(22 * dmgMult),
          color: '#e040fb',
          glowColor: '#ea80fc',
          life: 3500,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'WIF_HAT') {
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      const speed = 4.8;
      const baseAngle = Math.atan2(player.y - by, player.x - bx);

      // Pincer curved arc beanie discs (curving trajectory)
      const configs = [
        { angleOffset: -0.32, curve: 1.8 },
        { angleOffset: 0.32, curve: -1.8 },
      ];
      if (isEnraged) {
        configs.push({ angleOffset: -0.55, curve: 1.4 });
        configs.push({ angleOffset: 0.55, curve: -1.4 });
      }

      for (let i = 0; i < configs.length; i++) {
        const cfg = configs[i];
        const bAng = baseAngle + cfg.angleOffset;
        const b: BossBullet = {
          id: `bb_beanie_${Date.now()}_${i}`,
          type: 'BEANIE_DISC',
          x: bx,
          y: by,
          vx: Math.cos(bAng) * speed,
          vy: Math.sin(bAng) * speed,
          radius: 13,
          damage: Math.round(20 * dmgMult),
          color: '#ff4081',
          glowColor: '#ff80ab',
          life: 4500,
          angle: bAng + Math.PI / 2,
          rotationSpeed: 8.5,
          curveFactor: cfg.curve,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Spawns STICKY_YARN hazard zone on arena
      const yarnX = Math.max(50, Math.min(this.arenaWidth - 50, player.x + (Math.random() - 0.5) * 80));
      const yarnY = Math.max(120, Math.min(this.arenaHeight - 80, player.y + (Math.random() - 0.5) * 80));
      this.hazardZones.push({
        id: `yarn_${Date.now()}`,
        type: 'STICKY_YARN',
        x: yarnX,
        y: yarnY,
        radius: 48,
        life: 4000,
        maxLife: 4000,
      });

      // Enraged Yarn Ball Mine
      if (isEnraged) {
        const yarnBombBullet: BossBullet = {
          id: `bb_yarn_${Date.now()}`,
          type: 'YARN_BOMB',
          x: yarnX,
          y: yarnY,
          vx: 0,
          vy: 0,
          radius: 16,
          damage: Math.round(25 * dmgMult),
          color: '#f50057',
          glowColor: '#ff4081',
          life: 1800,
        };
        bullets.push(yarnBombBullet);
        this.bossBullets.push(yarnBombBullet);

        if (!boss.bombs) boss.bombs = [];
        boss.bombs.push({
          id: `bomb_yarn_${Date.now()}`,
          x: yarnX,
          y: yarnY,
          timer: 1.5,
          maxTimer: 1.5,
          radius: 42,
          damage: Math.round(26 * dmgMult),
          type: 'YARN_BOMB',
        });
      }
    } else if (boss.type === 'FED_GOLEM') {
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      const count = isEnraged ? 6 : 4;
      const speed = 3.9;
      for (let i = 0; i < count; i++) {
        const angle = (i * Math.PI * 2) / count + (Math.random() - 0.5) * 0.3;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'FED_CASH',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 9,
          damage: Math.round(20 * dmgMult),
          color: '#00e676',
          glowColor: '#69f0ae',
          life: 4000,
          angle: angle + Math.PI / 2,
          rotationSpeed: 4.0,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Drop 2 Fed Bombs on field
      if (!boss.bombs) boss.bombs = [];
      boss.bombs.push({
        id: `bomb_${Date.now()}_1`,
        x: Math.max(40, Math.min(this.arenaWidth - 40, player.x + (Math.random() - 0.5) * 140)),
        y: Math.max(120, Math.min(this.arenaHeight - 80, player.y + (Math.random() - 0.5) * 140)),
        timer: 1.4,
        maxTimer: 1.4,
        radius: 45,
        damage: Math.round(28 * dmgMult),
        type: 'FED_BOMB',
      });

      // Berserk Stomp -> Inflation Shockwave Ring
      if (isEnraged && Math.random() < 0.65) {
        if (!boss.shockwaves) boss.shockwaves = [];
        boss.shockwaves.push({
          id: `sw_${Date.now()}`,
          x: bx,
          y: by,
          radius: 20,
          maxRadius: Math.max(this.arenaWidth, this.arenaHeight) * 0.75,
          speed: 160,
          thickness: 18,
          damage: Math.round(24 * dmgMult),
          color: '#00e676',
        });
      }
    } else if (boss.type === 'POW_TITAN' || boss.type === 'BONK_MASTER') {
      if (boss.type === 'BONK_MASTER') {
        if (!boss.shockwaves) boss.shockwaves = [];
        boss.shockwaves.push({
          id: `sw_bonk_${Date.now()}`,
          x: bx,
          y: by,
          radius: 15,
          maxRadius: 180,
          speed: 240,
          thickness: 12,
          damage: Math.round(26 * dmgMult),
          color: '#ff9100',
        });
      }
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      const count = isEnraged ? 5 : 3;
      const speed = 4.2;
      const baseAng = Math.atan2(player.y - by, player.x - bx);
      for (let i = 0; i < count; i++) {
        const spread = (i - (count - 1) / 2) * 0.28;
        const angle = baseAng + spread;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'HASH_MINE',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 8.5,
          damage: Math.round(25 * dmgMult),
          color: '#ff9100',
          glowColor: '#ff6d00',
          life: 3800,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Enraged: plant stationary POW mine near boss
      if (isEnraged && (!boss.bombs || boss.bombs.length < 4)) {
        if (!boss.bombs) boss.bombs = [];
        boss.bombs.push({
          id: `mine_${Date.now()}`,
          x: bx + (Math.random() - 0.5) * 160,
          y: by + (Math.random() - 0.5) * 100,
          timer: 3.5,
          maxTimer: 3.5,
          radius: 36,
          damage: Math.round(30 * dmgMult),
          type: 'POW_MINE',
        });
      }

      // Periodically trigger POW laser
      if (Math.random() < 0.35 && !boss.laser?.active) {
        this.triggerLaserAttack(boss, player);
      }
    } else if (boss.type === 'VOID_CEX' || boss.type === 'POPCAT_OVERLORD') {
      // Dark vortex homing bullets
      const angle = Math.atan2(player.y - by, player.x - bx);
      const count = 4;
      for (let i = 0; i < count; i++) {
        const bAng = angle + (i - 1.5) * 0.35;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'SPREAD_ORB',
          x: bx,
          y: by,
          vx: Math.cos(bAng) * 3.6,
          vy: Math.sin(bAng) * 3.6,
          radius: 8,
          damage: Math.round(26 * dmgMult),
          color: '#7c4dff',
          glowColor: '#b388ff',
          life: 4500,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Trigger Liquidation Hook if idle
      if (boss.hook && boss.hook.phase === 'IDLE' && Math.random() < 0.6) {
        boss.hook.active = true;
        boss.hook.phase = 'EXTENDING';
        boss.hook.startX = bx;
        boss.hook.startY = by;
        boss.hook.currX = bx;
        boss.hook.currY = by;
        boss.hook.targetX = player.x;
        boss.hook.targetY = player.y;
        boss.hook.hasCaughtPlayer = false;

        // Ground telegraph warning line
        if (!boss.telegraphs) boss.telegraphs = [];
        boss.telegraphs.push({
          id: `tel_hook_${Date.now()}`,
          type: 'LINE',
          x: bx,
          y: by,
          targetX: player.x,
          targetY: player.y,
          width: 8,
          duration: 0.6,
          maxDuration: 0.6,
          color: 'rgba(124, 77, 255, 0.4)',
        });
      }
    } else if (boss.type === 'FLOKI_VIKING') {
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      const angle = Math.atan2(player.y - by, player.x - bx);
      const speed = 4.6;

      // Dual Viking Axes with OUTWARD -> HOVERING (Blade Whirlpool) -> RECALLING (Recall Backstab)
      for (const off of [-0.28, 0.28]) {
        const axeAngle = angle + off;
        const b: BossBullet = {
          id: `bb_axe_${Date.now()}_${Math.random()}`,
          type: 'VIKING_AXE',
          x: bx,
          y: by,
          vx: Math.cos(axeAngle) * speed,
          vy: Math.sin(axeAngle) * speed,
          radius: 15,
          damage: Math.round(26 * dmgMult),
          color: '#00b0ff',
          glowColor: '#00e5ff',
          life: 5200,
          angle: axeAngle + Math.PI / 2,
          rotationSpeed: 9.0,
          phase: 'OUTWARD',
          targetX: player.x + Math.cos(axeAngle) * 20,
          targetY: player.y + Math.sin(axeAngle) * 20,
          hoverTimer: 1.2,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Enraged: also throw 2 ricochet axes that bounce off walls up to 3 times
      if (isEnraged) {
        for (const wallOff of [-0.65, 0.65]) {
          const rAng = angle + wallOff;
          const ricochetAxe: BossBullet = {
            id: `bb_axe_rico_${Date.now()}_${Math.random()}`,
            type: 'VIKING_AXE',
            x: bx,
            y: by,
            vx: Math.cos(rAng) * 4.2,
            vy: Math.sin(rAng) * 4.2,
            radius: 14,
            damage: Math.round(22 * dmgMult),
            color: '#80d8ff',
            glowColor: '#00e5ff',
            life: 4500,
            angle: rAng,
            rotationSpeed: 10.0,
            bounceRemaining: 3,
          };
          bullets.push(ricochetAxe);
          this.bossBullets.push(ricochetAxe);
        }
      }
    } else if (boss.type === 'MEME_SHIBA') {
      // 7-way chaotic bouncy scatter bullets
      const count = 7;
      const speed = 4.4;
      for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'MEME_DOGE',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 9,
          damage: Math.round(23 * dmgMult),
          color: '#ffd700',
          glowColor: '#ffab00',
          life: 3800,
          rotationSpeed: 5.0,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'MOODENG_TERROR') {
      // 12-way Water Splash Droplet Burst
      const count = 12;
      const speed = 4.0;
      for (let i = 0; i < count; i++) {
        const angle = (i * Math.PI * 2) / count + (Math.random() - 0.5) * 0.2;
        const b: BossBullet = {
          id: `bb_splash_${Date.now()}_${i}`,
          type: 'WATER_SPLASH',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 8,
          damage: Math.round(22 * dmgMult),
          color: '#00b0ff',
          glowColor: '#80d8ff',
          life: 3400,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'HFT_CYBORG') {
      // 4 high-speed razor cuts with cross angles
      const angle = Math.atan2(player.y - by, player.x - bx);
      const speed = 6.2;
      for (const off of [-0.25, 0.25]) {
        const bAng = angle + off;
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'HFT_SLICE',
          x: bx,
          y: by,
          vx: Math.cos(bAng) * speed,
          vy: Math.sin(bAng) * speed,
          radius: 11,
          damage: Math.round(27 * dmgMult),
          color: '#cfd8dc',
          glowColor: '#90a4ae',
          life: 3000,
          angle: bAng + Math.PI / 2,
          rotationSpeed: 6.0,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      // Blink adjacent to player
      if (Math.random() < 0.45) {
        boss.x = Math.max(50, Math.min(this.arenaWidth - 50, player.x + (Math.random() < 0.5 ? -90 : 90)));
        boss.y = Math.max(90, Math.min(260, player.y - 70));
        boss.hitFlashTimer = 250;
      }
    } else if (boss.type === 'WOJAK_TRADER') {
      // 2 Candlestick Barricades placed at left/right flanks + Vertical Wick Strike with ample dodging space
      const count = 2;
      for (let i = 0; i < count; i++) {
        const flankBaseX = i === 0 ? this.arenaWidth * 0.22 : this.arenaWidth * 0.78;
        const dropX = Math.max(30, Math.min(this.arenaWidth - 30, flankBaseX + (Math.random() - 0.5) * 30));
        const dropY = Math.max(140, Math.min(this.arenaHeight - 120, player.y - 40 + (Math.random() - 0.5) * 60));
        this.barricades.push({
          id: `barricade_${Date.now()}_${i}`,
          x: dropX,
          y: dropY,
          width: 16,
          height: 60,
          life: 2000,
          maxLife: 2000,
          damage: Math.round(18 * dmgMult),
        });

        const b: BossBullet = {
          id: `bb_candle_${Date.now()}_${i}`,
          type: 'RED_CANDLE_DROP',
          x: dropX,
          y: -20,
          vx: 0,
          vy: 5.5,
          radius: 10,
          damage: Math.round(20 * dmgMult),
          color: '#ff1744',
          glowColor: '#d50000',
          life: 800,
          angle: Math.PI / 2,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }

      this.triggerVerticalWickStrike(boss, player);
    } else if (boss.type === 'EXPLOIT_DEMON') {
      // 8-way dark runes spiral
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      const count = isEnraged ? 12 : 8;
      const speed = 4.0;
      for (let i = 0; i < count; i++) {
        const angle = (i * Math.PI * 2) / count + (boss.shootTimer || 0);
        const b: BossBullet = {
          id: `bb_${Date.now()}_${Math.random()}`,
          type: 'EXPLOIT_RUNES',
          x: bx,
          y: by,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          radius: 8,
          damage: Math.round(28 * dmgMult),
          color: '#ff1744',
          glowColor: '#d50000',
          life: 4200,
        };
        bullets.push(b);
        this.bossBullets.push(b);
      }
    } else if (boss.type === 'GIGACHAD_OMEGA') {
      // Golden Cross Laser Severance + Mogging Deflection Barrier (Tuned for fair dodging)
      this.triggerCrossLaser(boss);
      this.triggerMoggingBarrier(boss);

      if (!boss.shockwaves) boss.shockwaves = [];
      boss.shockwaves.push({
        id: `sw_chad_${Date.now()}`,
        x: bx,
        y: by,
        radius: 20,
        maxRadius: 140, // 140px localized aura (players keeping distance are 100% safe)
        speed: 180,
        thickness: 16,
        damage: Math.round(22 * dmgMult),
        color: '#ffd700',
      });
    } else if (boss.type === 'BLACK_SWAN_OMEGA') {
      const isEnraged = boss.hp < boss.maxHp * 0.5;
      if (Math.random() < 0.5) {
        const angle = Math.atan2(player.y - by, player.x - bx);
        const speed = 4.8;
        for (const offset of [-0.32, 0.32]) {
          const slashAngle = angle + offset;
          const b: BossBullet = {
            id: `bb_${Date.now()}_${Math.random()}`,
            type: 'CRESCENT_SLASH',
            x: bx,
            y: by,
            vx: Math.cos(slashAngle) * speed,
            vy: Math.sin(slashAngle) * speed,
            radius: 14,
            damage: Math.round(32 * dmgMult),
            color: '#d500f9',
            glowColor: '#aa00ff',
            life: 4200,
            angle: slashAngle + Math.PI / 2,
            rotationSpeed: 4.2,
          };
          bullets.push(b);
          this.bossBullets.push(b);
        }
      } else {
        const count = isEnraged ? 8 : 6;
        const speed = isEnraged ? 4.2 : 3.8;
        for (let i = 0; i < count; i++) {
          const angle = (i * Math.PI * 2) / count;
          const b: BossBullet = {
            id: `bb_${Date.now()}_${Math.random()}`,
            type: 'SPIRAL_SWAN',
            x: bx,
            y: by,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            radius: 6.5,
            damage: Math.round(30 * dmgMult),
            color: '#d500f9',
            glowColor: '#aa00ff',
            life: 4000,
          };
          bullets.push(b);
          this.bossBullets.push(b);
        }
      }
    }

    this.onPlaySound?.('die');
    return bullets;
  }

  public devourRetailEnemy(
    idx: number,
    boss: BossEntity,
    enemies: Enemy[],
    isTendrilDrain: boolean = false
  ): void {
    const e = enemies[idx];
    if (!e) return;

    enemies.splice(idx, 1);

    const mult = boss.damageMultiplier || 1.0;
    const baseHeal = isTendrilDrain ? 80 : 150;
    const healAmount = Math.floor(baseHeal * mult);
    const actualHeal = Math.min(healAmount, boss.maxHp - boss.hp);

    if (actualHeal > 0) {
      boss.hp += actualHeal;
      boss.healPulseTimer = 550;
      this.onPlaySound?.('boost');

      this.bossFloatingTexts.push({
        id: `devour_${Date.now()}_${Math.random()}`,
        x: boss.x + (Math.random() - 0.5) * 24,
        y: boss.y - boss.size - 20,
        text: isTendrilDrain ? `+${actualHeal} 虹吸清算!` : `+${actualHeal} 割韭菜! 🩸`,
        color: '#00e676',
        life: 1300,
        maxLife: 1300,
        vy: -38,
      });

      // Spawn siphon energy orbs
      for (let i = 0; i < 3; i++) {
        this.siphonOrbs.push({
          x: e.x,
          y: e.y,
          startX: e.x,
          startY: e.y,
          targetX: boss.x,
          targetY: boss.y + boss.size * 0.4,
          progress: 0,
          color: '#00e676',
        });
      }
    }
  }

  public applyBossLifesteal(
    boss: BossEntity,
    amount: number,
    playerPos?: { x: number; y: number }
  ): void {
    const mult = boss.damageMultiplier || 1.0;
    const scaledAmount = Math.floor(amount * mult);
    const healed = Math.min(scaledAmount, boss.maxHp - boss.hp);
    if (healed <= 0) return;

    boss.hp += healed;
    boss.healPulseTimer = 600;

    this.bossFloatingTexts.push({
      id: `heal_${Date.now()}_${Math.random()}`,
      x: boss.x + (Math.random() - 0.5) * 20,
      y: boss.y - boss.size - 18,
      text: `+${healed} HP`,
      color: '#00e676',
      life: 1200,
      maxLife: 1200,
      vy: -35,
    });

    if (playerPos) {
      for (let i = 0; i < 4; i++) {
        this.siphonOrbs.push({
          x: playerPos.x + (Math.random() - 0.5) * 16,
          y: playerPos.y + (Math.random() - 0.5) * 16,
          startX: playerPos.x,
          startY: playerPos.y,
          targetX: boss.x,
          targetY: boss.y,
          progress: 0,
          color: '#00e676',
        });
      }
    }

    this.onPlaySound?.('boost');
  }

  public updateWhaleDevour(boss: BossEntity, enemies: Enemy[], dtSec: number = 0.016): void {
    const mouthX = boss.x;
    const mouthY = boss.y + boss.size * 0.4;
    const suctionRadius = 240;
    const devourRadius = boss.size + 16;

    for (let j = enemies.length - 1; j >= 0; j--) {
      const e = enemies[j];
      if (e.isBoss) continue;

      const dist = Math.hypot(mouthX - e.x, mouthY - e.y);
      if (dist < suctionRadius) {
        const pullRatio = 1 - dist / suctionRadius;
        const pullSpeed = 70 + pullRatio * 150;
        const angle = Math.atan2(mouthY - e.y, mouthX - e.x);
        e.x += Math.cos(angle) * pullSpeed * dtSec;
        e.y += Math.sin(angle) * pullSpeed * dtSec;

        if (dist < devourRadius) {
          this.devourRetailEnemy(j, boss, enemies);
          continue;
        }
      }
    }

    // Whale King Siphon Tendrils
    boss.siphonTendrilTimer = (boss.siphonTendrilTimer || 0) + dtSec;
    const nearbyEnemies: { enemy: Enemy; dist: number; index: number }[] = [];
    for (let j = 0; j < enemies.length; j++) {
      const e = enemies[j];
      if (e.isBoss) continue;
      const dist = Math.hypot(mouthX - e.x, mouthY - e.y);
      if (dist < suctionRadius + 30) {
        nearbyEnemies.push({ enemy: e, dist, index: j });
      }
    }
    nearbyEnemies.sort((a, bMob) => a.dist - bMob.dist);
    const tethered = nearbyEnemies.slice(0, 3);

    for (const t of tethered) {
      const drainDamage = 28 * dtSec;
      t.enemy.hp -= drainDamage;

      if (Math.random() < 0.2) {
        this.siphonOrbs.push({
          x: t.enemy.x,
          y: t.enemy.y,
          startX: t.enemy.x,
          startY: t.enemy.y,
          targetX: mouthX,
          targetY: mouthY,
          progress: 0,
          color: '#00e676',
        });
      }

      const healAmt = drainDamage * 0.75;
      boss.hp = Math.min(boss.maxHp, boss.hp + healAmt);

      if (t.enemy.hp <= 0) {
        const idx = enemies.indexOf(t.enemy);
        if (idx !== -1) {
          this.devourRetailEnemy(idx, boss, enemies, true);
        }
      }
    }
  }

  public update(
    dt: number,
    player: { x: number; y: number; size?: number },
    enemies: Enemy[] = [],
    invulnerableTimer: number = 0
  ): void {
    const boss = this.currentBoss;
    if (!boss) return;

    const dtSec = dt / 1000;
    if (boss.hitFlashTimer > 0) boss.hitFlashTimer -= dt;
    if (boss.healPulseTimer && boss.healPulseTimer > 0) boss.healPulseTimer -= dt;

    // Clone System threshold check & update
    this.cloneSystem.checkCloneThresholds(boss, this.arenaWidth);
    this.cloneSystem.update(dt, player, this.arenaWidth, this.arenaHeight, (clone) => {
      this.fireCloneAttack(clone, player);
    });

    // Berserk threshold check (Phase 2 at HP <= 50%)
    if (!boss.isBerserk && boss.hp <= boss.maxHp * 0.5) {
      boss.isBerserk = true;
      boss.hitFlashTimer = 600;
      this.bossFloatingTexts.push({
        id: `berserk_${Date.now()}`,
        x: boss.x,
        y: boss.y - boss.size - 25,
        text: '🔥 暴怒狀態 BERSERK! 🔥',
        color: '#ff1744',
        life: 1600,
        maxLife: 1600,
        vy: -32,
      });
      this.onPlaySound?.('boost');
    }

    // Bombs physics & countdown
    if (boss.bombs) {
      const pSize = player.size ?? 18;
      for (let i = boss.bombs.length - 1; i >= 0; i--) {
        const bomb = boss.bombs[i];
        bomb.timer -= dtSec;
        if (bomb.timer <= 0 && !bomb.exploded) {
          bomb.exploded = true;
          const dist = Math.hypot(player.x - bomb.x, player.y - bomb.y);
          if (dist < bomb.radius + pSize && invulnerableTimer <= 0) {
            this.onPlayerDamage?.(bomb.damage);
          }
          // Emit 4-way cross explosion bullets
          const speed = 4.2;
          for (let k = 0; k < 4; k++) {
            const angle = (k * Math.PI) / 2;
            this.bossBullets.push({
              id: `bblast_${Date.now()}_${k}`,
              type: bomb.type === 'FED_BOMB' ? 'FED_CASH' : 'HASH_MINE',
              x: bomb.x,
              y: bomb.y,
              vx: Math.cos(angle) * speed,
              vy: Math.sin(angle) * speed,
              radius: 7,
              damage: Math.round(bomb.damage * 0.7),
              color: bomb.type === 'FED_BOMB' ? '#00e676' : '#ff9100',
              glowColor: bomb.type === 'FED_BOMB' ? '#69f0ae' : '#ff6d00',
              life: 2500,
            });
          }
          boss.bombs.splice(i, 1);
        }
      }
    }

    // Shockwaves expansion & player contact
    if (boss.shockwaves) {
      const pSize = player.size ?? 18;
      for (let i = boss.shockwaves.length - 1; i >= 0; i--) {
        const sw = boss.shockwaves[i];
        sw.radius += sw.speed * dtSec;
        const dist = Math.hypot(player.x - sw.x, player.y - sw.y);
        if (!sw.hitPlayer && Math.abs(dist - sw.radius) < sw.thickness / 2 + pSize) {
          if (invulnerableTimer <= 0) {
            sw.hitPlayer = true;
            this.onPlayerDamage?.(sw.damage);
          }
        }
        if (sw.radius >= sw.maxRadius) {
          boss.shockwaves.splice(i, 1);
        }
      }
    }

    // Liquidation Hook update (CEX Void)
    if (boss.hook && boss.hook.active) {
      const hk = boss.hook;
      const pSize = player.size ?? 18;
      if (hk.phase === 'EXTENDING') {
        const dx = hk.targetX - hk.currX;
        const dy = hk.targetY - hk.currY;
        const dist = Math.hypot(dx, dy);
        const step = hk.speed * 60 * dtSec;
        if (dist <= step) {
          hk.currX = hk.targetX;
          hk.currY = hk.targetY;
          hk.phase = 'RETRACTING';
        } else {
          hk.currX += (dx / dist) * step;
          hk.currY += (dy / dist) * step;
        }

        const pDist = Math.hypot(player.x - hk.currX, player.y - hk.currY);
        if (pDist < pSize + 16 && !hk.hasCaughtPlayer) {
          hk.hasCaughtPlayer = true;
          if (invulnerableTimer <= 0) {
            this.onPlayerDamage?.(hk.damage);
          }
          hk.phase = 'RETRACTING';
        }
      } else if (hk.phase === 'RETRACTING') {
        const dx = hk.startX - hk.currX;
        const dy = hk.startY - hk.currY;
        const dist = Math.hypot(dx, dy);
        const step = hk.speed * 60 * dtSec;
        if (dist <= step) {
          hk.currX = hk.startX;
          hk.currY = hk.startY;
          hk.phase = 'IDLE';
          hk.active = false;
        } else {
          hk.currX += (dx / dist) * step;
          hk.currY += (dy / dist) * step;
        }

        if (hk.hasCaughtPlayer) {
          player.x += (boss.x - player.x) * (dtSec * 4);
          player.y += (boss.y - player.y) * (dtSec * 4);
        }
      }
    }

    // Telegraph countdown
    if (boss.telegraphs) {
      for (let i = boss.telegraphs.length - 1; i >= 0; i--) {
        boss.telegraphs[i].duration -= dtSec;
        if (boss.telegraphs[i].duration <= 0) {
          boss.telegraphs.splice(i, 1);
        }
      }
    }

    // Whale King / Whale God Devour & Swarm Logic
    if (boss.type === 'WHALE_KING' || boss.type === 'WHALE_GOD') {
      boss.whaleMobSpawnTimer = (boss.whaleMobSpawnTimer || 0) + dtSec;
      if (boss.whaleMobSpawnTimer >= 4.5) {
        boss.whaleMobSpawnTimer = 0;
        if (enemies.length < 20) {
          const spawnCount = 3 + Math.floor(Math.random() * 3);
          this.onSpawnRetailMob?.(spawnCount);
        }
      }

      this.updateWhaleDevour(boss, enemies, dtSec);

      // Delayed 2nd wave spread bullets
      if (boss.spreadWaveTimer && boss.spreadWaveTimer > 0) {
        boss.spreadWaveTimer -= dtSec;
        if (boss.spreadWaveTimer <= 0) {
          boss.spreadWaveTimer = 0;
          const speed = 3.6;
          const bx = boss.x;
          const by = boss.y + boss.size * 0.6;
          const dmgMult = boss.damageMultiplier || 1.0;
          for (let i = 0; i < 8; i++) {
            const spread = (i - 3.5) * 0.22;
            this.bossBullets.push({
              id: `bb_${Date.now()}_${Math.random()}`,
              type: 'SPREAD_ORB',
              x: bx,
              y: by,
              vx: Math.sin(spread) * speed,
              vy: Math.cos(spread) * speed,
              radius: 7.0,
              damage: Math.round(22 * dmgMult),
              color: '#80d8ff',
              glowColor: '#00e5ff',
              life: 4200,
              isLifesteal: true,
            });
          }
          this.onPlaySound?.('die');
        }
      }
    }

    // Laser Beam Logic
    if (boss.laser && boss.laser.active) {
      const laser = boss.laser;
      laser.startX = boss.x;
      laser.startY = boss.y + boss.size * 0.7;

      if (laser.phase === 'AIMING') {
        laser.timer -= dtSec;
        const targetAng = Math.atan2(player.y - laser.startY, player.x - laser.startX);
        laser.angle += (targetAng - laser.angle) * Math.min(1.0, dtSec * 4.5);

        if (laser.timer <= 0) {
          laser.phase = 'FIRING';
          laser.timer = 1.3;
          laser.sweepSpeed = player.x > boss.x ? 0.35 : -0.35;
          this.onPlaySound?.('die');
        }
      } else if (laser.phase === 'FIRING') {
        laser.timer -= dtSec;
        laser.angle += laser.sweepSpeed * dtSec;

        const cosA = Math.cos(laser.angle);
        const sinA = Math.sin(laser.angle);
        const vx = player.x - laser.startX;
        const vy = player.y - laser.startY;
        const proj = vx * cosA + vy * sinA;
        if (proj > 0 && proj < 1200) {
          const perpDist = Math.abs(vx * sinA - vy * cosA);
          const pSize = player.size ?? 18;
          if (perpDist < laser.width / 2 + pSize && invulnerableTimer <= 0) {
            this.onPlayerDamage?.(laser.damage);
          }
        }

        if (laser.timer <= 0) {
          laser.phase = 'NONE';
          laser.active = false;
        }
      }
    }

    // Regular Attack timer (when in FORMATION_HOVER)
    if (boss.state === 'FORMATION_HOVER' && !boss.laser?.active) {
      boss.shootTimer += dtSec;
      let shootInterval =
        boss.type === 'BLACK_SWAN_OMEGA'
          ? 1.6
          : boss.type === 'REAPER_UFO'
          ? 2.2
          : (boss.type === 'WHALE_KING' || boss.type === 'WHALE_GOD')
          ? 2.8
          : 2.2;
      const isEnraged = boss.hp / boss.maxHp <= 0.4;
      if (isEnraged) shootInterval *= 0.8;
      const stagePaceMult = Math.max(0.68, 1.0 - (boss.stage - 1) * 0.035);
      shootInterval *= stagePaceMult;
      if (boss.shootTimer >= shootInterval) {
        boss.shootTimer = 0;
        this.fireBossAttack(boss, player);
      }
    }

    // Dynamic Mobility & State Machine Delegation
    this.motionController.update(boss, dt, {
      arenaWidth: this.arenaWidth,
      arenaHeight: this.arenaHeight,
      player,
      invulnerableTimer,
      onPlayerDamage: this.onPlayerDamage,
      onPlaySound: this.onPlaySound,
      onWallImpact: (x, y, nx, ny, b) => this.handleWallImpact(b, x, y, nx, ny),
    });

    this.updateBossVisualEffects(dt);
    this.checkPhaseDrops(boss);
  }

  public checkPhaseDrops(boss: BossEntity): void {
    const pct = boss.hp / boss.maxHp;
    const thresholds = [
      { key: '75', val: 0.75 },
      { key: '50', val: 0.50 },
      { key: '25', val: 0.25 },
    ];
    for (const t of thresholds) {
      if (pct <= t.val && !this.phaseHeartDrops[t.key]) {
        this.phaseHeartDrops[t.key] = true;
        this.onDropHeart?.(boss.x + (Math.random() - 0.5) * 40, boss.y + 30);
        this.bossFloatingTexts.push({
          id: `ft_supply_${Date.now()}_${t.key}`,
          x: boss.x,
          y: boss.y - 30,
          text: '💚 醫療急救空投 (HEART DROP)!',
          color: '#00e676',
          life: 1600,
          maxLife: 1600,
          vy: -0.7,
        });
      }
    }
  }

  public updateBossVisualEffects(dt: number): void {
    const dtSec = dt / 1000;

    // Siphon Orbs update with smooth Bezier arc
    const boss = this.currentBoss;
    for (let i = this.siphonOrbs.length - 1; i >= 0; i--) {
      const orb = this.siphonOrbs[i];
      orb.progress += dtSec * 2.2;
      if (boss) {
        orb.targetX = boss.x;
        orb.targetY = boss.y;
      }
      const t = Math.min(1.0, orb.progress);
      const midX = (orb.startX + orb.targetX) / 2 + Math.sin(t * Math.PI) * 40;
      const midY = (orb.startY + orb.targetY) / 2 - 20;
      const omt = 1 - t;
      orb.x = omt * omt * orb.startX + 2 * omt * t * midX + t * t * orb.targetX;
      orb.y = omt * omt * orb.startY + 2 * omt * t * midY + t * t * orb.targetY;

      if (orb.progress >= 1.0) {
        this.siphonOrbs.splice(i, 1);
      }
    }

    // Boss Floating Texts update
    for (let i = this.bossFloatingTexts.length - 1; i >= 0; i--) {
      const ft = this.bossFloatingTexts[i];
      ft.life -= dt;
      ft.y += ft.vy * dtSec;
      if (ft.life <= 0) {
        this.bossFloatingTexts.splice(i, 1);
      }
    }
  }

  public updateBullets(
    dt: number,
    player: { x: number; y: number; size: number },
    onHitPlayer?: (b: BossBullet) => void
  ): void {
    const dtSec = dt / 1000;
    const boss = this.currentBoss;

    for (let i = this.bossBullets.length - 1; i >= 0; i--) {
      const b = this.bossBullets[i];
      b.life -= dt;

      // 1. BEANIE_DISC Lateral Curving Ballistics
      if (b.type === 'BEANIE_DISC' && b.curveFactor) {
        const speed = Math.hypot(b.vx, b.vy);
        if (speed > 0) {
          const currentAngle = Math.atan2(b.vy, b.vx);
          const newAngle = currentAngle + b.curveFactor * dtSec;
          b.vx = Math.cos(newAngle) * speed;
          b.vy = Math.sin(newAngle) * speed;
          b.angle = newAngle + Math.PI / 2;
        }
      }

      // 2. VIKING_AXE State Machine: OUTWARD -> HOVERING -> RECALLING
      if (b.type === 'VIKING_AXE' && b.phase) {
        if (b.phase === 'OUTWARD') {
          if (b.targetX !== undefined && b.targetY !== undefined) {
            const distToTarget = Math.hypot(b.targetX - b.x, b.targetY - b.y);
            if (distToTarget < 25 || b.life <= 3800) {
              b.phase = 'HOVERING';
              b.vx = 0;
              b.vy = 0;
              b.rotationSpeed = 16.0; // High speed blade whirlpool
            }
          }
        } else if (b.phase === 'HOVERING') {
          if (b.hoverTimer !== undefined) {
            b.hoverTimer -= dtSec;
            if (b.hoverTimer <= 0) {
              b.phase = 'RECALLING';
            }
          }
        }
        if (b.phase === 'RECALLING') {
          if (boss) {
            const dx = boss.x - b.x;
            const dy = boss.y - b.y;
            const distToBoss = Math.hypot(dx, dy) || 1;
            if (distToBoss < 30) {
              // Caught by Boss
              this.bossBullets.splice(i, 1);
              continue;
            }
            const recallSpeed = 8.8; // 2.2x speed recall
            b.vx = (dx / distToBoss) * recallSpeed;
            b.vy = (dy / distToBoss) * recallSpeed;
            b.angle = Math.atan2(b.vy, b.vx) + Math.PI / 2;
          }
        }
      }

      // 3. Wall Ricochet for Axes
      if (b.bounceRemaining && b.bounceRemaining > 0) {
        if ((b.x <= 20 && b.vx < 0) || (b.x >= this.arenaWidth - 20 && b.vx > 0)) {
          b.vx = -b.vx;
          b.bounceRemaining--;
        }
        if ((b.y <= 40 && b.vy < 0) || (b.y >= this.arenaHeight - 30 && b.vy > 0)) {
          b.vy = -b.vy;
          b.bounceRemaining--;
        }
      }

      b.x += b.vx * dtSec * 60;
      b.y += b.vy * dtSec * 60;
      if (b.angle !== undefined && b.rotationSpeed !== undefined) {
        b.angle += b.rotationSpeed * dtSec;
      }

      // Out of bounds or dead (if not hovering or recalling)
      if (
        b.life <= 0 ||
        (b.phase !== 'HOVERING' &&
          b.phase !== 'RECALLING' &&
          (b.x < -60 || b.x > this.arenaWidth + 60 || b.y < -60 || b.y > this.arenaHeight + 60))
      ) {
        this.bossBullets.splice(i, 1);
        continue;
      }

      // Player collision check
      const dist = Math.hypot(player.x - b.x, player.y - b.y);
      if (dist < player.size + b.radius) {
        if (b.phase === 'HOVERING') {
          // Hovering blades damage player on contact without disappearing
          onHitPlayer?.(b);
        } else {
          this.bossBullets.splice(i, 1);
          onHitPlayer?.(b);
        }
      }
    }

    // 4. Update Hazard Zones (Yarn slow, water puddles)
    for (let i = this.hazardZones.length - 1; i >= 0; i--) {
      const z = this.hazardZones[i];
      z.life -= dt;
      if (z.life <= 0) {
        this.hazardZones.splice(i, 1);
      }
    }

    // 5. Update Candlestick Barricades (Wojak)
    for (let i = this.barricades.length - 1; i >= 0; i--) {
      const bar = this.barricades[i];
      bar.life -= dt;
      if (bar.life <= 0) {
        this.barricades.splice(i, 1);
        continue;
      }
      // Collision with player
      const halfW = bar.width / 2;
      const halfH = bar.height / 2;
      if (
        player.x >= bar.x - halfW - player.size &&
        player.x <= bar.x + halfW + player.size &&
        player.y >= bar.y - halfH - player.size &&
        player.y <= bar.y + halfH + player.size
      ) {
        this.onPlayerDamage?.(bar.damage * dtSec * 2);
      }
    }

    // 6. Update Wick Strike
    this.updateWickStrike(dt, player);

    // 7. Update Cross Laser
    if (this.crossLaser && this.crossLaser.active) {
      this.crossLaser.timer -= dtSec;
      if (this.crossLaser.phase === 'AIMING' && this.crossLaser.timer <= 0) {
        this.crossLaser.phase = 'FIRING';
        this.crossLaser.timer = 1.2;
        this.onPlaySound?.('die');
      } else if (this.crossLaser.phase === 'FIRING') {
        if (this.crossLaser.timer <= 0) {
          this.crossLaser.active = false;
        } else {
          this.checkCrossLaserCollision(player);
        }
      }
    }

    // 8. Update Mogging Barrier & Deflection
    if (boss && boss.isDeflectingProjectiles && boss.specialCooldown) {
      boss.specialCooldown -= dtSec;
      if (boss.specialCooldown <= 0) {
        boss.isDeflectingProjectiles = false;
        boss.gravityPullActive = false;
      } else {
        this.applyGravityPull(boss, player, dt);
      }
    }
  }

  public resetBoss(): void {
    this.clear();
    this.phaseHeartDrops = { '75': false, '50': false, '25': false };
  }

  public clear(): void {
    this.currentBoss = null;
    this.bossBullets = [];
    this.siphonOrbs = [];
    this.bossFloatingTexts = [];
    this.cloneSystem.clear();
    this.phaseHeartDrops = { '75': false, '50': false, '25': false };
    this.hazardZones = [];
    this.barricades = [];
    this.crossLaser = null;
    this.wickStrike = null;
  }
}
