import { Enemy } from '../types.ts';

export interface EnemyMotionHost {
  px: number;
  py: number;
  freezeTimer: number;
  elapsedTime: number;
  enemies: Enemy[];
  activeEvent: { effect: { enemySpeedMult?: number } } | null;
}

export class EnemyMotionManager {
  public static update(host: EnemyMotionHost, dt: number): void {
    this.updateEliteAuras(host.enemies);

    const dtScale = Math.min(2.0, Math.max(0.1, dt / 16.6667));
    for (let i = host.enemies.length - 1; i >= 0; i--) {
      const e = host.enemies[i];
      const dx = host.px - e.x;
      const dy = host.py - e.y;
      const dist = Math.hypot(dx, dy);

      if (dist > 0 && host.freezeTimer <= 0) {
        let spd = e.speed;
        if (host.activeEvent?.effect.enemySpeedMult && !e.isBoss) {
          spd *= host.activeEvent.effect.enemySpeedMult;
        }
        if (e.speedModifier && !e.isBoss && !e.isElite) {
          spd *= e.speedModifier;
        }
        let moveX = (dx / dist) * spd * dtScale;
        let moveY = (dy / dist) * spd * dtScale;

        if (e.type === 'BLACK_SWAN') {
          const wave = Math.sin(host.elapsedTime * 4 + e.x * 0.05) * 0.7 * dtScale;
          moveX += (-dy / dist) * wave;
          moveY += (dx / dist) * wave;
        }
        e.x += moveX;
        e.y += moveY;
      }
      if (e.type === 'LIQUIDATION_REAPER') {
        e.rotation = (e.rotation || 0) + 0.12;
      }
    }
  }

  public static updateEliteAuras(enemies: Enemy[]): void {
    const elites = enemies.filter((e) => e.isElite && !e.isBoss);
    if (elites.length === 0) {
      for (const e of enemies) {
        if (!e.isBoss && !e.isElite) e.speedModifier = 1.0;
      }
      return;
    }

    for (const e of enemies) {
      if (e.isBoss || e.isElite) continue;
      let spdMult = 1.0;
      for (const elite of elites) {
        if (elite.auraType === 'SPEED_AURA') {
          const dist = Math.hypot(e.x - elite.x, e.y - elite.y);
          if (dist <= (elite.auraRadius || 160)) {
            spdMult = Math.max(spdMult, 1.35);
          }
        }
      }
      e.speedModifier = spdMult;
    }
  }
}
