import { IWeapon } from './IWeapon.ts';
import { VenomWeapon } from './VenomWeapon.ts';
import { OrbiterWeapon } from './OrbiterWeapon.ts';

export class WeaponManager {
  private weapons: Map<string, IWeapon> = new Map();

  public venom: VenomWeapon;
  public orbiter: OrbiterWeapon;

  constructor() {
    this.venom = new VenomWeapon();
    this.orbiter = new OrbiterWeapon();

    this.weapons.set(this.venom.id, this.venom);
    this.weapons.set(this.orbiter.id, this.orbiter);
  }

  public register(weapon: IWeapon): void {
    this.weapons.set(weapon.id, weapon);
  }

  public get<T extends IWeapon>(id: string): T | undefined {
    return this.weapons.get(id) as T | undefined;
  }

  public getAll(): IWeapon[] {
    return Array.from(this.weapons.values());
  }

  public updateAll(dt: number, engine: any): void {
    for (const weapon of this.weapons.values()) {
      weapon.update(dt, engine);
    }
  }

  public resetAll(): void {
    for (const weapon of this.weapons.values()) {
      weapon.reset();
    }
  }
}
