import { SurvivorEngine } from '../SurvivorEngine.ts';

export class CombatResolver {
  public static resolveAll(engine: SurvivorEngine): void {
    // 1. Player & Boss Bullets
    engine.bossCombatController.updateBullets(
      16.6,
      { x: engine.px, y: engine.py, size: engine.playerSize },
      (b) => {
        if (engine.invulnerableTimer <= 0) {
          const raw = b.damage;
          const dmg = Math.max(3, Math.floor(raw * (1 - Math.min(0.4, engine.damageReduction))));
          engine.hp -= dmg;
          engine.invulnerableTimer = 550;
          engine.soundManager.playDie();
          engine.particleSystem.emitDeath(b.x, b.y);
          (engine as any).callbacks.onHpChange(Math.max(0, engine.hp), engine.maxHp);
          if (
            b.isLifesteal &&
            engine.currentBoss &&
            (engine.currentBoss.type === 'WHALE_KING' || engine.currentBoss.type === 'WHALE_GOD')
          ) {
            engine.bossCombatController.applyBossLifesteal(engine.currentBoss, 120, {
              x: engine.px,
              y: engine.py,
            });
          }
          if (engine.hp <= 0) (engine as any).handleGameOver();
        }
      }
    );

    // 2. Player & Enemies (Normal Contact & Rocket Ramming)
    engine.collisionSystem.resolvePlayerEnemyCollisions({
      player: {
        x: engine.px,
        y: engine.py,
        size: engine.playerSize,
        damageReduction: engine.damageReduction,
      },
      enemies: engine.enemies,
      rocketTimer: engine.rocketTimer,
      freezeTimer: engine.freezeTimer,
      invulnerableTimer: engine.invulnerableTimer,
      getMonsterContactDamage: (e) => engine.getMonsterContactDamage(e),
      onPlayerDamage: (finalDmg) => {
        engine.hp -= finalDmg;
        engine.invulnerableTimer = 650;
        engine.soundManager.playDie();
        (engine as any).callbacks.onHpChange(Math.max(0, engine.hp), engine.maxHp);
        if (engine.hp <= 0) (engine as any).handleGameOver();
      },
      onRocketHitEnemy: (idx, e, dmg) => {
        e.hp -= dmg;
        engine.particleSystem.emitDeath(e.x, e.y);
        if (e.hp <= 0) engine.killEnemy(idx);
      },
    });

    // 3. Rocket Ramming vs Boss
    engine.collisionSystem.resolveRocketBossCollision({
      player: { x: engine.px, y: engine.py, size: engine.playerSize },
      boss: engine.currentBoss,
      rocketTimer: engine.rocketTimer,
      onBossHit: (boss, dmg) => {
        boss.hp -= dmg;
        boss.hitFlashTimer = 200;
        engine.particleSystem.emitDeath(boss.x, boss.y);
        if (boss.hp <= 0) engine.defeatBoss();
      },
    });

    // 4. Projectiles vs Boss, Clones & Enemies
    engine.collisionSystem.resolveProjectileCollisions({
      projectiles: engine.projectileSystem.activeProjectiles,
      enemies: engine.enemies,
      boss: engine.currentBoss,
      clones: engine.bossCombatController.cloneSystem.clones,
      damageMultiplier: engine.damageMultiplier,
      onHitBoss: (boss, dmg, p) => {
        if (boss.isDeflectingProjectiles) {
          engine.soundManager.playBoost();
          engine.particleSystem.emitDeath(p.x, p.y);
          p.vx = -p.vx * 1.2;
          p.vy = -p.vy * 1.2;
          engine.bossCombatController.bossFloatingTexts.push({
            id: `mog_${Date.now()}_${Math.random()}`,
            x: boss.x + (Math.random() - 0.5) * 40,
            y: boss.y - 20,
            text: 'MOGGED! 🗿',
            color: '#ffd700',
            life: 800,
            maxLife: 800,
            vy: -35,
          });
          return;
        }
        const cloneSys = engine.bossCombatController.cloneSystem;
        if (cloneSys.isBossImmune(boss)) {
          cloneSys.handleBossShieldDamage(boss, dmg);
          boss.hitFlashTimer = 100;
          engine.particleSystem.emitEat(p.x, p.y);
          engine.bossCombatController.deflectBossDamage(boss, p.x, p.y, dmg);
        } else {
          boss.hp -= dmg;
          boss.hitFlashTimer = 120;
          engine.particleSystem.emitEat(p.x, p.y);
          if (boss.hp <= 0) engine.defeatBoss();
        }
      },
      onHitClone: (clone, dmg, p) => {
        if (engine.currentBoss) {
          engine.bossCombatController.cloneSystem.handleCloneDamage(engine.currentBoss, clone, dmg);
          engine.particleSystem.emitEat(p.x, p.y);
          engine.bossCombatController.deflectBossDamage(engine.currentBoss, clone.x, clone.y, dmg);
        }
      },
      onHitEnemy: (j, e, dmg, p) => {
        e.hp -= dmg;
        engine.particleSystem.emitEat(p.x, p.y);
        if (e.hp <= 0) engine.killEnemy(j);
      },
    });
  }
}
