import { SoundManager } from '../../audio/SoundManager.ts';
import { ParticleSystem } from '../../engine/ParticleSystem.ts';
import { MACRO_EVENTS, MacroEvent } from './data/events.ts';
import { TALENTS_POOL } from './data/talents.ts';

export * from './types.ts';
import {
  EnemyType,
  BossEntity,
  BossFloatingText,
  SiphonOrb,
  BossBullet,
  BattlefieldPickup,
  Enemy,
  Projectile,
  ExpGem,
  SurvivorCallbacks,
} from './types.ts';
import { WeaponManager } from './weapons/WeaponManager.ts';
import { SurvivorRenderer } from './rendering/SurvivorRenderer.ts';
import { WaveDirector } from './monsters/WaveDirector.ts';
import { LootManager } from './pickups/LootManager.ts';
import { BossCombatController } from './combat/BossCombatController.ts';
import { CollisionSystem } from './systems/CollisionSystem.ts';
import { ProjectileSystem } from './systems/ProjectileSystem.ts';
import { TalentApplier } from './systems/TalentApplier.ts';
import { PickupApplier } from './systems/PickupApplier.ts';
import { BossLifecycleManager } from './systems/BossLifecycleManager.ts';
import { MacroEventScheduler } from './systems/MacroEventScheduler.ts';
import { PlayerMotionManager } from './systems/PlayerMotionManager.ts';
import { SurvivorLifecycleManager } from './systems/SurvivorLifecycleManager.ts';
import { LevelCurves } from './progression/LevelCurves.ts';
import { CombatResolver } from './systems/CombatResolver.ts';
import { EnemyMotionManager } from './systems/EnemyMotionManager.ts';
import { EnemyDefeatProcessor } from './systems/EnemyDefeatProcessor.ts';

/**
 * SurvivorEngine (Pure Facade & Orchestrator)
 * High-cohesion, low-coupling facade coordinating sub-controllers for SNEK Survivor.
 */
export class SurvivorEngine {
  public canvas: HTMLCanvasElement;
  public ctx: CanvasRenderingContext2D;
  public callbacks: SurvivorCallbacks;
  public soundManager: SoundManager;
  public particleSystem: ParticleSystem;

  public width: number = 440;
  public height: number = 600;

  // Sub-Controllers & Systems
  public waveDirector: WaveDirector;
  public lootManager: LootManager;
  public bossCombatController: BossCombatController;
  public collisionSystem: CollisionSystem = new CollisionSystem();
  public projectileSystem: ProjectileSystem = new ProjectileSystem();
  public weaponManager: WeaponManager = new WeaponManager();
  private renderer: SurvivorRenderer = new SurvivorRenderer();

  // Player State
  public px: number = 220;
  public py: number = 300;
  public pvx: number = 0;
  public pvy: number = 0;
  public hp: number = 100;
  public maxHp: number = 100;
  public speed: number = 2.4;
  public playerSize: number = 18;
  public damageReduction: number = 0;
  public damageMultiplier: number = 1.0;
  public magnetRadius: number = 65;
  public hasCompoundInterest: boolean = false;
  public invulnerableTimer: number = 0;

  // Stats & Progression
  public level: number = 1;
  public exp: number = 0;
  public nextExp: number = 6;
  public kills: number = 0;
  public elapsedTime: number = 0;

  // Macro Events
  public activeEvent: MacroEvent | null = null;
  public eventTimer: number = 0;
  public nextEventTimer: number = 18;

  // Entities & Getters/Setters
  public enemies: Enemy[] = [];
  public pickups: BattlefieldPickup[] = [];
  public get projectiles(): Projectile[] { return this.projectileSystem.activeProjectiles; }
  public set projectiles(v: Projectile[]) { this.projectileSystem.activeProjectiles = v; }
  public get expGems(): ExpGem[] { return this.lootManager.gems; }
  public set expGems(v: ExpGem[]) { this.lootManager.gems = v; }
  public get currentBoss(): BossEntity | null { return this.bossCombatController.currentBoss; }
  public set currentBoss(v: BossEntity | null) { this.bossCombatController.currentBoss = v; }
  public get bossBullets(): BossBullet[] { return this.bossCombatController.bossBullets; }
  public set bossBullets(v: BossBullet[]) { this.bossCombatController.bossBullets = v; }
  public get bossFloatingTexts(): BossFloatingText[] { return this.bossCombatController.bossFloatingTexts; }
  public set bossFloatingTexts(v: BossFloatingText[]) { this.bossCombatController.bossFloatingTexts = v; }
  public get siphonOrbs(): SiphonOrb[] { return this.bossCombatController.siphonOrbs; }
  public set siphonOrbs(v: SiphonOrb[]) { this.bossCombatController.siphonOrbs = v; }

  // Boss & Progression Status
  public bossWarningTimer: number = 0;
  public stageClearTimer: number = 0;
  public stageClearTitle: string = '';
  public bossDefeatedCount: number = 0;
  public stage: number = 1;
  public stageAlert: { stage: number; title: string; subtitle: string; timer: number; maxTimer: number } | null = null;

  // Active Pickups & Fever Timers
  public rocketTimer: number = 0;
  public freezeTimer: number = 0;
  public nukeFlashTimer: number = 0;
  public magnetAllTimer: number = 0;
  public comboMeter: number = 0;
  public isFever: boolean = false;
  public feverTimer: number = 0;
  public comboIdleTimer: number = 0;

  // Ambient Candlesticks for Trading Floor
  private bgCandles: { x: number; y: number; h: number; isUp: boolean }[] = [];

  // Lifecycle
  public isRunning: boolean = false;
  public isPaused: boolean = false;
  public isSleeping: boolean = false;
  public canRevive: boolean = true;
  private hasRenderedPauseFrame: boolean = false;
  private lastTime: number = 0;
  private animFrameId: number | null = null;
  private onVisibilityChangeHandler: (() => void) | null = null;

  // SNEK Mascot Sprite
  public headImage: HTMLImageElement = new Image();
  public imageLoaded: boolean = false;

  // Weapon Strategy Delegations
  public get venomCount(): number { return this.weaponManager.venom.count; }
  public set venomCount(v: number) { this.weaponManager.venom.count = v; }
  public get venomCooldown(): number { return this.weaponManager.venom.cooldown; }
  public set venomCooldown(v: number) { this.weaponManager.venom.cooldown = v; }
  public get orbitCount(): number { return this.weaponManager.orbiter.count; }
  public set orbitCount(v: number) { this.weaponManager.orbiter.count = v; }
  public get orbitSpeed(): number { return this.weaponManager.orbiter.speed; }
  public set orbitSpeed(v: number) { this.weaponManager.orbiter.speed = v; }
  public get orbitAngle(): number { return this.weaponManager.orbiter.angle; }
  public set orbitAngle(v: number) { this.weaponManager.orbiter.angle = v; }

  constructor(canvas: HTMLCanvasElement, callbacks: SurvivorCallbacks) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('No 2D context');
    this.ctx = ctx;
    this.callbacks = callbacks;
    this.soundManager = new SoundManager();
    this.particleSystem = new ParticleSystem();

    this.waveDirector = new WaveDirector({
      arenaWidth: this.width,
      arenaHeight: this.height,
      baseSpawnInterval: 1400,
      onSpawnEnemy: (enemy: Enemy) => this.enemies.push(enemy),
    });

    this.lootManager = new LootManager({
      onExpCollected: (amount: number, gem: ExpGem) => {
        this.collectExp(amount);
        if (gem && (gem.tier === 'BOSS' || gem.tier === 'ELITE')) this.particleSystem.emitSuperEat(this.px, this.py);
        else this.particleSystem.emitEat(this.px, this.py);
      },
    });

    this.bossCombatController = new BossCombatController({
      arenaWidth: this.width,
      arenaHeight: this.height,
      onBossDefeated: () => this.defeatBoss(),
      onPlayerDamage: (raw) => {
        if (this.invulnerableTimer <= 0) {
          const dmg = Math.max(3, Math.floor(raw * (1 - Math.min(0.4, this.damageReduction))));
          this.hp -= dmg;
          this.invulnerableTimer = 380;
          this.soundManager.playDie();
          this.particleSystem.emitDeath(this.px, this.py);
          this.callbacks.onHpChange(Math.max(0, this.hp), this.maxHp);
          if (this.hp <= 0) this.handleGameOver();
        }
      },
      onPlaySound: (s) => (s === 'boost' ? this.soundManager.playBoost() : this.soundManager.playDie()),
      onSpawnRetailMob: (count) => this.waveDirector.spawnRetailMobWave(count, this.activeEvent?.effect.enemySpeedMult || 1.0),
      onDropHeart: (x, y) => {
        this.pickups.push({
          id: `boss_heart_${Date.now()}_${Math.random()}`,
          x,
          y,
          type: 'HEART',
          life: 18000,
          bobAngle: 0,
        });
      },
    });

    this.headImage.src = './assets/face/SNEK_0004.webp';
    this.headImage.onload = () => { this.imageLoaded = true; };

    this.onVisibilityChangeHandler = () => {
      if (typeof document !== 'undefined' && document.hidden) {
        this.isSleeping = true;
        if (this.animFrameId !== null) { cancelAnimationFrame(this.animFrameId); this.animFrameId = null; }
      } else {
        this.isSleeping = false;
        this.lastTime = performance.now();
        if (this.isRunning && this.animFrameId === null) this.animFrameId = requestAnimationFrame(this.loop);
      }
    };
    if (typeof document !== 'undefined' && document.addEventListener) {
      document.addEventListener('visibilitychange', this.onVisibilityChangeHandler);
    }

    this.initCanvasSize();
    this.initBgCandles();
  }

  // Progression Curves Delegations
  public getNextExpForLevel(lvl: number): number { return LevelCurves.getNextExpForLevel(lvl); }
  public getMonsterContactDamage(e: Enemy): number { return LevelCurves.getMonsterContactDamage(e, this.stage, this.elapsedTime); }
  public getTargetLevelForStage(stage: number): number { return LevelCurves.getTargetLevelForStage(stage); }
  public fireVenom(): void { this.weaponManager.venom.fire(this); }

  public collectExp(amount: number): void {
    this.exp += amount;
    this.soundManager.playEat();
    if (this.exp >= this.nextExp) this.handleLevelUp();
    else this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
  }

  public addExp(amount: number): void { this.collectExp(amount); }

  private initCanvasSize(): void {
    const dpr = Math.min(2.0, window.devicePixelRatio || 1);
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.ctx.setTransform(1, 0, 0, 1, 0, 0);
    this.ctx.scale(dpr, dpr);
  }

  public resize(displayWidth: number, displayHeight: number): void {
    if (displayWidth <= 0 || displayHeight <= 0) return;
    this.width = 440;
    this.height = Math.max(600, displayHeight);
    const dpr = Math.min(2.0, window.devicePixelRatio || 1);
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.ctx.setTransform(1, 0, 0, 1, 0, 0);
    this.ctx.scale(dpr, dpr);
    this.waveDirector.arenaWidth = this.width;
    this.waveDirector.arenaHeight = this.height;
    this.bossCombatController.arenaWidth = this.width;
    this.bossCombatController.arenaHeight = this.height;
    this.initBgCandles();
  }

  private initBgCandles(): void {
    this.bgCandles = [];
    for (let i = 0; i < 18; i++) {
      this.bgCandles.push({
        x: Math.random() * this.width,
        y: Math.random() * this.height,
        h: 20 + Math.random() * 50,
        isUp: Math.random() > 0.45,
      });
    }
  }

  public addFloatingText(
    text: string,
    color: string = '#00e676',
    x: number = this.px,
    y: number = this.py - 24
  ): void {
    if (this.bossCombatController && this.bossCombatController.bossFloatingTexts) {
      this.bossCombatController.bossFloatingTexts.push({
        id: `ft_${Date.now()}_${Math.random()}`,
        x,
        y,
        text,
        color,
        life: 1200,
        maxLife: 1200,
        vy: -0.65,
      });
    }
  }

  public revive(): boolean {
    return SurvivorLifecycleManager.revive(this);
  }

  public restartGame(): void {
    SurvivorLifecycleManager.restartGame(this);
  }

  public start(): void {
    if (this.hp <= 0) {
      this.restartGame();
      return;
    }
    if (this.isRunning) return; if (this.animFrameId !== null) { cancelAnimationFrame(this.animFrameId); this.animFrameId = null; }
    this.isRunning = true;
    this.isPaused = false;
    this.isSleeping = false;
    this.lastTime = performance.now();
    this.callbacks.onHpChange(this.hp, this.maxHp);
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
    this.callbacks.onKillsChange(this.kills);
    this.callbacks.onTimerChange(Math.floor(this.elapsedTime));
    this.callbacks.onStageChange?.(this.stage, `關卡 ${this.stage}`);
    this.loop(this.lastTime);
  }

  public pause(): void { this.isPaused = true; this.hasRenderedPauseFrame = false; }
  public resume(): void {
    if (!this.isPaused) return;
    this.isPaused = false;
    this.hasRenderedPauseFrame = false;
    this.lastTime = performance.now();
  }

  public setMoveVector(vx: number, vy: number): void {
    const len = Math.hypot(vx, vy);
    if (len > 1.0) { this.pvx = vx / len; this.pvy = vy / len; }
    else { this.pvx = vx; this.pvy = vy; }
  }

  public applyUpgrade(upgradeId: string): void { TalentApplier.apply(this, upgradeId); }
  public collectPickup(p: BattlefieldPickup): void { PickupApplier.apply(this, p); }
  public triggerBossEncounter(stage: number): void { BossLifecycleManager.triggerEncounter(this, stage); }
  public defeatBoss(): void { BossLifecycleManager.handleDefeat(this); }

  public triggerMacroEventForTesting(eventId: string): void {
    const ev = MACRO_EVENTS.find((m) => m.id === eventId) || MACRO_EVENTS[0];
    this.activeEvent = ev;
    this.eventTimer = ev.durationSec;
    if (ev.effect.spawnWhaleBoss) this.spawnWhaleBoss();
  }

  public destroy(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) { cancelAnimationFrame(this.animFrameId); this.animFrameId = null; }
    if (typeof document !== 'undefined' && this.onVisibilityChangeHandler) {
      document.removeEventListener('visibilitychange', this.onVisibilityChangeHandler);
      this.onVisibilityChangeHandler = null;
    }
  }

  private loop = (time: number): void => {
    if (!this.isRunning) return;
    if (this.isSleeping) { this.animFrameId = null; return; }
    if (time - this.lastTime < 15.6) {
      this.animFrameId = requestAnimationFrame(this.loop);
      return;
    }
    const dt = Math.min(time - this.lastTime, 100);
    this.lastTime = time;

    if (!this.isPaused) { this.update(dt); this.render(dt); }
    else if (!this.hasRenderedPauseFrame) { this.render(0); this.hasRenderedPauseFrame = true; }

    this.animFrameId = requestAnimationFrame(this.loop);
  };

  /**
   * Pure Orchestrator: High-Performance Main Update Pipeline
   */
  private update(dt: number): void {
    this.elapsedTime += dt / 1000;
    this.callbacks.onTimerChange(Math.floor(this.elapsedTime));
    this.particleSystem.update(dt);

    // 1. Player Motion & Status Timers
    PlayerMotionManager.update(this, dt);

    // 2. Macro Events Lifecycle
    MacroEventScheduler.update(this, dt);

    // 3. Boss Encounter Check
    if (!this.currentBoss && this.bossWarningTimer <= 0 && this.stageClearTimer <= 0) {
      if (this.level >= this.getTargetLevelForStage(this.stage)) this.triggerBossEncounter(this.stage);
    }
    if (this.bossWarningTimer > 0) this.bossWarningTimer -= dt / 1000;
    if (this.stageClearTimer > 0) this.stageClearTimer -= dt / 1000;

    // 4. Boss Combat System
    if (this.currentBoss) {
      this.bossCombatController.update(dt, { x: this.px, y: this.py, size: this.playerSize }, this.enemies, this.invulnerableTimer);
      this.bossCombatController.checkBossDefeat();
    }
    this.bossCombatController.updateBossVisualEffects(dt);

    // 5. Enemy Waves Spawning
    const speedMult = this.activeEvent?.effect.enemySpeedMult || 1.0;
    const spawnRateMult = this.activeEvent?.effect.spawnRateMult || 1.0;
    this.waveDirector.update(dt, this.stage, this.elapsedTime, !!this.currentBoss, this.enemies.length, speedMult, spawnRateMult);

    // 6. Battlefield Pickups Lifecycle & Collection
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const p = this.pickups[i];
      p.life -= dt;
      p.bobAngle += (dt / 1000) * 4;
      if (p.life <= 0) this.pickups.splice(i, 1);
    }
    this.collisionSystem.resolvePickupCollisions({
      player: { x: this.px, y: this.py, size: this.playerSize },
      pickups: this.pickups,
      onCollectPickup: (p) => this.collectPickup(p),
    });

    // 7. Enemy Movements & Auras
    EnemyMotionManager.update(this, dt);

    // 8. Weapons & Projectiles
    this.weaponManager.venom.update(dt, this);
    this.projectileSystem.update(dt);
    this.weaponManager.orbiter.update(dt, this);

    // 9. Combat Collisions & Resolution
    CombatResolver.resolveAll(this);

    // 10. Loot Collection
    const effectiveMagnetAll = !!(this.activeEvent?.effect.magnetAll || this.magnetAllTimer > 0);
    this.lootManager.update(
      dt,
      { x: this.px, y: this.py, size: this.playerSize, magnetRadius: this.magnetRadius },
      effectiveMagnetAll,
      this.isFever ? 1.4 : 1.0
    );
  }

  public updateEliteAuras(): void { EnemyMotionManager.updateEliteAuras(this.enemies); }
  public spawnEnemy(forceType?: EnemyType): void {
    const speedMult = this.activeEvent?.effect.enemySpeedMult || 1.0;
    this.waveDirector.triggerSpawn(this.stage, this.elapsedTime, false, speedMult, forceType, 1);
  }

  public spawnWhaleBoss(): void { SurvivorLifecycleManager.spawnWhaleBoss(this); }
  public killEnemy(idx: number): void { EnemyDefeatProcessor.process(this, idx); }
  public checkStageProgression(): void {
    if (!this.currentBoss && this.bossWarningTimer <= 0 && this.level >= this.getTargetLevelForStage(this.stage)) {
      this.triggerBossEncounter(this.stage);
    }
  }

  public updateBoss(dt: number): void {
    if (this.currentBoss) {
      this.bossCombatController.update(dt, { x: this.px, y: this.py, size: this.playerSize }, this.enemies, this.invulnerableTimer);
      this.bossCombatController.checkBossDefeat();
    }
  }

  private handleLevelUp(): void {
    this.exp = Math.max(0, this.exp - this.nextExp);
    this.level++;
    this.nextExp = this.getNextExpForLevel(this.level);
    this.checkStageProgression();
    this.soundManager.playHighScore();
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
    const shuffled = [...TALENTS_POOL].sort(() => 0.5 - Math.random()).slice(0, 3);
    this.pause();
    this.callbacks.onLevelUp(shuffled);
  }

  public triggerGameClear(): void { this.handleGameClear(); }
  public handleGameClear(): void { SurvivorLifecycleManager.handleGameClear(this); }
  private handleGameOver(): void { SurvivorLifecycleManager.handleGameOver(this); }

  private render(dt: number): void {
    if (this.ctx && typeof this.ctx.save === 'function') this.renderer.render(this.ctx, this, dt);
  }
}
