/**
 * Snek Web Audio API 8-bit Sound Synthesizer
 * Pure procedural audio without external mp3 dependencies
 */
export class SoundManager {
  private ctx: AudioContext | null = null;
  private muted: boolean = false;
  private isUnlocked: boolean = false;

  constructor() {
    const saved = localStorage.getItem('snek_game_muted');
    if (saved !== null) {
      this.muted = saved === 'true';
    }
    this.setupLifecycleListeners();
  }

  private setupLifecycleListeners(): void {
    if (typeof window === 'undefined' || typeof document === 'undefined') return;

    // 1. Re-awaken AudioContext when browser tab/app becomes visible
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        this.resumeContext();
      }
    });

    window.addEventListener('pageshow', () => {
      this.resumeContext();
    });

    window.addEventListener('focus', () => {
      this.resumeContext();
    });

    // 2. User Gesture Wakeup: On mobile, resume() is most reliable during user touch/pointer interaction
    const wakeOnTouch = () => {
      this.resumeContext();
    };
    window.addEventListener('touchstart', wakeOnTouch, { passive: true });
    window.addEventListener('pointerdown', wakeOnTouch, { passive: true });
  }

  public resumeContext(): void {
    if (!this.ctx) {
      if (this.isUnlocked) {
        this.unlock();
      }
      return;
    }

    try {
      if (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted') {
        this.ctx.resume().catch(() => {});
      } else if (this.ctx.state === 'closed') {
        // Self-heal closed audio context
        this.isUnlocked = false;
        this.ctx = null;
        this.unlock();
      }
    } catch {
      // Audio operation failed
    }
  }

  public unlock(): void {
    if (this.isUnlocked && this.ctx && this.ctx.state !== 'closed') return;
    try {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
        if (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted') {
          this.ctx.resume().catch(() => {});
        }
        this.isUnlocked = true;
      }
    } catch {
      // Audio not supported or blocked
    }
  }

  public isMuted(): boolean {
    return this.muted;
  }

  public toggleMute(): boolean {
    this.muted = !this.muted;
    localStorage.setItem('snek_game_muted', String(this.muted));
    return this.muted;
  }

  private canPlay(): boolean {
    if (this.muted) return false;
    if (!this.ctx || this.ctx.state === 'closed') {
      this.unlock();
    }
    this.resumeContext();
    return !!this.ctx;
  }

  /**
   * 吃到普通 SNEK 金幣
   */
  public playEat(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(587.33, now); // D5
    osc.frequency.exponentialRampToValueAtTime(880, now + 0.08); // A5

    gain.gain.setValueAtTime(0.18, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.09);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.1);
  }

  /**
   * 吃到稀有 ADA 代幣 (更響亮清脆的三和弦音)
   */
  public playAda(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [659.25, 830.61, 1046.5]; // E5, G#5, C6

    notes.forEach((freq, idx) => {
      if (!this.ctx) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + idx * 0.05);

      gain.gain.setValueAtTime(0.2, now + idx * 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.05 + 0.15);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now + idx * 0.05);
      osc.stop(now + idx * 0.05 + 0.16);
    });
  }

  /**
   * 吃到狂暴辣椒
   */
  public playChili(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [440, 554.37, 659.25, 880];

    notes.forEach((freq, idx) => {
      if (!this.ctx) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(freq, now + idx * 0.04);

      gain.gain.setValueAtTime(0.15, now + idx * 0.04);
      gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.04 + 0.12);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now + idx * 0.04);
      osc.stop(now + idx * 0.04 + 0.14);
    });
  }

  /**
   * 燃燒衝刺音效
   */
  public playBoost(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(220, now);
    osc.frequency.exponentialRampToValueAtTime(440, now + 0.06);

    gain.gain.setValueAtTime(0.08, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.07);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.08);
  }

  /**
   * 撞牆或陣亡 (低沉遞減滑音 + 白噪音感)
   */
  public playDie(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'square';
    osc.frequency.setValueAtTime(300, now);
    osc.frequency.exponentialRampToValueAtTime(50, now + 0.35);

    gain.gain.setValueAtTime(0.25, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.38);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.4);
  }

  /**
   * 戰場治癒/拾取回血道具清脆上升音效 (E5 -> G#5 -> B5)
   */
  public playHeal(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [659.25, 830.61, 987.77];

    notes.forEach((freq, idx) => {
      if (!this.ctx) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + idx * 0.06);

      gain.gain.setValueAtTime(0.24, now + idx * 0.06);
      gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.06 + 0.22);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now + idx * 0.06);
      osc.stop(now + idx * 0.06 + 0.24);
    });
  }

  /**
   * 創下新紀錄彩蛋音效
   */
  public playHighScore(): void {
    if (!this.canPlay() || !this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6

    notes.forEach((freq, idx) => {
      if (!this.ctx) return;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + idx * 0.1);

      gain.gain.setValueAtTime(0.22, now + idx * 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.1 + 0.3);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now + idx * 0.1);
      osc.stop(now + idx * 0.1 + 0.32);
    });
  }
}
