import { GAME_REGISTRY, GameMeta } from '../games/registry.ts';
import { LocalStorageAdapter } from '../storage/LocalStorageAdapter.ts';
import { Icons } from '../ui/icons.ts';
import { I18nService } from '../platform/I18nService.ts';
import { isDebugMode } from '../debug/GMDebugOverlay.ts';

export class LobbyView {
  private container: HTMLElement;
  private storage: LocalStorageAdapter;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
    this.storage = new LocalStorageAdapter();
  }

  public async mount(): Promise<() => void> {
    const i18n = I18nService.getInstance();
    const highScore = await this.storage.getHighScore();

    const render = () => {
      const isEn = i18n.getLocale() === 'en';

      this.container.innerHTML = `
        <div class="lobby-view">
          <!-- Lobby Top Header -->
          <header class="lobby-header">
            <a href="https://www.snek.com.tw/" class="lobby-brand" id="lobby-brand" title="${i18n.t('lobby.backToWebsite')}">
              <img src="./assets/token/Snek-Round-BG.svg" alt="SNEK" class="brand-logo" />
              <div class="brand-text-col">
                <span class="brand-title">SNEK ARCADE</span>
                <span class="brand-badge">TAIWAN HUB</span>
              </div>
            </a>
            <div class="lobby-header-right">
              <button id="btn-lobby-lang" class="icon-btn lang-btn" title="${i18n.t('hud.langSwitchTitle')}" aria-label="${i18n.t('hud.langSwitchTitle')}">
                ${Icons.globe}
              </button>
              <a href="https://www.snek.com.tw/" class="btn-back-website" id="btn-back-website" title="${i18n.t('lobby.backToWebsite')}">
                <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path><polyline points="9 22 9 12 15 12 15 22"></polyline></svg>
                <span>${i18n.t('lobby.backToWebsite')}</span>
              </a>
              <div class="lobby-user-stats">
                <span class="lobby-stat-label">${i18n.t('lobby.highScore')}</span>
                <span class="lobby-stat-val">${highScore.toLocaleString()}</span>
              </div>
            </div>
          </header>

          <!-- Scrollable Main Content -->
          <div class="lobby-scroll-content">
            ${isDebugMode() ? `
              <div style="background: rgba(0, 230, 118, 0.15); border: 1px solid #00e676; border-radius: 8px; padding: 10px 14px; margin-bottom: 16px; display: flex; align-items: center; justify-content: space-between; box-shadow: 0 0 15px rgba(0, 230, 118, 0.2);">
                <span style="color: #00e676; font-size: 13px; font-weight: bold;">🛠️ GM 除錯模式已啟用 (?debug=snek)</span>
                <a href="#/game/survivor" style="background: #00e676; color: #000; font-weight: 900; font-size: 12px; padding: 6px 14px; border-radius: 6px; text-decoration: none; cursor: pointer;">🚀 進入 SNEK 倖存者</a>
              </div>
            ` : ''}
            <!-- Hero Feature Banner -->
            <section class="lobby-hero-card">
              <div class="hero-bg-wrapper">
                <img src="./assets/banner/Snek Banana 1200x630.webp" alt="Snek Hero" class="hero-bg-img" />
                <div class="hero-overlay"></div>
              </div>
              <div class="hero-content">
                <span class="hero-pill">
                  ${Icons.flame}
                  <span>${i18n.t('lobby.featuredGame')}</span>
                </span>
                <h2 class="hero-title">${i18n.t('lobby.heroTitle')}</h2>
                <p class="hero-desc">${i18n.t('lobby.heroDesc')}</p>
                <button id="btn-hero-play" class="btn-hero-cta">
                  ${Icons.play}
                  <span>${i18n.t('lobby.playNow')}</span>
                </button>
              </div>
            </section>

            <!-- Section Title -->
            <div class="lobby-section-header">
              <h3 class="section-title">${i18n.t('lobby.allGames')}</h3>
              <span class="section-count">${i18n.t('lobby.gamesCount', { count: GAME_REGISTRY.length })}</span>
            </div>

            <!-- Game Cards Grid -->
            <div class="lobby-games-grid">
              ${GAME_REGISTRY.map((game) => this.renderGameCard(game, i18n, isEn)).join('')}
            </div>
          </div>

          <!-- Bottom Platform Navigation Bar -->
          <nav class="lobby-bottom-bar" aria-label="Platform Navigation">
            <button id="tab-lobby" class="lobby-tab-btn active">
              ${Icons.gamepad}
              <span>${i18n.t('lobby.tabLobby')}</span>
            </button>
            <button id="tab-leaderboard" class="lobby-tab-btn">
              ${Icons.trophy}
              <span>${i18n.t('lobby.tabLeaderboard')}</span>
            </button>
            <button id="tab-rewards" class="lobby-tab-btn">
              ${Icons.gift}
              <span>${i18n.t('lobby.tabRewards')}</span>
            </button>
          </nav>

          <!-- Coming Soon / Info Modal -->
          <div id="lobby-modal" class="modal-overlay">
            <div class="game-modal lobby-info-modal">
              <h2 id="lobby-modal-title" class="modal-title">${i18n.t('lobby.comingSoon')}</h2>
              <p id="lobby-modal-desc" class="lobby-modal-desc">${i18n.t('lobby.comingSoonDesc')}</p>
              <div class="modal-actions">
                <button id="btn-lobby-modal-close" class="btn-primary">
                  <span>${i18n.t('lobby.iKnow')}</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      `;

      this.bindEvents(i18n);
    };

    render();

    const unsubLocale = i18n.onLocaleChange(() => {
      render();
    });
    this.cleanups.push(unsubLocale);

    return () => {
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }

  private bindEvents(i18n: I18nService): void {
    // Bind Language Toggle
    const btnLobbyLang = this.container.querySelector('#btn-lobby-lang') as HTMLButtonElement;
    btnLobbyLang?.addEventListener('click', () => {
      const current = i18n.getLocale();
      i18n.setLocale(current === 'en' ? 'zh-TW' : 'en');
    });

    // Bind Back to Website links (Top-Left Brand & Top-Right Button)
    const lobbyBrand = this.container.querySelector('#lobby-brand') as HTMLElement;
    lobbyBrand?.addEventListener('click', (e) => {
      e.preventDefault();
      window.location.href = 'https://www.snek.com.tw/';
    });

    const btnBackWebsite = this.container.querySelector('#btn-back-website') as HTMLElement;
    btnBackWebsite?.addEventListener('click', (e) => {
      e.preventDefault();
      window.location.href = 'https://www.snek.com.tw/';
    });

    // Bind Hero Play
    const btnHeroPlay = this.container.querySelector('#btn-hero-play') as HTMLButtonElement;
    btnHeroPlay?.addEventListener('click', () => {
      window.location.hash = '#/game/survivor';
    });

    // Bind Game Cards
    this.container.querySelectorAll('.game-card').forEach((card) => {
      const gameId = card.getAttribute('data-id');
      const isPlayable = card.getAttribute('data-status') === 'playable';

      card.addEventListener('click', () => {
        if (isPlayable) {
          window.location.hash = `#/game/${gameId}`;
        } else {
          const game = GAME_REGISTRY.find((g) => g.id === gameId);
          if (game) {
            const isEn = i18n.getLocale() === 'en';
            const title = i18n.t(`games.${game.id}.title`) || game.title;
            const subtitle = i18n.t(`games.${game.id}.subtitle`) || game.subtitle;
            const desc = i18n.t(`games.${game.id}.desc`) || game.description;
            const statusText = isEn
              ? 'Status: Coming Soon! Stay tuned for official SNEK community updates.'
              : '狀態：籌備中，敬請鎖定 SNEK 社群第一手公告！';

            this.showModal(
              title,
              `【${subtitle}】\n\n${desc}\n\n${statusText}`
            );
          }
        }
      });
    });

    // Bind Tab Bar
    const tabLeaderboard = this.container.querySelector('#tab-leaderboard') as HTMLButtonElement;
    tabLeaderboard?.addEventListener('click', () => {
      this.showModal(
        i18n.t('lobby.leaderboardTitle'),
        i18n.t('lobby.leaderboardDesc')
      );
    });

    const tabRewards = this.container.querySelector('#tab-rewards') as HTMLButtonElement;
    tabRewards?.addEventListener('click', () => {
      this.showModal(
        i18n.t('lobby.rewardsTitle'),
        i18n.t('lobby.rewardsDesc')
      );
    });

    // Bind Modal Close
    const modal = this.container.querySelector('#lobby-modal') as HTMLElement;
    const btnClose = this.container.querySelector('#btn-lobby-modal-close') as HTMLButtonElement;
    btnClose?.addEventListener('click', () => {
      modal.classList.remove('active');
    });
  }

  private renderGameCard(game: GameMeta, i18n: I18nService, isEn: boolean): string {
    const isPlayable = game.status === 'playable';
    const badgeText = game.badge === 'HOT' ? 'HOT' : game.badge === 'NEW' ? 'NEW' : 'SOON';
    const badgeClass = game.badge.toLowerCase();
    const actionLabel = isPlayable ? i18n.t('lobby.playNow') : (isEn ? 'PREVIEW' : '玩法預告');

    // Dynamic i18n resolved fields with fallback to registry default
    const title = i18n.t(`games.${game.id}.title`) !== `games.${game.id}.title` ? i18n.t(`games.${game.id}.title`) : game.title;
    const subtitle = i18n.t(`games.${game.id}.subtitle`) !== `games.${game.id}.subtitle` ? i18n.t(`games.${game.id}.subtitle`) : game.subtitle;
    const desc = i18n.t(`games.${game.id}.desc`) !== `games.${game.id}.desc` ? i18n.t(`games.${game.id}.desc`) : game.description;
    const tags = i18n.tArray(`games.${game.id}.tags`).length > 0 ? i18n.tArray(`games.${game.id}.tags`) : game.tags;

    return `
      <div class="game-card ${isPlayable ? 'playable' : 'coming-soon'}" data-id="${game.id}" data-status="${game.status}">
        <div class="game-card-header">
          <img src="${game.iconImg}" alt="${title}" class="game-card-icon" />
          <span class="game-card-badge ${badgeClass}">${badgeText}</span>
        </div>
        <div class="game-card-body">
          <h4 class="game-card-title">${title}</h4>
          <span class="game-card-subtitle">${subtitle}</span>
          <p class="game-card-desc">${desc}</p>
          <div class="game-card-tags">
            ${tags.map((t) => `<span class="game-tag">#${t}</span>`).join('')}
          </div>
        </div>
        <div class="game-card-footer">
          <button class="btn-card-action ${isPlayable ? 'btn-play' : 'btn-soon'}">
            ${isPlayable ? Icons.play : Icons.sparkles}
            <span>${actionLabel}</span>
          </button>
        </div>
      </div>
    `;
  }

  private showModal(title: string, desc: string): void {
    const modal = this.container.querySelector('#lobby-modal') as HTMLElement;
    const modalTitle = this.container.querySelector('#lobby-modal-title') as HTMLElement;
    const modalDesc = this.container.querySelector('#lobby-modal-desc') as HTMLElement;

    if (modal && modalTitle && modalDesc) {
      modalTitle.textContent = title;
      modalDesc.innerHTML = desc.replace(/\n/g, '<br/>');
      modal.classList.add('active');
    }
  }
}
