import { BossEntity } from '../types.ts';

export interface BossMotionContext {
  arenaWidth: number;
  arenaHeight: number;
  player: { x: number; y: number; size?: number };
  invulnerableTimer: number;
  onPlayerDamage?: (damage: number) => void;
  onPlaySound?: (sound: 'boost' | 'die') => void;
  onWallImpact?: (x: number, y: number, nx: number, ny: number, boss: BossEntity) => void;
}

export class BossMotionController {
  /**
   * Main movement update cycle. Dispatches to active movement state handlers.
   */
  public update(boss: BossEntity, dt: number, ctx: BossMotionContext): void {
    const dtSec = dt / 1000;
    boss.stateTimer = (boss.stateTimer || 0) + dtSec;

    switch (boss.state) {
      case 'ENTERING':
        this.updateEntering(boss, dtSec, ctx);
        break;

      case 'FORMATION_HOVER':
        this.updateHoverAndStalking(boss, dtSec, ctx);
        break;

      case 'TELEGRAPH_DASH':
        this.updateTelegraphDash(boss, dtSec, ctx);
        break;

      case 'DASHING':
        this.updateDashing(boss, dtSec, ctx);
        break;

      case 'LEAP_WINDUP':
        this.updateLeapWindup(boss, dtSec, ctx);
        break;

      case 'LEAP_SMASH':
        this.updateLeapSmash(boss, dtSec, ctx);
        break;

      case 'STUNNED':
        this.updateStunned(boss, dtSec, ctx);
        break;

      case 'WALL_BOUNCING':
        this.updateWallBouncing(boss, dtSec, ctx);
        break;

      case 'PREPARE_DIVE':
        this.updatePrepareDive(boss, dtSec, ctx);
        break;

      case 'DIVING':
        this.updateDiving(boss, dtSec, ctx);
        break;

      case 'RETURNING':
        this.updateReturning(boss, dtSec, ctx);
        break;

      case 'TRACTOR_BEAM':
        this.updateTractorBeam(boss, dtSec, ctx);
        break;
    }
  }

  private updateEntering(boss: BossEntity, dtSec: number, _ctx: BossMotionContext): void {
    boss.y += 120 * dtSec;
    const targetHoverBaseY = Math.max(80, Math.min(360, boss.hoverBaseY || 145));
    if (boss.y >= targetHoverBaseY) {
      boss.y = targetHoverBaseY;
      boss.hoverBaseY = targetHoverBaseY;
      boss.state = 'FORMATION_HOVER';
      boss.stateTimer = 0;
      boss.mobilityCooldown = 6.5 + Math.random() * 2.0;
    }
  }

  /**
   * Dynamic Stalking & Positioning
   * Smoothly steers Boss X towards player and oscillates Y within patrol band.
   */
  private updateHoverAndStalking(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    // Animation frame timer countdown
    if (boss.animTimer && boss.animTimer > 0) {
      boss.animTimer -= dtSec;
      if (boss.animTimer <= 0) {
        boss.animState = 'IDLE';
        boss.frameIndex = 0;
      }
    }

    const isEnraged = (boss.hp / boss.maxHp) <= 0.4;
    const speedMult = isEnraged ? 1.3 : 1.0;

    // 1. Dynamic Stalking: Follow player's horizontal coordinate with soft inertia
    const margin = boss.size + 24;
    const targetX = Math.max(margin, Math.min(ctx.arenaWidth - margin, ctx.player.x));
    boss.stalkTargetX = targetX;
    const stalkLerp = Math.min(1.0, dtSec * 1.8 * speedMult);
    boss.x += (targetX - boss.x) * stalkLerp;

    // 2. Y-axis dynamic breathing patrol (y ∈ [80, 360])
    boss.hoverAngle = (boss.hoverAngle || 0) + (boss.hoverSpeed || 1.8) * speedMult * dtSec;
    const targetBaseY = Math.max(80, Math.min(360, 150 + Math.sin(boss.hoverAngle * 0.7) * 75));
    boss.hoverBaseY = (boss.hoverBaseY || 145) + (targetBaseY - (boss.hoverBaseY || 145)) * Math.min(1.0, dtSec * 1.5);
    boss.y = Math.max(80, Math.min(360, boss.hoverBaseY + Math.sin(boss.hoverAngle * 1.8) * 22));

    // 3. Mobility Action Dispatcher
    const cooldown = boss.mobilityCooldown || (boss.type === 'REAPER_UFO' ? 11.0 : 8.0);
    if (boss.stateTimer >= cooldown && !boss.laser?.active) {
      this.dispatchRandomMobilityAction(boss, ctx);
    }
  }

  /**
   * Selects an action from the mobility pool based on boss type and random distribution
   */
  public dispatchRandomMobilityAction(boss: BossEntity, ctx: BossMotionContext): void {
    boss.stateTimer = 0;
    boss.mobilityCooldown = 7.0 + Math.random() * 2.5;

    if (boss.type === 'REAPER_UFO') {
      boss.state = 'TRACTOR_BEAM';
      boss.tractorBeamActive = true;
      boss.tractorTimer = 3.5;
      ctx.onPlaySound?.('boost');
      return;
    }

    // Role-specific action preferences
    const roll = Math.random();
    if (boss.type === 'BONK_MASTER') {
      if (roll < 0.6) this.triggerLeapSmash(boss, ctx);
      else this.triggerLineDash(boss, ctx);
    } else if (boss.type === 'MOODENG_TERROR') {
      if (roll < 0.55) this.triggerWallBounce(boss, ctx, 3, (Math.random() > 0.5 ? 240 : -240), 180);
      else this.triggerLineDash(boss, ctx);
    } else if (boss.type === 'GIGACHAD_OMEGA') {
      if (roll < 0.65) this.triggerLineDash(boss, ctx);
      else this.triggerPrepareDive(boss, ctx);
    } else {
      // General Boss Pool: 40% Line Dash, 30% Leap Smash, 30% Dive
      if (roll < 0.4) {
        this.triggerLineDash(boss, ctx);
      } else if (roll < 0.7) {
        this.triggerLeapSmash(boss, ctx);
      } else {
        this.triggerPrepareDive(boss, ctx);
      }
    }
  }

  public calculateBossDashDamage(stage: number = 1): number {
    const scale = 0.35 + Math.max(0, stage - 1) * 0.08;
    return Math.max(10, Math.round(36 * scale));
  }

  public calculateBossSlamDamage(stage: number = 1): number {
    const scale = 0.35 + Math.max(0, stage - 1) * 0.08;
    return Math.max(12, Math.round(42 * scale));
  }

  // --- Line Dash ---
  public triggerLineDash(boss: BossEntity, ctx: BossMotionContext): void {
    boss.state = 'TELEGRAPH_DASH';
    boss.stateTimer = 0;
    boss.animState = 'WINDUP';
    boss.frameIndex = 1;
    boss.hitFlashTimer = 500;

    // Calculate overshoot vector: penetrate beyond player coordinates
    const dx = ctx.player.x - boss.x;
    const dy = ctx.player.y - boss.y;
    const dist = Math.hypot(dx, dy) || 1;
    const dirX = dx / dist;
    const dirY = dy / dist;

    // Penetrate at least 260px beyond the player or until arena boundaries
    const overshootDist = dist + 260;
    let targetX = boss.x + dirX * overshootDist;
    let targetY = boss.y + dirY * overshootDist;

    const margin = boss.size + 15;
    targetX = Math.max(margin, Math.min(ctx.arenaWidth - margin, targetX));
    targetY = Math.max(margin, Math.min(ctx.arenaHeight - margin, targetY));

    boss.dashTargetX = targetX;
    boss.dashTargetY = targetY;

    if (!boss.telegraphs) boss.telegraphs = [];
    boss.telegraphs.push({
      id: `tel_dash_${Date.now()}`,
      type: 'LINE',
      x: boss.x,
      y: boss.y,
      startX: boss.x,
      startY: boss.y,
      targetX: targetX,
      targetY: targetY,
      width: 32,
      duration: 0.8,
      maxDuration: 0.8,
      color: '#ff1744',
    });
    ctx.onPlaySound?.('die');
  }

  private updateTelegraphDash(boss: BossEntity, _dtSec: number, ctx: BossMotionContext): void {
    if (boss.stateTimer >= 0.8) {
      boss.state = 'DASHING';
      boss.stateTimer = 0;
      boss.animState = 'ATTACK';
      boss.frameIndex = 2;

      const targetX = boss.dashTargetX ?? ctx.player.x;
      const targetY = boss.dashTargetY ?? ctx.player.y;
      const angle = Math.atan2(targetY - boss.y, targetX - boss.x);
      const isEnraged = (boss.hp / boss.maxHp) <= 0.4;
      const speed = isEnraged ? 680 : 600;
      boss.dashVx = Math.cos(angle) * speed;
      boss.dashVy = Math.sin(angle) * speed;
      boss.dashTimer = 1.2;
      ctx.onPlaySound?.('boost');
    }
  }

  private updateDashing(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    if (boss.dashVx === undefined || boss.dashVy === undefined || boss.dashTimer === undefined) {
      boss.state = 'RETURNING';
      boss.stateTimer = 0;
      return;
    }

    boss.x += boss.dashVx * dtSec;
    boss.y += boss.dashVy * dtSec;
    boss.dashTimer -= dtSec;

    // Arena boundary clamp
    const margin = boss.size + 10;
    boss.x = Math.max(margin, Math.min(ctx.arenaWidth - margin, boss.x));
    boss.y = Math.max(margin, Math.min(ctx.arenaHeight - margin, boss.y));

    // Player contact collision check
    const pSize = ctx.player.size ?? 18;
    const dist = Math.hypot(ctx.player.x - boss.x, ctx.player.y - boss.y);
    if (dist < pSize + boss.size && ctx.invulnerableTimer <= 0) {
      const stage = (boss as any).stage ?? 1;
      ctx.onPlayerDamage?.(this.calculateBossDashDamage(stage));
    }

    // Check if overshoot destination reached, wall hit, or timer expired -> smooth RETURNING
    const targetX = boss.dashTargetX ?? ctx.arenaWidth / 2;
    const targetY = boss.dashTargetY ?? (ctx.arenaHeight - margin);
    const distToTarget = Math.hypot(targetX - boss.x, targetY - boss.y);

    if (boss.dashTimer <= 0 || distToTarget < 25) {
      boss.state = 'RETURNING';
      boss.stateTimer = 0;
      boss.dashVx = 0;
      boss.dashVy = 0;
    }
  }

  // --- Leap Smash & Stun ---
  public triggerLeapSmash(boss: BossEntity, ctx: BossMotionContext): void {
    boss.state = 'LEAP_WINDUP';
    boss.stateTimer = 0;
    boss.animState = 'WINDUP';
    boss.frameIndex = 1;
    boss.smashTargetX = ctx.player.x;
    boss.smashTargetY = ctx.player.y;

    if (!boss.telegraphs) boss.telegraphs = [];
    boss.telegraphs.push({
      id: `tel_smash_${Date.now()}`,
      type: 'CIRCLE',
      x: boss.smashTargetX,
      y: boss.smashTargetY,
      targetX: boss.smashTargetX,
      targetY: boss.smashTargetY,
      radius: 65,
      duration: 1.1,
      maxDuration: 1.1,
      color: '#ff9100',
    });
    ctx.onPlaySound?.('boost');
  }

  private updateLeapWindup(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    boss.y -= 400 * dtSec;
    if (boss.stateTimer >= 0.6) {
      boss.state = 'LEAP_SMASH';
      boss.stateTimer = 0;
      boss.x = boss.smashTargetX || ctx.player.x;
      boss.animState = 'ATTACK';
      boss.frameIndex = 2;
    }
  }

  private updateLeapSmash(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    const targetY = boss.smashTargetY || ctx.player.y;
    boss.y += 900 * dtSec;

    if (boss.y >= targetY) {
      boss.y = targetY;
      ctx.onPlaySound?.('die');

      // Emit ground shockwave
      if (!boss.shockwaves) boss.shockwaves = [];
      boss.shockwaves.push({
        id: `sw_smash_${Date.now()}`,
        x: boss.x,
        y: boss.y,
        radius: 15,
        maxRadius: 150,
        speed: 260,
        thickness: 16,
        damage: 28,
        color: '#ff9100',
      });

      // Direct player contact check
      const pSize = ctx.player.size ?? 18;
      const dist = Math.hypot(ctx.player.x - boss.x, ctx.player.y - boss.y);
      if (dist < pSize + boss.size && ctx.invulnerableTimer <= 0) {
        const stage = (boss as any).stage ?? 1;
        ctx.onPlayerDamage?.(this.calculateBossSlamDamage(stage));
      }

      // Enter STUNNED vulnerability window
      boss.state = 'STUNNED';
      boss.stateTimer = 0;
      boss.stunTimer = 1.6;
      boss.animState = 'HURT';
      boss.hitFlashTimer = 800;
    }
  }

  private updateStunned(boss: BossEntity, dtSec: number, _ctx: BossMotionContext): void {
    if (boss.stunTimer) {
      boss.stunTimer -= dtSec;
      if (boss.stunTimer <= 0) {
        boss.state = 'RETURNING';
        boss.stateTimer = 0;
      }
    } else {
      boss.state = 'RETURNING';
    }
  }

  // --- Wall Bounce ---
  public triggerWallBounce(
    boss: BossEntity,
    ctx: BossMotionContext,
    count: number = 3,
    vx: number = 220,
    vy: number = 160
  ): void {
    boss.state = 'WALL_BOUNCING';
    boss.stateTimer = 0;
    boss.bounceCount = count;
    boss.bounceVx = vx;
    boss.bounceVy = vy;
    boss.animState = 'ATTACK';
    boss.frameIndex = 2;
    ctx.onPlaySound?.('boost');
  }

  private updateWallBouncing(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    if (boss.bounceVx === undefined || boss.bounceVy === undefined || boss.bounceCount === undefined) {
      boss.state = 'FORMATION_HOVER';
      return;
    }

    boss.x += boss.bounceVx * dtSec;
    boss.y += boss.bounceVy * dtSec;

    const margin = boss.size + 8;
    // Horizontal bounce
    if (boss.x <= margin && boss.bounceVx < 0) {
      boss.x = margin;
      boss.bounceVx = -boss.bounceVx;
      boss.bounceCount--;
      ctx.onPlaySound?.('die');
      ctx.onWallImpact?.(boss.x, boss.y, 1, 0, boss);
    } else if (boss.x >= ctx.arenaWidth - margin && boss.bounceVx > 0) {
      boss.x = ctx.arenaWidth - margin;
      boss.bounceVx = -boss.bounceVx;
      boss.bounceCount--;
      ctx.onPlaySound?.('die');
      ctx.onWallImpact?.(boss.x, boss.y, -1, 0, boss);
    }

    // Vertical reflection
    if (boss.y <= margin && boss.bounceVy < 0) {
      boss.y = margin;
      boss.bounceVy = -boss.bounceVy;
      ctx.onWallImpact?.(boss.x, boss.y, 0, 1, boss);
    } else if (boss.y >= ctx.arenaHeight - margin && boss.bounceVy > 0) {
      boss.y = ctx.arenaHeight - margin;
      boss.bounceVy = -boss.bounceVy;
      ctx.onWallImpact?.(boss.x, boss.y, 0, -1, boss);
    }

    // Player contact damage
    const pSize = ctx.player.size ?? 18;
    const dist = Math.hypot(ctx.player.x - boss.x, ctx.player.y - boss.y);
    if (dist < pSize + boss.size && ctx.invulnerableTimer <= 0) {
      ctx.onPlayerDamage?.(30);
    }

    if (boss.bounceCount <= 0) {
      boss.state = 'FORMATION_HOVER';
      boss.stateTimer = 0;
      boss.mobilityCooldown = 3.5 + Math.random() * 2.0;
    }
  }

  // --- Classic Bezier Dive ---
  public triggerPrepareDive(boss: BossEntity, ctx: BossMotionContext): void {
    boss.state = 'PREPARE_DIVE';
    boss.stateTimer = 0;
    boss.animState = 'WINDUP';
    boss.frameIndex = 1;
    boss.hitFlashTimer = 600;
    ctx.onPlaySound?.('die');
  }

  private updatePrepareDive(boss: BossEntity, _dtSec: number, ctx: BossMotionContext): void {
    boss.animState = 'WINDUP';
    boss.frameIndex = 1;
    if (boss.stateTimer >= 0.6) {
      boss.state = 'DIVING';
      boss.stateTimer = 0;
      boss.diveProgress = 0;
      boss.diveStartX = boss.x;
      boss.diveStartY = boss.y;
      boss.diveTargetX = ctx.player.x + (Math.random() - 0.5) * 40;
      boss.diveTargetY = ctx.arenaHeight + 50;
      boss.diveControlX =
        (boss.diveStartX + boss.diveTargetX) / 2 +
        (boss.x > ctx.arenaWidth / 2 ? -90 : 90);
      boss.diveControlY = ctx.player.y;
    }
  }

  private updateDiving(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    boss.diveProgress += dtSec / 1.1;
    const t = Math.min(1.0, boss.diveProgress);
    const omt = 1 - t;
    boss.x =
      omt * omt * boss.diveStartX +
      2 * omt * t * boss.diveControlX +
      t * t * boss.diveTargetX;
    boss.y =
      omt * omt * boss.diveStartY +
      2 * omt * t * boss.diveControlY +
      t * t * boss.diveTargetY;

    const pSize = ctx.player.size ?? 18;
    const dist = Math.hypot(ctx.player.x - boss.x, ctx.player.y - boss.y);
    if (dist < pSize + boss.size && ctx.invulnerableTimer <= 0) {
      const raw = boss.stage >= 3 ? 42 : 28;
      ctx.onPlayerDamage?.(raw);
    }

    if (boss.diveProgress >= 1.0) {
      boss.state = 'RETURNING';
      boss.stateTimer = 0;
    }
  }

  private updateReturning(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    const targetX = ctx.arenaWidth / 2;
    const targetY = boss.hoverBaseY || 140;
    const lerpFactor = Math.min(1.0, dtSec * 2.6);
    boss.x += (targetX - boss.x) * lerpFactor;
    boss.y += (targetY - boss.y) * lerpFactor;

    if (Math.hypot(targetX - boss.x, targetY - boss.y) < 18) {
      boss.x = targetX;
      boss.y = targetY;
      boss.hoverBaseY = targetY;
      boss.state = 'FORMATION_HOVER';
      boss.stateTimer = 0;
      boss.mobilityCooldown = 3.5 + Math.random() * 2.0;
      boss.animState = 'IDLE';
      boss.frameIndex = 0;
    }
  }

  private updateTractorBeam(boss: BossEntity, dtSec: number, ctx: BossMotionContext): void {
    if (boss.tractorTimer !== undefined) {
      boss.tractorTimer -= dtSec;
      boss.x += (ctx.arenaWidth / 2 - boss.x) * (dtSec * 2);
      boss.y += ((boss.hoverBaseY || 140) - boss.y) * (dtSec * 2);

      if (boss.tractorTimer <= 0) {
        boss.tractorBeamActive = false;
        boss.state = 'FORMATION_HOVER';
        boss.stateTimer = 0;
        boss.mobilityCooldown = 3.5 + Math.random() * 2.0;
      }
    } else {
      boss.state = 'FORMATION_HOVER';
    }
  }
}
