import { StorageService } from '../../../platform/StorageService.ts';
import { SaveMigrationEngine } from './SaveMigrationEngine.ts';
import {
  CURRENT_SAVE_SCHEMA_VERSION,
  SURVIVOR_STORAGE_KEY,
  SurvivorSaveData,
  BossDefeatSnapshot,
  PlayerStatsSnapshot,
} from './types.ts';

export interface HostSnapshotSource {
  level: number;
  hp: number;
  maxHp: number;
  speed: number;
  playerSize?: number;
  damageReduction: number;
  damageMultiplier: number;
  magnetRadius: number;
  hasCompoundInterest: boolean;
  weapons: {
    venomCount: number;
    venomCooldown: number;
    orbitCount: number;
    orbitSpeed: number;
  };
  kills: number;
  elapsedTime: number;
}

export class SaveManager {
  private static instance: SaveManager | null = null;
  private storage: StorageService;

  constructor(storage?: StorageService) {
    this.storage = storage ?? new StorageService({ prefix: 'snek_arcade:' });
  }

  public static getInstance(storage?: StorageService): SaveManager {
    if (!SaveManager.instance || storage) {
      SaveManager.instance = new SaveManager(storage);
    }
    return SaveManager.instance;
  }

  public load(): SurvivorSaveData {
    const raw = this.storage.getItem<any>(SURVIVOR_STORAGE_KEY, null);
    const data = SaveMigrationEngine.migrate(raw);
    // If migration adjusted or filled default values, re-save to keep persistent
    if (!raw || raw.version !== data.version) {
      this.save(data);
    }
    return data;
  }

  public save(data: SurvivorSaveData): boolean {
    data.lastSavedAt = Date.now();
    data.version = CURRENT_SAVE_SCHEMA_VERSION;
    return this.storage.setItem(SURVIVOR_STORAGE_KEY, data);
  }

  public saveBossDefeat(
    stage: number,
    bossType: string,
    bossTitle: string,
    hostState: HostSnapshotSource
  ): SurvivorSaveData {
    const data = this.load();

    if (!data.defeatedBossStages.includes(stage)) {
      data.defeatedBossStages.push(stage);
      data.defeatedBossStages.sort((a, b) => a - b);
    }

    if (stage + 1 > data.highestStageUnlocked) {
      data.highestStageUnlocked = stage + 1;
    }

    const playerStats: PlayerStatsSnapshot = {
      level: hostState.level,
      hp: hostState.hp,
      maxHp: hostState.maxHp,
      speed: hostState.speed,
      playerSize: hostState.playerSize ?? 18,
      damageReduction: hostState.damageReduction,
      damageMultiplier: hostState.damageMultiplier,
      magnetRadius: hostState.magnetRadius,
      hasCompoundInterest: hostState.hasCompoundInterest,
      weapons: {
        venomCount: hostState.weapons.venomCount,
        venomCooldown: hostState.weapons.venomCooldown,
        orbitCount: hostState.weapons.orbitCount,
        orbitSpeed: hostState.weapons.orbitSpeed,
      },
    };

    const snapshot: BossDefeatSnapshot = {
      stage,
      bossType,
      bossTitle,
      defeatedAt: Date.now(),
      playerStats,
      kills: hostState.kills,
      elapsedTime: hostState.elapsedTime,
    };

    data.bossSnapshots[stage] = snapshot;
    this.save(data);
    return data;
  }

  public getSnapshot(stage: number): BossDefeatSnapshot | null {
    const data = this.load();
    return data.bossSnapshots[stage] ?? null;
  }

  public isBossDefeated(stage: number): boolean {
    const data = this.load();
    return data.defeatedBossStages.includes(stage);
  }

  public getDefeatedBossStages(): number[] {
    const data = this.load();
    return [...data.defeatedBossStages];
  }

  public clearSave(): void {
    this.storage.removeItem(SURVIVOR_STORAGE_KEY);
  }
}
