import { Direction } from '../types.ts';

export interface InputCallbacks {
  onDirection: (dir: Direction) => void;
  onBoostChange: (isBoosting: boolean) => void;
  onPauseToggle: () => void;
  onRestart: () => void;
}

export class InputManager {
  private callbacks: InputCallbacks;
  private isBoosting: boolean = false;
  private touchStartX: number = 0;
  private touchStartY: number = 0;
  private lastTriggerX: number = 0;
  private lastTriggerY: number = 0;
  private minSwipeDistance: number = 20;
  private isTouching: boolean = false;
  private hapticsEnabled: boolean = true;

  constructor(callbacks: InputCallbacks) {
    this.callbacks = callbacks;
    this.initKeyboard();
  }

  public setHaptics(enabled: boolean): void {
    this.hapticsEnabled = enabled;
  }

  public vibrate(pattern: number | number[]): void {
    if (this.hapticsEnabled && 'vibrate' in navigator) {
      try {
        navigator.vibrate(pattern);
      } catch {
        // Ignore haptics errors if blocked
      }
    }
  }

  private initKeyboard(): void {
    window.addEventListener('keydown', (e) => {
      // Prevent browser scroll for game keys
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) {
        e.preventDefault();
      }

      switch (e.code) {
        case 'ArrowUp':
        case 'KeyW':
          this.callbacks.onDirection('UP');
          break;
        case 'ArrowDown':
        case 'KeyS':
          this.callbacks.onDirection('DOWN');
          break;
        case 'ArrowLeft':
        case 'KeyA':
          this.callbacks.onDirection('LEFT');
          break;
        case 'ArrowRight':
        case 'KeyD':
          this.callbacks.onDirection('RIGHT');
          break;
        case 'Space':
          if (!this.isBoosting) {
            this.isBoosting = true;
            this.callbacks.onBoostChange(true);
          }
          break;
        case 'KeyP':
        case 'Escape':
          this.callbacks.onPauseToggle();
          break;
        case 'KeyR':
          this.callbacks.onRestart();
          break;
      }
    });

    window.addEventListener('keyup', (e) => {
      if (e.code === 'Space') {
        if (this.isBoosting) {
          this.isBoosting = false;
          this.callbacks.onBoostChange(false);
        }
      }
    });
  }

  /**
   * 手機全螢幕零延遲連續滑動手勢 (Continuous Glide Gesture)
   */
  public bindTouchSwipe(element: HTMLElement): void {
    let lastTapTime = 0;

    element.addEventListener(
      'touchstart',
      (e: TouchEvent) => {
        if (e.touches.length > 0) {
          this.isTouching = true;
          this.touchStartX = e.touches[0].clientX;
          this.touchStartY = e.touches[0].clientY;
          this.lastTriggerX = this.touchStartX;
          this.lastTriggerY = this.touchStartY;

          // Double tap on canvas to trigger quick boost toggle
          const now = performance.now();
          if (now - lastTapTime < 280) {
            this.setBoosting(!this.isBoosting);
            this.vibrate(20);
          }
          lastTapTime = now;
        }
      },
      { passive: false }
    );

    element.addEventListener(
      'touchmove',
      (e: TouchEvent) => {
        if (!this.isTouching || e.touches.length === 0) return;
        e.preventDefault(); // Prevent pull-to-refresh & screen dragging

        const currentX = e.touches[0].clientX;
        const currentY = e.touches[0].clientY;

        const deltaX = currentX - this.lastTriggerX;
        const deltaY = currentY - this.lastTriggerY;

        const absX = Math.abs(deltaX);
        const absY = Math.abs(deltaY);

        if (Math.max(absX, absY) >= this.minSwipeDistance) {
          if (absX > absY) {
            const dir = deltaX > 0 ? 'RIGHT' : 'LEFT';
            this.callbacks.onDirection(dir);
            this.vibrate(8);
          } else {
            const dir = deltaY > 0 ? 'DOWN' : 'UP';
            this.callbacks.onDirection(dir);
            this.vibrate(8);
          }
          this.lastTriggerX = currentX;
          this.lastTriggerY = currentY;
        }
      },
      { passive: false }
    );

    const onTouchEnd = () => {
      this.isTouching = false;
    };

    element.addEventListener('touchend', onTouchEnd, { passive: true });
    element.addEventListener('touchcancel', onTouchEnd, { passive: true });
  }

  /**
   * 觸控虛擬方向按鈕
   */
  public triggerDirection(dir: Direction): void {
    this.callbacks.onDirection(dir);
    this.vibrate(10);
  }

  public setBoosting(boosting: boolean): void {
    if (this.isBoosting !== boosting) {
      this.isBoosting = boosting;
      this.callbacks.onBoostChange(boosting);
      if (boosting) {
        this.vibrate(15);
      }
    }
  }
}
