import { BattlefieldPickup, Enemy, ExpGem } from '../types.ts';

export interface PickupApplierHost {
  px: number;
  py: number;
  hp: number;
  maxHp: number;
  kills: number;
  enemies: Enemy[];
  expGems: ExpGem[];
  rocketTimer: number;
  nukeFlashTimer: number;
  magnetAllTimer: number;
  freezeTimer: number;
  lootManager: {
    addGem: (x: number, y: number, val: number, tier: 'NORMAL' | 'ELITE' | 'BOSS') => void;
  };
  particleSystem: {
    emitBurnDash: (x: number, y: number, angle: number) => void;
    emitDeath: (x: number, y: number) => void;
    emitEat: (x: number, y: number) => void;
  };
  soundManager: {
    playHighScore: () => void;
    playHeal?: () => void;
  };
  callbacks: {
    onHpChange: (hp: number, maxHp: number) => void;
    onKillsChange: (kills: number) => void;
  };
  addFloatingText?: (text: string, color: string) => void;
}

export class PickupApplier {
  public static apply(host: PickupApplierHost, p: BattlefieldPickup): void {
    if (p.type === 'HEART' || p.type === 'PIZZA') {
      if (typeof host.soundManager.playHeal === 'function') {
        host.soundManager.playHeal();
      } else {
        host.soundManager.playHighScore();
      }
    } else {
      host.soundManager.playHighScore();
    }

    switch (p.type) {
      case 'ROCKET':
        host.rocketTimer = 5.0; // 5s invincible rocket dash!
        for (let k = 0; k < 12; k++) {
          host.particleSystem.emitBurnDash(host.px, host.py, Math.random() * Math.PI * 2);
        }
        break;

      case 'NUKE': {
        host.nukeFlashTimer = 0.35;
        let deadCount = 0;
        for (const e of host.enemies) {
          if (!e.isBoss) {
            deadCount++;
            host.particleSystem.emitDeath(e.x, e.y);
            const val =
              e.type === 'BLACK_SWAN'
                ? 7
                : e.type === 'BEAR'
                ? 3
                : e.type === 'LIQUIDATION_REAPER'
                ? 5
                : e.type === 'FLASH_BEETLE'
                ? 2
                : 1;
            host.lootManager.addGem(e.x, e.y, val, val >= 3 ? 'ELITE' : 'NORMAL');
          }
        }
        host.enemies = host.enemies.filter((e) => e.isBoss);
        host.kills += deadCount;
        host.callbacks.onKillsChange(host.kills);
        break;
      }

      case 'MAGNET':
        host.magnetAllTimer = 2.5;
        for (const g of host.expGems) {
          const dx = host.px - g.x;
          const dy = host.py - g.y;
          const d = Math.hypot(dx, dy) || 1;
          g.x += (dx / d) * 15;
          g.y += (dy / d) * 15;
        }
        break;

      case 'HEART':
      case 'PIZZA': {
        const healAmt = Math.max(40, Math.floor(host.maxHp * 0.30));
        const prevHp = host.hp;
        host.hp = Math.min(host.maxHp, host.hp + healAmt);
        const actualGained = host.hp - prevHp;
        const displayAmt = actualGained > 0 ? actualGained : healAmt;

        host.callbacks.onHpChange(host.hp, host.maxHp);
        host.addFloatingText?.(`💚 +${displayAmt} HP`, '#00e676');

        for (let k = 0; k < 14; k++) {
          host.particleSystem.emitEat(
            host.px + (Math.random() - 0.5) * 24,
            host.py + (Math.random() - 0.5) * 24
          );
        }
        break;
      }

      case 'FREEZE':
        host.freezeTimer = 4.5;
        break;
    }
  }
}
