export const CURRENT_SAVE_SCHEMA_VERSION = 1;
export const SURVIVOR_STORAGE_KEY = 'survivor_save_data';

export interface PlayerStatsSnapshot {
  level: number;
  hp: number;
  maxHp: number;
  speed: number;
  playerSize: number;
  damageReduction: number;
  damageMultiplier: number;
  magnetRadius: number;
  hasCompoundInterest: boolean;
  weapons: {
    venomCount: number;
    venomCooldown: number;
    orbitCount: number;
    orbitSpeed: number;
  };
}

export interface BossDefeatSnapshot {
  stage: number;
  bossType: string;
  bossTitle: string;
  defeatedAt: number;
  playerStats: PlayerStatsSnapshot;
  kills: number;
  elapsedTime: number;
}

export interface SurvivorSaveData {
  version: number;
  lastSavedAt: number;
  highestStageUnlocked: number;
  defeatedBossStages: number[];
  bossSnapshots: Record<number, BossDefeatSnapshot>;
}
