import { SurvivorEngine } from '../SurvivorEngine.ts';
import { BossDefeatSnapshot } from '../save/types.ts';

export class SurvivorLifecycleManager {
  public static revive(engine: SurvivorEngine): boolean {
    engine.hp = engine.maxHp;
    engine.invulnerableTimer = 4000;
    engine.canRevive = false;
    engine.pvx = 0;
    engine.pvy = 0;

    // Nuke / Clear non-boss enemies around player
    let deadCount = 0;
    for (const e of engine.enemies) {
      if (!e.isBoss) {
        deadCount++;
        engine.particleSystem.emitDeath(e.x, e.y);
        engine.lootManager.addGem(e.x, e.y, 2, 'NORMAL');
      }
    }
    engine.enemies = engine.enemies.filter((e) => e.isBoss);
    engine.kills += deadCount;
    engine.callbacks.onKillsChange(engine.kills);

    // Repel active boss away to arena top and reset active action/hazard states
    if (engine.currentBoss) {
      const b = engine.currentBoss;
      b.y = 80;
      b.state = 'FORMATION_HOVER';
      b.stateTimer = 0;
      b.shockwaves = [];
      b.bombs = [];
      b.telegraphs = [];
      b.dashVx = 0;
      b.dashVy = 0;
      b.bounceVx = 0;
      b.bounceVy = 0;
      b.bounceCount = 0;
      b.isDeflectingProjectiles = false;
      b.gravityPullActive = false;
      if (b.laser) b.laser.active = false;
    }

    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.soundManager.playHighScore();
    engine.addFloatingText('💚 復活重獲新生 (FULL HP)', '#ffd700');

    for (let i = 0; i < 24; i++) {
      engine.particleSystem.emitSuperEat(engine.px, engine.py);
    }

    // Clear active boss projectiles and hazardous strikes so player is safe upon reviving
    if (engine.bossCombatController) {
      engine.bossCombatController.bossBullets = [];
      engine.bossCombatController.hazardZones = [];
      engine.bossCombatController.barricades = [];
      engine.bossCombatController.crossLaser = null;
      engine.bossCombatController.wickStrike = null;
    }

    // Cancel existing RAF frame and restart game loop cleanly
    if ((engine as any).animFrameId !== null) {
      cancelAnimationFrame((engine as any).animFrameId);
      (engine as any).animFrameId = null;
    }
    engine.isRunning = false;
    engine.isPaused = false;
    engine.start();
    return true;
  }

  public static restartGame(engine: SurvivorEngine): void {
    engine.isRunning = false;
    engine.isPaused = false;
    engine.stage = 1;
    engine.level = 1;
    engine.exp = 0;
    engine.nextExp = 10;
    engine.hp = 100;
    engine.maxHp = 100;
    engine.kills = 0;
    engine.elapsedTime = 0;
    engine.comboMeter = 0;
    engine.isFever = false;
    engine.feverTimer = 0;
    engine.enemies = [];
    engine.projectiles = [];
    engine.pickups = [];
    engine.currentBoss = null;
    engine.bossCombatController.resetBoss();
    engine.invulnerableTimer = 1000;
    engine.canRevive = true;
    engine.px = engine.width / 2;
    engine.py = engine.height / 2;
    engine.pvx = 0;
    engine.pvy = 0;
    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.callbacks.onExpChange(engine.exp, engine.nextExp, engine.level);
    engine.callbacks.onKillsChange(engine.kills);
    engine.callbacks.onTimerChange(0);
    engine.callbacks.onStageChange?.(1, '關卡 1');
    engine.start();
  }

  public static loadSnapshotAndStart(engine: SurvivorEngine, snapshot: BossDefeatSnapshot): void {
    engine.isRunning = false;
    engine.isPaused = false;
    engine.stage = snapshot.stage;
    engine.level = snapshot.playerStats.level;
    engine.nextExp = engine.getNextExpForLevel(engine.level);
    engine.exp = 0;
    engine.hp = snapshot.playerStats.hp;
    engine.maxHp = snapshot.playerStats.maxHp;
    engine.speed = snapshot.playerStats.speed;
    engine.playerSize = snapshot.playerStats.playerSize;
    engine.damageReduction = snapshot.playerStats.damageReduction;
    engine.damageMultiplier = snapshot.playerStats.damageMultiplier;
    engine.magnetRadius = snapshot.playerStats.magnetRadius;
    engine.hasCompoundInterest = snapshot.playerStats.hasCompoundInterest;

    engine.venomCount = snapshot.playerStats.weapons.venomCount;
    engine.venomCooldown = snapshot.playerStats.weapons.venomCooldown;
    engine.orbitCount = snapshot.playerStats.weapons.orbitCount;
    engine.orbitSpeed = snapshot.playerStats.weapons.orbitSpeed;

    engine.kills = snapshot.kills;
    engine.elapsedTime = snapshot.elapsedTime;
    engine.comboMeter = 0;
    engine.isFever = false;
    engine.feverTimer = 0;

    engine.enemies = [];
    engine.projectiles = [];
    engine.pickups = [];
    engine.currentBoss = null;
    engine.bossCombatController.resetBoss();
    engine.invulnerableTimer = 1500;
    engine.canRevive = true;
    engine.px = engine.width / 2;
    engine.py = engine.height / 2;
    engine.pvx = 0;
    engine.pvy = 0;

    engine.callbacks.onHpChange(engine.hp, engine.maxHp);
    engine.callbacks.onExpChange(engine.exp, engine.nextExp, engine.level);
    engine.callbacks.onKillsChange(engine.kills);
    engine.callbacks.onTimerChange(Math.floor(engine.elapsedTime));
    engine.callbacks.onStageChange?.(engine.stage, snapshot.bossTitle || `Stage ${engine.stage}`);

    engine.triggerBossEncounter(snapshot.stage);
    engine.start();
  }

  public static spawnWhaleBoss(engine: SurvivorEngine): void {
    if (engine.enemies.some((e) => e.type === 'WHALE_BOSS')) return;
    engine.enemies.push({
      id: `boss_whale_${Date.now()}`,
      x: engine.width / 2,
      y: -50,
      hp: 360,
      maxHp: 360,
      speed: 0.65,
      size: 32,
      type: 'WHALE_BOSS',
      color: '#00b0ff',
      isBoss: true,
      rotation: 0,
    });
  }

  public static handleGameClear(engine: SurvivorEngine): void {
    engine.isRunning = false;
    engine.pause();
    engine.soundManager.playHighScore();
    for (let i = 0; i < 36; i++) {
      engine.particleSystem.emitEat(
        engine.width / 2 + (Math.random() - 0.5) * 260,
        engine.height / 3 + (Math.random() - 0.5) * 180
      );
    }
    engine.callbacks.onGameClear?.(engine.kills, Math.floor(engine.elapsedTime), engine.level);
  }

  public static handleGameOver(engine: SurvivorEngine): void {
    if ((engine as any).animFrameId !== null) {
      cancelAnimationFrame((engine as any).animFrameId);
      (engine as any).animFrameId = null;
    }
    engine.isRunning = false;
    engine.soundManager.playDie();
    engine.particleSystem.emitDeath(engine.px, engine.py);
    engine.callbacks.onGameOver(engine.kills, Math.floor(engine.elapsedTime), engine.level);
  }
}
