import { SurvivorEngine } from './SurvivorEngine.ts';
import { getSurvivorSvg } from './data/icons.ts';
import { GMDebugOverlay, isDebugMode } from '../../debug/GMDebugOverlay.ts';
import { I18nService } from '../../platform/I18nService.ts';
import { BossSelectModal } from './ui/BossSelectModal.ts';
import { SurvivorLifecycleManager } from './systems/SurvivorLifecycleManager.ts';

export class SurvivorView {
  private container: HTMLElement;
  private engine: SurvivorEngine | null = null;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
  }

  public mount(): () => void {
    const i18n = I18nService.getInstance();

    this.container.innerHTML = `
      <div class="game-view survivor-view">
        <!-- Top HUD -->
        <header class="arcade-header">
          <div class="brand-section">
            <button id="btn-back-lobby" class="icon-btn back-btn" title="${i18n.t('hud.backToLobby')}" aria-label="${i18n.t('hud.backToLobby')}">
              ${Icons.back}
            </button>
            <div class="brand-meta-col">
              <span class="brand-title">SURVIVOR</span>
              <span id="stage-badge" class="stage-pill">${i18n.t('hud.stage')} 1</span>
            </div>
          </div>

          <div class="survivor-hud-center">
            <div class="bar-row">
              <span class="bar-tag hp-tag">HP</span>
              <div class="progress-track hp-track">
                <div id="hp-bar-fill" class="progress-fill hp-fill" style="width: 100%;"></div>
                <span id="hp-val-text" class="bar-val-text">100/100</span>
              </div>
            </div>
            <div class="bar-row">
              <span id="level-badge" class="bar-tag exp-tag">${i18n.t('hud.level')}1</span>
              <div class="progress-track exp-track">
                <div id="exp-bar-fill" class="progress-fill exp-fill" style="width: 0%;"></div>
              </div>
            </div>
            <div class="bar-row fever-row">
              <span id="fever-badge" class="bar-tag fever-tag">${i18n.t('hud.fever')}</span>
              <div class="progress-track fever-track">
                <div id="fever-bar-fill" class="progress-fill fever-fill" style="width: 0%;"></div>
              </div>
            </div>
          </div>

          <div class="hud-stats">
            <div class="stat-item">
              <span class="stat-label" id="lbl-hud-kills">${i18n.t('hud.kills')}</span>
              <span id="stat-kills" class="stat-value score">0</span>
            </div>
            <div class="stat-item">
              <span class="stat-label" id="lbl-hud-time">${i18n.t('hud.surviveTime')}</span>
              <span id="stat-time" class="stat-value">0:00</span>
            </div>
          </div>

          <div class="hud-actions">
            <button id="btn-audio" class="icon-btn" title="${i18n.t('hud.soundOn')}" aria-label="${i18n.t('hud.soundOn')}">
              ${Icons.volume}
            </button>
          </div>
        </header>

        <!-- Canvas Arena Container -->
        <main class="canvas-container">
          <div class="canvas-wrapper survivor-wrapper">
            <canvas id="survivor-canvas"></canvas>

            <!-- Macro Event Breaking News Ticker -->
            <div id="macro-event-banner" class="macro-event-banner" style="display: none;"></div>

            <!-- Level Up Selection Modal -->
            <div id="levelup-modal" class="modal-overlay">
              <div class="game-modal upgrade-modal">
                <span class="upgrade-header-pill" id="lbl-levelup-pill">${i18n.t('modal.levelUpTitle')}</span>
                <h3 class="upgrade-modal-title" id="lbl-levelup-title">${i18n.t('modal.levelUpSub')}</h3>
                <div id="upgrade-cards-list" class="upgrade-cards-list"></div>
              </div>
            </div>

            <!-- Game Over Modal -->
            <div id="gameover-modal" class="modal-overlay">
              <div class="game-modal">
                <h2 class="modal-title" id="lbl-gameover-title">${i18n.t('modal.gameOver')}</h2>
                <div class="modal-stats-grid">
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-stat-kills">${i18n.t('modal.finalKills')}</span>
                    <span id="modal-kills" class="modal-stat-val primary">0</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-stat-time">${i18n.t('modal.surviveDuration')}</span>
                    <span id="modal-time" class="modal-stat-val">0:00</span>
                  </div>
                  <div class="modal-stat-box" style="grid-column: span 2;">
                    <span class="modal-stat-label" id="lbl-stat-level">${i18n.t('modal.reachedLevel')}</span>
                    <span id="modal-level" class="modal-stat-val" style="color: var(--gold-color);">LV. 1</span>
                  </div>
                </div>

                <div class="modal-actions">
                  <button id="btn-revive" class="btn-primary" style="background: linear-gradient(135deg, #00e676, #00b0ff); color: #051016; font-weight: 900; margin-bottom: 8px;">
                    💚 <span id="lbl-btn-revive">${i18n.t('modal.reviveButton')}</span>
                  </button>
                  <button id="btn-restart" class="btn-secondary" style="margin-bottom: 4px;">
                    ${Icons.restart}
                    <span id="lbl-btn-restart">${i18n.t('modal.playAgain')}</span>
                  </button>
                  <button id="btn-gameover-boss-select" class="btn-secondary" style="margin-bottom: 4px;">
                    <span id="lbl-btn-gameover-boss-select">${i18n.t('bossSelect.backToSelect')}</span>
                  </button>
                  <div class="share-row">
                    <button id="btn-share-x" class="btn-secondary">
                      ${Icons.xLogo}
                      <span id="lbl-btn-share-x">${i18n.t('modal.shareToX')}</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>

            <!-- Victory Game Clear Modal -->
            <div id="victory-modal" class="modal-overlay">
              <div class="game-modal victory-modal">
                <div class="victory-crown-badge">👑</div>
                <h2 class="modal-title victory-title" id="lbl-victory-title">${i18n.t('victory.title')}</h2>
                <div class="victory-story-box">
                  <div class="story-badge" id="lbl-victory-story-title">${i18n.t('victory.storyTitle')}</div>
                  <p class="story-desc" id="lbl-victory-story-desc">${i18n.t('victory.storyDesc')}</p>
                </div>
                <div class="modal-stats-grid">
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-victory-stat-kills">${i18n.t('victory.finalKills')}</span>
                    <span id="victory-kills" class="modal-stat-val primary">0</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-victory-stat-time">${i18n.t('victory.surviveDuration')}</span>
                    <span id="victory-time" class="modal-stat-val">0:00</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-victory-stat-level">${i18n.t('victory.reachedLevel')}</span>
                    <span id="victory-level" class="modal-stat-val" style="color: var(--gold-color);">LV. 100 MAX</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label" id="lbl-victory-stat-bosses">${i18n.t('victory.defeatedBosses')}</span>
                    <span id="victory-bosses" class="modal-stat-val" style="color: #00e5ff;">10 / 10</span>
                  </div>
                </div>

                <div class="modal-actions">
                  <button id="btn-victory-share-x" class="btn-primary victory-share-btn">
                    ${Icons.xLogo}
                    <span id="lbl-btn-victory-share-x">${i18n.t('victory.shareToX')}</span>
                  </button>
                  <button id="btn-victory-restart" class="btn-secondary">
                    ${Icons.restart}
                    <span id="lbl-btn-victory-restart">${i18n.t('victory.playAgain')}</span>
                  </button>
                  <button id="btn-victory-boss-select" class="btn-secondary" style="margin-top: 4px;">
                    <span id="lbl-btn-victory-boss-select">${i18n.t('bossSelect.backToSelect')}</span>
                  </button>
                </div>
              </div>
            </div>

            <!-- On-Screen Virtual Floating Joystick Overlay -->
            <div id="survivor-touch-zone" class="survivor-joystick-overlay" aria-label="Touch Joystick">
              <div id="joystick-base" class="joystick-base">
                <div id="joystick-stick" class="joystick-stick"></div>
              </div>
              <span class="joystick-hint" id="lbl-joystick-hint">${i18n.t('controls.touchHint')}</span>
            </div>
          </div>
        </main>
      </div>
    `;

    // Elements
    const canvas = this.container.querySelector('#survivor-canvas') as HTMLCanvasElement;
    const canvasWrapper = this.container.querySelector('.canvas-wrapper') as HTMLElement;
    const btnBack = this.container.querySelector('#btn-back-lobby') as HTMLButtonElement;
    const hpFill = this.container.querySelector('#hp-bar-fill') as HTMLElement;
    const hpValText = this.container.querySelector('#hp-val-text') as HTMLElement | null;
    const expFill = this.container.querySelector('#exp-bar-fill') as HTMLElement;
    const levelBadge = this.container.querySelector('#level-badge') as HTMLElement;
    const stageBadge = this.container.querySelector('#stage-badge') as HTMLElement;
    const feverBadge = this.container.querySelector('#fever-badge') as HTMLElement;
    const feverBarFill = this.container.querySelector('#fever-bar-fill') as HTMLElement;
    const statKills = this.container.querySelector('#stat-kills') as HTMLElement;
    const statTime = this.container.querySelector('#stat-time') as HTMLElement;
    const btnAudio = this.container.querySelector('#btn-audio') as HTMLButtonElement;
    const btnLang = this.container.querySelector('#btn-lang') as HTMLButtonElement | null;

    const levelupModal = this.container.querySelector('#levelup-modal') as HTMLElement;
    const upgradeCardsList = this.container.querySelector('#upgrade-cards-list') as HTMLElement;
    const gameoverModal = this.container.querySelector('#gameover-modal') as HTMLElement;
    const modalKills = this.container.querySelector('#modal-kills') as HTMLElement;
    const modalTime = this.container.querySelector('#modal-time') as HTMLElement;
    const modalLevel = this.container.querySelector('#modal-level') as HTMLElement;
    const btnRevive = this.container.querySelector('#btn-revive') as HTMLButtonElement | null;
    const btnRestart = this.container.querySelector('#btn-restart') as HTMLButtonElement;
    const btnGoBossSelect = this.container.querySelector('#btn-gameover-boss-select') as HTMLButtonElement | null;
    const btnShareX = this.container.querySelector('#btn-share-x') as HTMLButtonElement;

    const victoryModal = this.container.querySelector('#victory-modal') as HTMLElement;
    const victoryKills = this.container.querySelector('#victory-kills') as HTMLElement;
    const victoryTime = this.container.querySelector('#victory-time') as HTMLElement;
    const victoryLevel = this.container.querySelector('#victory-level') as HTMLElement;
    const victoryBosses = this.container.querySelector('#victory-bosses') as HTMLElement;
    const btnVictoryRestart = this.container.querySelector('#btn-victory-restart') as HTMLButtonElement;
    const btnVicBossSelect = this.container.querySelector('#btn-victory-boss-select') as HTMLButtonElement | null;
    const btnVictoryShareX = this.container.querySelector('#btn-victory-share-x') as HTMLButtonElement;

    const touchZone = this.container.querySelector('#survivor-touch-zone') as HTMLElement;
    const joystickStick = this.container.querySelector('#joystick-stick') as HTMLElement;
    const macroEventBanner = this.container.querySelector('#macro-event-banner') as HTMLElement;

    const applyI18nLabels = () => {
      if (btnLang) {
        btnLang.innerHTML = Icons.globe;
        btnLang.title = i18n.t('hud.langSwitchTitle');
        btnLang.setAttribute('aria-label', i18n.t('hud.langSwitchTitle'));
      }

      const lblKills = this.container.querySelector('#lbl-hud-kills');
      if (lblKills) lblKills.textContent = i18n.t('hud.kills');
      const lblTime = this.container.querySelector('#lbl-hud-time');
      if (lblTime) lblTime.textContent = i18n.t('hud.surviveTime');

      const lblLevelupPill = this.container.querySelector('#lbl-levelup-pill');
      if (lblLevelupPill) lblLevelupPill.textContent = i18n.t('modal.levelUpTitle');
      const lblLevelupTitle = this.container.querySelector('#lbl-levelup-title');
      if (lblLevelupTitle) lblLevelupTitle.textContent = i18n.t('modal.levelUpSub');

      const lblGameoverTitle = this.container.querySelector('#lbl-gameover-title');
      if (lblGameoverTitle) lblGameoverTitle.textContent = i18n.t('modal.gameOver');
      const lblStatKills = this.container.querySelector('#lbl-stat-kills');
      if (lblStatKills) lblStatKills.textContent = i18n.t('modal.finalKills');
      const lblStatTime = this.container.querySelector('#lbl-stat-time');
      if (lblStatTime) lblStatTime.textContent = i18n.t('modal.surviveDuration');
      const lblStatLevel = this.container.querySelector('#lbl-stat-level');
      if (lblStatLevel) lblStatLevel.textContent = i18n.t('modal.reachedLevel');

      const lblRestart = this.container.querySelector('#lbl-btn-restart');
      if (lblRestart) lblRestart.textContent = i18n.t('modal.playAgain');
      const lblShareX = this.container.querySelector('#lbl-btn-share-x');
      if (lblShareX) lblShareX.textContent = i18n.t('modal.shareToX');
      const lblGoBossSelect = this.container.querySelector('#lbl-btn-gameover-boss-select');
      if (lblGoBossSelect) lblGoBossSelect.textContent = i18n.t('bossSelect.backToSelect');

      const lblVictoryTitle = this.container.querySelector('#lbl-victory-title');
      if (lblVictoryTitle) lblVictoryTitle.textContent = i18n.t('victory.title');
      const lblVictoryStoryTitle = this.container.querySelector('#lbl-victory-story-title');
      if (lblVictoryStoryTitle) lblVictoryStoryTitle.textContent = i18n.t('victory.storyTitle');
      const lblVictoryStoryDesc = this.container.querySelector('#lbl-victory-story-desc');
      if (lblVictoryStoryDesc) lblVictoryStoryDesc.textContent = i18n.t('victory.storyDesc');
      const lblVictoryStatKills = this.container.querySelector('#lbl-victory-stat-kills');
      if (lblVictoryStatKills) lblVictoryStatKills.textContent = i18n.t('victory.finalKills');
      const lblVictoryStatTime = this.container.querySelector('#lbl-victory-stat-time');
      if (lblVictoryStatTime) lblVictoryStatTime.textContent = i18n.t('victory.surviveDuration');
      const lblVictoryStatLevel = this.container.querySelector('#lbl-victory-stat-level');
      if (lblVictoryStatLevel) lblVictoryStatLevel.textContent = i18n.t('victory.reachedLevel');
      const lblVictoryStatBosses = this.container.querySelector('#lbl-victory-stat-bosses');
      if (lblVictoryStatBosses) lblVictoryStatBosses.textContent = i18n.t('victory.defeatedBosses');
      const lblBtnVictoryShareX = this.container.querySelector('#lbl-btn-victory-share-x');
      if (lblBtnVictoryShareX) lblBtnVictoryShareX.textContent = i18n.t('victory.shareToX');
      const lblBtnVictoryRestart = this.container.querySelector('#lbl-btn-victory-restart');
      if (lblBtnVictoryRestart) lblBtnVictoryRestart.textContent = i18n.t('victory.playAgain');
      const lblVicBossSelect = this.container.querySelector('#lbl-btn-victory-boss-select');
      if (lblVicBossSelect) lblVicBossSelect.textContent = i18n.t('bossSelect.backToSelect');

      const lblJoystick = this.container.querySelector('#lbl-joystick-hint');
      if (lblJoystick) lblJoystick.textContent = i18n.t('controls.touchHint');
    };

    btnLang?.addEventListener('click', () => {
      const current = i18n.getLocale();
      i18n.setLocale(current === 'en' ? 'zh-TW' : 'en');
    });

    const unsubLocale = i18n.onLocaleChange(() => {
      applyI18nLabels();
      if (this.engine) {
        const st = this.engine.stage;
        const curLvl = this.engine.level;
        const targetLvl = this.engine.getTargetLevelForStage(st);
        const stageLabel = i18n.t('hud.stage');
        if (this.engine.currentBoss) {
          stageBadge.textContent = `${stageLabel} ${st} · BOSS`;
        } else {
          stageBadge.textContent = `${stageLabel} ${st} (${curLvl}/${targetLvl})`;
        }
      }
    });
    this.cleanups.push(unsubLocale);

    // Back to Lobby
    btnBack.addEventListener('click', () => {
      window.location.hash = '#/';
    });

    let currentKills = 0;
    let currentTimeSec = 0;
    let currentLevel = 1;

    let lastMacroEventId: string | null = null;
    let lastRemainingSec = -1;

    // Input & Joystick Controls State
    const keysPressed: Record<string, boolean> = {};
    let touchId: number | null = null;
    let isMouseDown = false;
    let centerX = 0;
    let centerY = 0;
    const maxRadius = 38;

    const resetJoystick = () => {
      touchId = null;
      if (touchZone) {
        touchZone.classList.remove('active');
        touchZone.style.left = '50%';
        touchZone.style.top = 'auto';
        touchZone.style.bottom = '24px';
        touchZone.style.transform = 'translateX(-50%)';
      }
      if (joystickStick) {
        joystickStick.style.transition = 'transform 0.15s ease';
        joystickStick.style.transform = 'translate(0px, 0px)';
      }
      this.engine?.setMoveVector(0, 0);
    };

    const resetControls = () => {
      for (const k in keysPressed) {
        keysPressed[k] = false;
      }
      isMouseDown = false;
      resetJoystick();
    };

    // Initialize Engine
    this.engine = new SurvivorEngine(canvas, {
      onHpChange: (hp, maxHp) => {
        const safeHp = Math.max(0, Math.ceil(hp));
        const safeMaxHp = Math.max(1, Math.ceil(maxHp));
        const pct = Math.max(0, Math.min(100, (safeHp / safeMaxHp) * 100));
        hpFill.style.width = `${pct}%`;
        if (hpValText) {
          hpValText.textContent = `${safeHp}/${safeMaxHp}`;
          if (pct <= 25) {
            hpValText.classList.add('critical-low');
          } else {
            hpValText.classList.remove('critical-low');
          }
        }
      },
      onExpChange: (exp, nextExp, level) => {
        const pct = Math.max(0, Math.min(100, (exp / nextExp) * 100));
        expFill.style.width = `${pct}%`;
        levelBadge.textContent = `LV.${level}`;

        if (this.engine) {
          const st = this.engine.stage;
          const targetLvl = this.engine.getTargetLevelForStage(st);
          if (this.engine.currentBoss) {
            stageBadge.textContent = `STAGE ${st} · BOSS`;
          } else {
            stageBadge.textContent = `STAGE ${st} (${level}/${targetLvl})`;
          }
        }
      },
      onFeverChange: (meter, isFever, remainingSec) => {
        const pct = Math.max(0, Math.min(100, meter));
        feverBarFill.style.width = `${pct}%`;
        if (isFever) {
          feverBadge.textContent = `🔥${remainingSec}s`;
          feverBadge.classList.add('fever-active');
          feverBarFill.classList.add('fever-burning');
        } else {
          feverBadge.textContent = 'FEVER';
          feverBadge.classList.remove('fever-active');
          feverBarFill.classList.remove('fever-burning');
        }
      },
      onStageChange: (stage, title) => {
        const targetLvl = this.engine ? this.engine.getTargetLevelForStage(stage) : (stage === 1 ? 5 : (stage === 2 ? 10 : (stage === 3 ? 16 : 23)));
        const curLvl = this.engine ? this.engine.level : 1;
        stageBadge.textContent = `STAGE ${stage} (${curLvl}/${targetLvl})`;
        stageBadge.title = title;
      },
      onKillsChange: (kills) => {
        currentKills = kills;
        statKills.textContent = kills.toString();
      },
      onTimerChange: (seconds) => {
        currentTimeSec = seconds;
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        statTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
      },
      onMacroEvent: (event, remainingSec) => {
        if (!event || remainingSec <= 0) {
          if (lastMacroEventId !== null) {
            macroEventBanner.style.display = 'none';
            macroEventBanner.classList.remove('active', 'banner-intro', 'banner-collapsed');
            lastMacroEventId = null;
            lastRemainingSec = -1;
          }
          return;
        }

        const elapsed = event.durationSec - remainingSec;
        const isIntro = elapsed < 2.5;

        const localizedBadge = i18n.t(`macroEvents.${event.id}.badge`) || event.badge;
        const localizedName = i18n.t(`macroEvents.${event.id}.name`) || event.name;
        const localizedHeadline = i18n.t(`macroEvents.${event.id}.headline`) || event.headline;

        if (lastMacroEventId !== event.id) {
          lastMacroEventId = event.id;
          lastRemainingSec = remainingSec;
          macroEventBanner.style.display = 'flex';
          macroEventBanner.classList.add('active');
          macroEventBanner.style.borderColor = event.borderColor;
          macroEventBanner.style.boxShadow = `0 4px 18px ${event.glowColor}`;
        }

        if (isIntro) {
          if (!macroEventBanner.classList.contains('banner-intro')) {
            macroEventBanner.classList.add('banner-intro');
            macroEventBanner.classList.remove('banner-collapsed');
            macroEventBanner.style.background = event.bannerBg;
            macroEventBanner.innerHTML = `
              <div class="macro-banner-icon">${getSurvivorSvg(event.iconKey, 24, '#ffffff')}</div>
              <div class="macro-banner-content">
                <div class="macro-banner-row">
                  <span class="macro-pill">${localizedBadge}</span>
                  <span class="macro-name">${localizedName}</span>
                  <span id="macro-timer-val" class="macro-timer-pill">${remainingSec}s</span>
                </div>
                <div class="macro-headline">${localizedHeadline}</div>
              </div>
            `;
          }
        } else {
          // Collapsed into compact mini pill status badge (22px) to free up screen space
          if (!macroEventBanner.classList.contains('banner-collapsed')) {
            macroEventBanner.classList.add('banner-collapsed');
            macroEventBanner.classList.remove('banner-intro');
            macroEventBanner.style.background = 'rgba(10, 15, 24, 0.88)';
            macroEventBanner.innerHTML = `
              <div class="macro-banner-icon mini">${getSurvivorSvg(event.iconKey, 16, event.borderColor)}</div>
              <span class="macro-name mini">${localizedName}</span>
              <span id="macro-timer-val" class="macro-timer-pill mini">${remainingSec}s</span>
            `;
          }
        }

        if (lastRemainingSec !== remainingSec) {
          lastRemainingSec = remainingSec;
          const timerEl = macroEventBanner.querySelector('#macro-timer-val');
          if (timerEl) {
            timerEl.textContent = `${remainingSec}s`;
          }
        }
      },
      onLevelUp: (choices) => {
        if (this.engine) {
          this.engine.setMoveVector(0, 0);
        }
        upgradeCardsList.innerHTML = choices
          .map((c) => {
            const title = i18n.t(`talents.${c.id}.title`) || c.title;
            const badge = i18n.t(`talents.${c.id}.badge`) || c.badge;
            const desc = i18n.t(`talents.${c.id}.desc`) || c.desc;
            return `
          <button class="upgrade-card-btn" data-id="${c.id}">
            <div class="upgrade-card-icon-col">
              ${getSurvivorSvg(c.iconKey, 32, '#00e676')}
            </div>
            <div class="upgrade-card-info">
              <div class="upgrade-card-head">
                <span class="upgrade-title">${title}</span>
                <span class="upgrade-badge ${c.category.toLowerCase()}">${badge}</span>
              </div>
              <p class="upgrade-desc">${desc}</p>
            </div>
          </button>
        `;
          })
          .join('');

        upgradeCardsList.querySelectorAll('.upgrade-card-btn').forEach((btn) => {
          btn.addEventListener('click', () => {
            const upId = btn.getAttribute('data-id');
            if (upId && this.engine) {
              levelupModal.classList.remove('active');
              this.engine.applyUpgrade(upId);
            }
          });
        });

        levelupModal.classList.add('active');
      },
      onGameOver: (kills, timeSec, level) => {
        resetControls();
        currentKills = kills;
        currentTimeSec = timeSec;
        currentLevel = level;

        modalKills.textContent = kills.toString();
        const mins = Math.floor(timeSec / 60);
        const secs = timeSec % 60;
        modalTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
        modalLevel.textContent = `LV. ${level}`;

        if (btnRevive) {
          btnRevive.style.display = (this.engine && this.engine.canRevive) ? 'flex' : 'none';
        }

        gameoverModal.classList.add('active');
      },
      onGameClear: (kills, timeSec, level) => {
        currentKills = kills;
        currentTimeSec = timeSec;
        currentLevel = level;

        victoryKills.textContent = kills.toString();
        const mins = Math.floor(timeSec / 60);
        const secs = timeSec % 60;
        victoryTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
        victoryLevel.textContent = `LV. ${level} MAX`;
        victoryBosses.textContent = '10 / 10';

        victoryModal.classList.add('active');
      },
    });

    const engine = this.engine;
    (window as any).__survivorEngine = engine;
    (window as any).__survivorView = this;

    // Gated by ?debug=snek for zero production interference
    if (isDebugMode()) {
      const gmOverlay = new GMDebugOverlay(engine);
      (window as any).__gmOverlay = gmOverlay;
      gmOverlay.show(); // Automatically pop open when debug query is present
      this.cleanups.push(() => gmOverlay.destroy());
    }

    // Boss Select Screen Overlay (Stage & Boss Selection)
    const bossSelectModal = new BossSelectModal({
      onStartNewRun: () => {
        resetControls();
        engine.restartGame();
      },
      onSelectBoss: (snapshot) => {
        resetControls();
        SurvivorLifecycleManager.loadSnapshotAndStart(engine, snapshot);
      },
    });
    const bossSelectDom = bossSelectModal.render();
    canvasWrapper.appendChild(bossSelectDom);
    this.cleanups.push(() => bossSelectModal.destroy());

    // Responsive Auto-Resize for 100% Viewport Filling
    const handleResize = () => {
      if (this.engine && canvasWrapper.clientWidth > 0 && canvasWrapper.clientHeight > 0) {
        this.engine.resize(canvasWrapper.clientWidth, canvasWrapper.clientHeight);
      }
    };
    handleResize();
    requestAnimationFrame(handleResize);
    window.addEventListener('resize', handleResize);
    this.cleanups.push(() => window.removeEventListener('resize', handleResize));

    // Audio Toggle
    btnAudio.addEventListener('click', () => {
      engine.soundManager.toggleMute();
      btnAudio.innerHTML = engine.soundManager.isMuted() ? Icons.volumeMute : Icons.volume;
    });

    // Revive
    if (btnRevive) {
      btnRevive.addEventListener('click', () => {
        gameoverModal.classList.remove('active');
        resetControls();
        engine.revive();
      });
    }

    // Replay / Clean Restart
    btnRestart.addEventListener('click', () => {
      gameoverModal.classList.remove('active');
      resetControls();
      engine.restartGame();
    });

    // Game Over -> Boss Select
    btnGoBossSelect?.addEventListener('click', () => {
      gameoverModal.classList.remove('active');
      resetControls();
      bossSelectModal.show();
      engine.pause();
    });

    // Share to X
    btnShareX.addEventListener('click', () => {
      const text = i18n.t('modal.shareText', {
        time: currentTimeSec,
        kills: currentKills,
        level: currentLevel,
      });
      const url = 'https://www.snek.com.tw/game/#/game/survivor';
      const tweetUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;
      window.open(tweetUrl, '_blank', 'noopener,noreferrer');
    });

    // Victory Replay
    btnVictoryRestart.addEventListener('click', () => {
      victoryModal.classList.remove('active');
      resetControls();
      engine.restartGame();
    });

    // Victory -> Boss Select
    btnVicBossSelect?.addEventListener('click', () => {
      victoryModal.classList.remove('active');
      resetControls();
      bossSelectModal.show();
      engine.pause();
    });

    // Victory Share to X
    btnVictoryShareX.addEventListener('click', () => {
      const mins = Math.floor(currentTimeSec / 60);
      const secs = currentTimeSec % 60;
      const timeStr = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
      const text = i18n.t('victory.shareText', {
        time: timeStr,
        kills: currentKills,
      });
      const url = 'https://www.snek.com.tw/game/#/game/survivor';
      const tweetUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;
      window.open(tweetUrl, '_blank', 'noopener,noreferrer');
    });

    // Keyboard Controls
    const updateMovementFromKeys = () => {
      let vx = 0;
      let vy = 0;
      if (keysPressed['KeyW'] || keysPressed['ArrowUp']) vy -= 1;
      if (keysPressed['KeyS'] || keysPressed['ArrowDown']) vy += 1;
      if (keysPressed['KeyA'] || keysPressed['ArrowLeft']) vx -= 1;
      if (keysPressed['KeyD'] || keysPressed['ArrowRight']) vx += 1;

      const len = Math.hypot(vx, vy);
      if (len > 0) {
        engine.setMoveVector(vx / len, vy / len);
      } else {
        engine.setMoveVector(0, 0);
      }
    };

    const onKeyDown = (e: KeyboardEvent) => {
      keysPressed[e.code] = true;
      updateMovementFromKeys();
    };
    const onKeyUp = (e: KeyboardEvent) => {
      keysPressed[e.code] = false;
      updateMovementFromKeys();
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    this.cleanups.push(() => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    });

    // On-Screen Virtual Floating Joystick Controls on Canvas
    const updateJoystickMovement = (clientX: number, clientY: number) => {
      const dx = clientX - centerX;
      const dy = clientY - centerY;
      const dist = Math.hypot(dx, dy);

      const angle = Math.atan2(dy, dx);
      const clampedDist = Math.min(maxRadius, dist);
      const stickX = Math.cos(angle) * clampedDist;
      const stickY = Math.sin(angle) * clampedDist;

      joystickStick.style.transform = `translate(${stickX}px, ${stickY}px)`;

      if (dist > 5) {
        const strength = Math.min(1.0, Math.max(0.5, dist / maxRadius));
        engine.setMoveVector((dx / dist) * strength, (dy / dist) * strength);
      } else {
        engine.setMoveVector(0, 0);
      }
    };

    canvasWrapper.addEventListener(
      'touchstart',
      (e: TouchEvent) => {
        if (levelupModal.classList.contains('active') || gameoverModal.classList.contains('active') || victoryModal.classList.contains('active')) {
          return;
        }
        if (e.touches.length > 0 && touchId === null) {
          e.preventDefault();
          const t = e.touches[0];
          touchId = t.identifier;

          const wrapRect = canvasWrapper.getBoundingClientRect();
          const touchRelX = t.clientX - wrapRect.left;
          const touchRelY = t.clientY - wrapRect.top;

          const baseRadius = 45;
          const clampedX = Math.max(baseRadius + 8, Math.min(wrapRect.width - baseRadius - 8, touchRelX));
          const clampedY = Math.max(baseRadius + 8, Math.min(wrapRect.height - baseRadius - 8, touchRelY));

          touchZone.style.left = `${clampedX}px`;
          touchZone.style.top = `${clampedY}px`;
          touchZone.style.bottom = 'auto';
          touchZone.style.transform = 'translate(-50%, -50%)';
          touchZone.classList.add('active');

          centerX = wrapRect.left + clampedX;
          centerY = wrapRect.top + clampedY;

          joystickStick.style.transition = 'none';
          updateJoystickMovement(t.clientX, t.clientY);
        }
      },
      { passive: false }
    );

    canvasWrapper.addEventListener(
      'touchmove',
      (e: TouchEvent) => {
        if (touchId === null) return;
        for (let i = 0; i < e.touches.length; i++) {
          const t = e.touches[i];
          if (t.identifier === touchId) {
            e.preventDefault();
            updateJoystickMovement(t.clientX, t.clientY);
            break;
          }
        }
      },
      { passive: false }
    );

    const onTouchEnd = (e: TouchEvent) => {
      if (touchId === null) return;
      for (let i = 0; i < e.changedTouches.length; i++) {
        if (e.changedTouches[i].identifier === touchId) {
          resetJoystick();
          break;
        }
      }
    };

    canvasWrapper.addEventListener('touchend', onTouchEnd, { passive: true });
    canvasWrapper.addEventListener('touchcancel', onTouchEnd, { passive: true });
    window.addEventListener('touchend', onTouchEnd, { passive: true });
    window.addEventListener('touchcancel', onTouchEnd, { passive: true });

    // Mouse Drag Controls for Desktop Testing
    const onMouseDown = (e: MouseEvent) => {
      if (levelupModal.classList.contains('active') || gameoverModal.classList.contains('active') || victoryModal.classList.contains('active')) return;
      isMouseDown = true;
      const wrapRect = canvasWrapper.getBoundingClientRect();
      const touchRelX = e.clientX - wrapRect.left;
      const touchRelY = e.clientY - wrapRect.top;
      const baseRadius = 48;
      const clampedX = Math.max(baseRadius + 8, Math.min(wrapRect.width - baseRadius - 8, touchRelX));
      const clampedY = Math.max(baseRadius + 8, Math.min(wrapRect.height - baseRadius - 8, touchRelY));

      touchZone.style.left = `${clampedX}px`;
      touchZone.style.top = `${clampedY}px`;
      touchZone.style.bottom = 'auto';
      touchZone.style.transform = 'translate(-50%, -50%)';
      touchZone.classList.add('active');

      centerX = wrapRect.left + clampedX;
      centerY = wrapRect.top + clampedY;
      joystickStick.style.transition = 'none';
      updateJoystickMovement(e.clientX, e.clientY);
    };

    const onMouseMove = (e: MouseEvent) => {
      if (!isMouseDown) return;
      updateJoystickMovement(e.clientX, e.clientY);
    };

    const onMouseUp = () => {
      if (!isMouseDown) return;
      isMouseDown = false;
      resetJoystick();
    };

    canvasWrapper.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);

    this.cleanups.push(() => {
      window.removeEventListener('touchend', onTouchEnd);
      window.removeEventListener('touchcancel', onTouchEnd);
      canvasWrapper.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    });

    // Start Engine
    engine.start();
    (window as any).__survivorEngine = engine;

    // Show Boss Select screen on startup unless bypassing via preview hash
    if (!window.location.hash.includes('preview=')) {
      bossSelectModal.show();
      engine.pause();
    } else {
      bossSelectModal.hide();
    }

    // Testing / Preview helper
    if (window.location.hash.includes('preview=levelup')) {
      engine.addExp(20);
    } else if (window.location.hash.includes('preview=cpi')) {
      engine.triggerMacroEventForTesting('CPI_SURGE');
    } else if (window.location.hash.includes('preview=nfp')) {
      engine.triggerMacroEventForTesting('NFP_REPORT');
    } else if (window.location.hash.includes('preview=battle')) {
      setTimeout(() => {
        engine.enemies.push(
          { id: 'b1', x: 140, y: 150, hp: 50, maxHp: 50, speed: 0.8, size: 20, type: 'BEAR', color: '#ff1744' },
          { id: 'c1', x: 300, y: 140, hp: 30, maxHp: 30, speed: 0.9, size: 16, type: 'RED_CANDLE', color: '#d50000' },
          { id: 'r1', x: 120, y: 290, hp: 40, maxHp: 40, speed: 1.2, size: 18, type: 'LIQUIDATION_REAPER', color: '#ea80fc', rotation: 0.5 },
          { id: 'w1', x: 310, y: 300, hp: 350, maxHp: 400, speed: 0.5, size: 36, type: 'WHALE_BOSS', color: '#40c4ff', isBoss: true }
        );
        engine.expGems.push(
          { id: 'g1', x: 180, y: 200, value: 1, angle: 0.2 },
          { id: 'g2', x: 260, y: 210, value: 2, angle: 0.8 },
          { id: 'g3', x: 230, y: 270, value: 5, angle: 1.5 }
        );
      }, 50);
    }

    return () => {
      delete (window as any).__survivorEngine;
      if (this.engine) {
        this.engine.destroy();
        this.engine = null;
      }
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }
}
