import { IWeapon } from './IWeapon.ts';

export class OrbiterWeapon implements IWeapon {
  public readonly id = 'ORBITER';
  public readonly name = '期權對沖烈焰盾';

  public count: number = 1;
  public speed: number = 0.05;
  public angle: number = 0;
  public readonly radius: number = 45;

  public update(_dt: number, engine: any): void {
    this.angle += this.speed;

    for (let o = 0; o < this.count; o++) {
      const orbAngle = this.angle + (o * Math.PI * 2) / this.count;
      const ox = engine.px + Math.cos(orbAngle) * this.radius;
      const oy = engine.py + Math.sin(orbAngle) * this.radius;

      // Orbit damage to Boss
      if (engine.currentBoss && Math.hypot(ox - engine.currentBoss.x, oy - engine.currentBoss.y) < engine.currentBoss.size + 12) {
        engine.currentBoss.hp -= 2.2 * engine.damageMultiplier;
        engine.currentBoss.hitFlashTimer = 80;
        engine.particleSystem.emitBurnDash(ox, oy, orbAngle);
        if (engine.currentBoss.hp <= 0) {
          engine.defeatBoss();
        }
      }

      // Orbit damage to colliding enemies
      for (let j = engine.enemies.length - 1; j >= 0; j--) {
        const e = engine.enemies[j];
        if (Math.hypot(ox - e.x, oy - e.y) < e.size + 10) {
          e.hp -= 1.8 * engine.damageMultiplier;
          engine.particleSystem.emitBurnDash(ox, oy, orbAngle);
          if (e.hp <= 0) {
            engine.killEnemy(j);
          }
        }
      }
    }
  }

  public upgrade(): void {
    if (this.count < 6) {
      this.count++;
    }
    this.speed += 0.015;
  }

  public reset(): void {
    this.count = 1;
    this.speed = 0.05;
    this.angle = 0;
  }
}
