import { BossEntity, PickupType, Enemy } from '../types.ts';
import { BossFactory } from '../factories/BossFactory.ts';
import { I18nService } from '../../../platform/I18nService.ts';
import { SaveManager } from '../save/SaveManager.ts';

export interface BossLifecycleHost {
  width: number;
  stage: number;
  kills: number;
  bossDefeatedCount: number;
  bossWarningTimer: number;
  stageClearTimer: number;
  stageClearTitle: string;
  nextEventTimer: number;
  eventTimer: number;
  activeEvent: any;
  currentBoss: BossEntity | null;
  pickups: Array<{ id: string; x: number; y: number; type: PickupType; life: number; bobAngle: number }>;
  enemies: Enemy[];
  soundManager: {
    playBoost: () => void;
    playHighScore: () => void;
  };
  px?: number;
  py?: number;
  hp?: number;
  maxHp?: number;
  particleSystem: {
    emitDeath: (x: number, y: number) => void;
    emitEat?: (x: number, y: number) => void;
  };
  level: number;
  elapsedTime: number;
  callbacks: {
    onHpChange?: (hp: number, maxHp: number) => void;
    onMacroEvent?: (event: any, sec: number) => void;
    onKillsChange: (kills: number) => void;
    onStageChange?: (stage: number, title: string) => void;
    onGameClear?: (kills: number, timeSec: number, level: number) => void;
  };
  bossCombatController: {
    setBoss: (boss: BossEntity | null) => void;
    clear: () => void;
    bossFloatingTexts?: Array<{ id: string; x: number; y: number; text: string; color: string; life: number; maxLife: number; vy: number }>;
  };
  lootManager: {
    addGem: (x: number, y: number, val: number, tier: 'NORMAL' | 'ELITE' | 'BOSS') => void;
  };
}

export class BossLifecycleManager {
  public static triggerEncounter(host: BossLifecycleHost, stage: number): void {
    if (host.currentBoss) return;
    host.bossWarningTimer = 2.4;
    host.soundManager.playBoost();
    const boss = BossFactory.createBoss(stage, host.width);
    host.bossCombatController.setBoss(boss);

    // Rule: When Boss appears, NO macro events can exist or show!
    if (host.activeEvent) {
      host.activeEvent = null;
      host.eventTimer = 0;
      host.callbacks.onMacroEvent?.(null, 0);
    }
    host.nextEventTimer = 20;
  }

  public static handleDefeat(host: BossLifecycleHost): void {
    const boss = host.currentBoss;
    if (!boss) return;

    // 1. Full Heal on Boss Defeat (Immediate restoration to Max HP!)
    if (host.maxHp && host.hp !== undefined) {
      host.hp = host.maxHp;
      host.callbacks.onHpChange?.(host.hp, host.maxHp);
      host.soundManager.playBoost();

      if (host.px !== undefined && host.py !== undefined) {
        if (typeof host.particleSystem.emitEat === 'function') {
          for (let i = 0; i < 20; i++) {
            host.particleSystem.emitEat(host.px, host.py);
          }
        }
        if (host.bossCombatController.bossFloatingTexts) {
          host.bossCombatController.bossFloatingTexts.push({
            id: `fullheal_${Date.now()}`,
            x: host.px,
            y: host.py - 25,
            text: '❤️ FULL HEAL',
            color: '#00e676',
            life: 1200,
            maxLife: 1200,
            vy: -28,
          });
        }
      }
    }

    host.soundManager.playHighScore();
    for (let k = 0; k < 24; k++) {
      host.particleSystem.emitDeath(
        boss.x + (Math.random() - 0.5) * 40,
        boss.y + (Math.random() - 0.5) * 40
      );
    }

    host.bossDefeatedCount++;
    host.kills += 5;
    host.callbacks.onKillsChange(host.kills);

    // Silent background auto-save progression & player stats snapshot
    try {
      SaveManager.getInstance().saveBossDefeat(boss.stage, boss.type, boss.title, {
        level: host.level,
        hp: host.hp ?? 100,
        maxHp: host.maxHp ?? 100,
        speed: (host as any).speed ?? 2.4,
        playerSize: (host as any).playerSize ?? 18,
        damageReduction: (host as any).damageReduction ?? 0,
        damageMultiplier: (host as any).damageMultiplier ?? 1.0,
        magnetRadius: (host as any).magnetRadius ?? 65,
        hasCompoundInterest: (host as any).hasCompoundInterest ?? false,
        weapons: {
          venomCount: (host as any).weaponManager?.venom?.count ?? 1,
          venomCooldown: (host as any).weaponManager?.venom?.cooldown ?? 420,
          orbitCount: (host as any).weaponManager?.orbiter?.count ?? 1,
          orbitSpeed: (host as any).weaponManager?.orbiter?.speed ?? 0.05,
        },
        kills: host.kills,
        elapsedTime: host.elapsedTime,
      });
    } catch {
      // Ignored for resilience
    }

    // Drop Mega Diamond Gem (80 base EXP) + 6 satellites via LootManager
    host.lootManager.addGem(boss.x, boss.y, 80, 'BOSS');
    for (let i = 0; i < 6; i++) {
      const angle = (i * Math.PI * 2) / 6;
      host.lootManager.addGem(
        boss.x + Math.cos(angle) * 35,
        boss.y + Math.sin(angle) * 35,
        5,
        'ELITE'
      );
    }

    // 2 Guaranteed Battlefield Pickups!
    const pTypes: PickupType[] = ['ROCKET', 'NUKE', 'MAGNET', 'PIZZA', 'FREEZE'];
    const p1 = pTypes[Math.floor(Math.random() * pTypes.length)];
    const p2 = pTypes[Math.floor(Math.random() * pTypes.length)];
    host.pickups.push({
      id: `boss_pickup_1_${Date.now()}`,
      x: boss.x - 22,
      y: boss.y + 15,
      type: p1,
      life: 10000,
      bobAngle: 0,
    });
    host.pickups.push({
      id: `boss_pickup_2_${Date.now()}`,
      x: boss.x + 22,
      y: boss.y + 15,
      type: p2,
      life: 10000,
      bobAngle: 2,
    });

    // Stage 10 Final Boss (GIGACHAD OMEGA) Defeated -> Triggers Game Clear Victory!
    if (boss.stage === 10) {
      host.bossCombatController.clear();
      host.bossWarningTimer = 0;
      host.stageClearTimer = 0;
      if (typeof (host as any).handleGameClear === 'function') {
        (host as any).handleGameClear();
      } else {
        host.callbacks.onGameClear?.(host.kills, Math.floor(host.elapsedTime), host.level);
      }
      return;
    }

    // Advance to next Stage seamlessly (Infinite NG+ Loop!)
    const nextStage = host.stage + 1;
    host.stage = nextStage;
    const i18n = I18nService.getInstance();
    host.stageClearTimer = 3.5;
    host.stageClearTitle = i18n.t('boss.stageClear', { stage: boss.stage });

    const nextCycle = Math.floor((nextStage - 1) / 10) + 1;
    const nextStageInCycle = ((nextStage - 1) % 10) + 1;

    const bossKeys: Record<number, string> = {
      1: 'DOGE_KING',
      2: 'PEPE_FROG',
      3: 'WHALE_GOD',
      4: 'WIF_HAT',
      5: 'BONK_MASTER',
      6: 'POPCAT_OVERLORD',
      7: 'FLOKI_VIKING',
      8: 'MOODENG_TERROR',
      9: 'WOJAK_TRADER',
      10: 'GIGACHAD_OMEGA',
    };

    const bKey = bossKeys[nextStageInCycle];
    const localizedBossName = bKey ? i18n.t(`boss.${bKey}`) : '無盡輪迴';
    const stageLabel = i18n.t('hud.stage');

    let newStageTitle = `${stageLabel} ${nextStage}: ${localizedBossName}`;

    if (nextCycle > 1) {
      const loopPrefix = i18n.t('boss.loopPrefix', { cycle: nextCycle });
      newStageTitle = loopPrefix + newStageTitle;
    }

    host.callbacks.onStageChange?.(host.stage, newStageTitle);

    host.bossCombatController.clear();
    host.bossWarningTimer = 0;
    host.nextEventTimer = 22;
  }
}
