import { MACRO_EVENTS, MacroEvent } from '../data/events.ts';
import { Enemy, BossEntity, PickupType } from '../types.ts';

export interface MacroEventSchedulerHost {
  width: number;
  height: number;
  px: number;
  py: number;
  stage: number;
  currentBoss: BossEntity | null;
  bossWarningTimer: number;
  activeEvent: MacroEvent | null;
  nextEventTimer: number;
  eventTimer: number;
  stageAlert: { stage: number; title: string; subtitle: string; timer: number; maxTimer: number } | null;
  enemies: Enemy[];
  pickups: Array<{ id: string; x: number; y: number; type: PickupType; life: number; bobAngle: number }>;
  soundManager: {
    playBoost: () => void;
    playHighScore: () => void;
  };
  particleSystem: {
    emitEat: (x: number, y: number) => void;
    emitBurnDash: (x: number, y: number, angle: number) => void;
  };
  callbacks: {
    onMacroEvent?: (event: MacroEvent | null, remainingSec: number) => void;
  };
  spawnWhaleBoss: () => void;
  spawnEnemy: (type?: any) => void;
  killEnemy: (idx: number) => void;
}

export class MacroEventScheduler {
  public static update(host: MacroEventSchedulerHost, dt: number): void {
    // When Boss is active or warning siren is playing, NO events are allowed!
    if (host.currentBoss || host.bossWarningTimer > 0) {
      if (host.activeEvent) {
        host.activeEvent = null;
        host.eventTimer = 0;
        host.callbacks.onMacroEvent?.(null, 0);
      }
      host.nextEventTimer = Math.max(host.nextEventTimer, 16);
      return;
    }

    if (!host.activeEvent) {
      host.nextEventTimer -= dt / 1000;
      if (host.nextEventTimer <= 0) {
        const event = MACRO_EVENTS[Math.floor(Math.random() * MACRO_EVENTS.length)];
        host.activeEvent = event;
        host.eventTimer = event.durationSec;
        host.nextEventTimer = 28 + Math.random() * 12;

        if (event.effect.spawnWhaleBoss) {
          host.spawnWhaleBoss();
        }
        if (event.effect.spawnReaper) {
          for (let k = 0; k < 5; k++) {
            host.spawnEnemy('LIQUIDATION_REAPER');
          }
        }

        host.soundManager.playBoost();
        host.callbacks.onMacroEvent?.(host.activeEvent, Math.ceil(host.eventTimer));
      }
    } else {
      host.eventTimer -= dt / 1000;
      if (host.eventTimer <= 0) {
        if (host.activeEvent.id === 'CPI_SURGE') {
          // CPI 危機解除！保證掉落回血披薩 (+40 HP)
          host.pickups.push({
            id: `pickup_cpi_pizza_${Date.now()}`,
            x: Math.max(35, Math.min(host.width - 35, host.px + (Math.random() - 0.5) * 40)),
            y: Math.max(35, Math.min(host.height - 35, host.py + (Math.random() - 0.5) * 40)),
            type: 'PIZZA',
            life: 25000,
            bobAngle: 0,
          });
          host.soundManager.playHighScore();
          for (let k = 0; k < 12; k++) {
            host.particleSystem.emitEat(
              host.px + (Math.random() - 0.5) * 20,
              host.py + (Math.random() - 0.5) * 20
            );
          }
          host.stageAlert = {
            stage: host.stage,
            title: '💚 CPI 危機解除！通膨降溫',
            subtitle: '已緊急空投回血披薩 (+40 HP)！快撿起補血！',
            timer: 2.5,
            maxTimer: 2.5,
          };
        }
        host.activeEvent = null;
        host.callbacks.onMacroEvent?.(null, 0);
      } else {
        host.callbacks.onMacroEvent?.(host.activeEvent, Math.ceil(host.eventTimer));
        if (host.activeEvent.effect.burnAllTickDamage) {
          for (let j = host.enemies.length - 1; j >= 0; j--) {
            const e = host.enemies[j];
            e.hp -= (dt / 1000) * 12;
            if (Math.random() < 0.08) {
              host.particleSystem.emitBurnDash(e.x, e.y, -Math.PI / 2);
            }
            if (e.hp <= 0) {
              host.killEnemy(j);
            }
          }
        }
      }
    }
  }
}
