export interface TalentApplierHost {
  weaponManager: {
    venom: { upgrade: () => void };
    orbiter: { upgrade: () => void };
  };
  damageMultiplier: number;
  speed: number;
  hp: number;
  maxHp: number;
  damageReduction: number;
  magnetRadius: number;
  hasCompoundInterest: boolean;
  kills: number;
  enemies: Array<{ x: number; y: number; isBoss?: boolean; type?: string }>;
  expGems: Array<{ id: string; x: number; y: number; value: number; tier?: 'NORMAL' | 'ELITE' | 'BOSS' }>;
  particleSystem: { emitDeath: (x: number, y: number) => void };
  soundManager: { playHighScore: () => void };
  callbacks: {
    onHpChange: (hp: number, maxHp: number) => void;
    onKillsChange: (kills: number) => void;
  };
  resume: () => void;
}

export class TalentApplier {
  public static apply(host: TalentApplierHost, upgradeId: string): void {
    switch (upgradeId) {
      case 'LIQUIDITY_INJECTION':
      case 'MULTI_VENOM':
        host.weaponManager.venom.upgrade();
        host.damageMultiplier *= 1.08;
        break;

      case 'HEDGE_OPTIONS_SHIELD':
      case 'BURN_AURA':
        host.weaponManager.orbiter.upgrade();
        break;

      case 'ARBITRAGE_SPRINT':
      case 'SLITHER_SPEED':
        host.speed = Math.min(4.5, host.speed * 1.18);
        break;

      case 'DIAMOND_HANDS':
        host.maxHp += 30;
        host.hp = host.maxHp;
        host.damageReduction = Math.min(0.35, host.damageReduction + 0.1);
        host.callbacks.onHpChange(host.hp, host.maxHp);
        break;

      case 'FED_QE_PIVOT':
      case 'MEGA_BURN':
        for (const e of host.enemies) {
          if (!e.isBoss) {
            host.particleSystem.emitDeath(e.x, e.y);
            const val = e.type === 'BEAR' ? 3 : (e.type === 'LIQUIDATION_REAPER' ? 5 : 1);
            host.expGems.push({
              id: `gem_${Math.random()}`,
              x: e.x,
              y: e.y,
              value: val,
              tier: val >= 3 ? 'ELITE' : 'NORMAL',
            });
          }
        }
        host.kills += host.enemies.filter((e) => !e.isBoss).length;
        host.enemies = host.enemies.filter((e) => e.isBoss);
        host.callbacks.onKillsChange(host.kills);
        host.soundManager.playHighScore();
        break;

      case 'WHALE_MAGNET':
        host.magnetRadius *= 2.0;
        break;

      case 'COMPOUND_INTEREST':
        host.hasCompoundInterest = true;
        host.damageMultiplier *= 1.15;
        break;
    }
    host.resume();
  }
}
