import { getSurvivorPath2D } from '../data/icons.ts';

const bossSpriteCache: Record<string, HTMLImageElement> = {};
function getBossSprite(url: string): HTMLImageElement | null {
  if (typeof Image === 'undefined') return null;
  if (!bossSpriteCache[url]) {
    const img = new Image();
    img.src = url;
    bossSpriteCache[url] = img;
  }
  return bossSpriteCache[url];
}

export class SurvivorRenderer {
  public render(ctx: CanvasRenderingContext2D, engine: any, dt: number): void {
    ctx.save();

    // 1. Cyber Trading Floor Dark Gradient Background
    const bgGrad = ctx.createRadialGradient(
      engine.width / 2, engine.height / 2, 30,
      engine.width / 2, engine.height / 2, Math.max(engine.width, engine.height) * 0.75
    );
    bgGrad.addColorStop(0, '#0c121d');
    bgGrad.addColorStop(1, '#070a0f');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, engine.width, engine.height);

    // 2. Ambient K-Line Candlestick Waves
    for (let i = 0; i < engine.bgCandles.length; i++) {
      const c = engine.bgCandles[i];
      c.x -= (dt / 1000) * 12;
      if (c.x < -30) {
        c.x = engine.width + 10;
        c.y = 80 + Math.random() * (engine.height - 180);
        c.h = 20 + Math.random() * 45;
        c.isUp = Math.random() > 0.48;
      }

      ctx.fillStyle = c.isUp ? 'rgba(0, 230, 118, 0.07)' : 'rgba(255, 23, 68, 0.07)';
      ctx.fillRect(c.x, c.y, 14, c.h);
      ctx.strokeStyle = c.isUp ? 'rgba(0, 230, 118, 0.12)' : 'rgba(255, 23, 68, 0.12)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(c.x + 7, c.y - 8);
      ctx.lineTo(c.x + 7, c.y + c.h + 8);
      ctx.stroke();
    }

    // 3. Grid Lines
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
    ctx.lineWidth = 1;
    for (let x = 0; x < engine.width; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, engine.height);
      ctx.stroke();
    }
    for (let y = 0; y < engine.height; y += 40) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(engine.width, y);
      ctx.stroke();
    }

    // 4. Render EXP Gems (Crypto Tokens)
    for (const g of engine.expGems) {
      ctx.save();
      ctx.translate(g.x, g.y);
      ctx.rotate(g.angle || 0);

      if (g.tier === 'BOSS') {
        // Mega Rainbow Diamond Gem
        ctx.shadowColor = '#e040fb';
        ctx.shadowBlur = 14;
        ctx.fillStyle = '#ff4081';
        ctx.beginPath();
        ctx.arc(0, 0, 8.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(-3, -3, 6, 6);
        ctx.fillStyle = '#00e5ff';
        ctx.fillRect(-1.5, -1.5, 3, 3);
      } else if (g.tier === 'ELITE') {
        // Ether Cyan Gem
        ctx.shadowColor = '#00e5ff';
        ctx.shadowBlur = 10;
        ctx.fillStyle = '#00b0ff';
        ctx.beginPath();
        ctx.arc(0, 0, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(-2, -2, 4, 4);
      } else {
        // Standard Gold / Mint Token
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 7;
        ctx.fillStyle = '#ffd700';
        ctx.beginPath();
        ctx.arc(0, 0, 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#2bd88e';
        ctx.fillRect(-1.5, -1.5, 3, 3);
      }
      ctx.restore();
    }

    // 5. Render Battlefield Pickups
    for (const p of engine.pickups) {
      ctx.save();
      const bobY = Math.sin(p.bobAngle) * 4;
      ctx.translate(p.x, p.y + bobY);

      if (p.life < 4000 && Math.floor(performance.now() / 140) % 2 === 0) {
        ctx.globalAlpha = 0.35;
      }

      let glowColor = '#00e676';
      if (p.type === 'ROCKET') glowColor = '#ff3d00';
      else if (p.type === 'NUKE') glowColor = '#ffd600';
      else if (p.type === 'FREEZE') glowColor = '#00e5ff';
      else if (p.type === 'PIZZA') glowColor = '#ff9100';
      else if (p.type === 'MAGNET') glowColor = '#e040fb';
      else if (p.type === 'HEART') glowColor = '#00e676';

      ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
      ctx.strokeStyle = glowColor;
      ctx.lineWidth = 2;
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(0, 0, 14, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      if (p.type === 'HEART') {
        const pulse = 1 + Math.sin(performance.now() / 150) * 0.15;
        ctx.save();
        ctx.scale(pulse, pulse);
        ctx.fillStyle = '#00e676';
        ctx.shadowColor = '#69f0ae';
        ctx.shadowBlur = 12;
        ctx.beginPath();
        // Centered heart vector
        ctx.moveTo(0, -3);
        ctx.bezierCurveTo(-5, -9, -10, -3, -10, 1);
        ctx.bezierCurveTo(-10, 5, -5, 8, 0, 11);
        ctx.bezierCurveTo(5, 8, 10, 5, 10, 1);
        ctx.bezierCurveTo(10, -3, 5, -9, 0, -3);
        ctx.fill();
        ctx.restore();
      } else {
        let iconKey: 'rocket' | 'nuke' | 'magnet' | 'pizza' | 'freeze' = 'magnet';
        if (p.type === 'ROCKET') iconKey = 'rocket';
        else if (p.type === 'NUKE') iconKey = 'nuke';
        else if (p.type === 'FREEZE') iconKey = 'freeze';
        else if (p.type === 'PIZZA') iconKey = 'pizza';

        const iconPath = getSurvivorPath2D(iconKey);
        if (iconPath) {
          ctx.save();
          ctx.scale(18 / 512, 18 / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = glowColor;
          ctx.fill(iconPath);
          ctx.restore();
        }
      }
      ctx.restore();
    }

    // 6. Particle Systems
    engine.particleSystem.render(ctx);

    // 7. Render Player Projectiles (Liquidity Multi-Order Bullets)
    for (const p of engine.projectiles) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.fillStyle = '#69f0ae';
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(0, 0, 5, 0, Math.PI * 2);
      ctx.fill();

      // Incandescent pure white bullet impact core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(0, 0, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 8. Render Boss UFO Tractor Beam
    if (engine.currentBoss?.tractorBeamActive) {
      const boss = engine.currentBoss;
      ctx.save();
      const grad = ctx.createLinearGradient(boss.x, boss.y, boss.x, engine.height);
      grad.addColorStop(0, 'rgba(0, 229, 255, 0.45)');
      grad.addColorStop(0.5, 'rgba(224, 64, 251, 0.35)');
      grad.addColorStop(1, 'rgba(0, 229, 255, 0.08)');

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(boss.x - 20, boss.y + 10);
      ctx.lineTo(boss.x + 20, boss.y + 10);
      ctx.lineTo(boss.x + 95, engine.height);
      ctx.lineTo(boss.x - 95, engine.height);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = 'rgba(0, 229, 255, 0.6)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([8, 6]);
      ctx.lineDashOffset = -performance.now() / 25;
      ctx.stroke();

      // Pulsing horizontal grid scanlines
      const scanPhase = (performance.now() / 30) % 25;
      ctx.strokeStyle = 'rgba(0, 229, 255, 0.28)';
      ctx.lineWidth = 1.2;
      ctx.setLineDash([]);
      for (let sy = boss.y + 20 + scanPhase; sy < engine.height; sy += 25) {
        const progress = (sy - boss.y) / (engine.height - boss.y);
        const spanW = 20 + (95 - 20) * progress;
        ctx.beginPath();
        ctx.moveTo(boss.x - spanW, sy);
        ctx.lineTo(boss.x + spanW, sy);
        ctx.stroke();
      }
      ctx.restore();
    }

    // 8.5 Render Boss Sweep Laser Beam
    if (engine.currentBoss?.laser?.active) {
      const laser = engine.currentBoss.laser;
      ctx.save();
      const startX = laser.startX;
      const startY = laser.startY;
      const beamLength = 1200;
      const endX = startX + Math.cos(laser.angle) * beamLength;
      const endY = startY + Math.sin(laser.angle) * beamLength;

      if (laser.phase === 'AIMING') {
        const flash = Math.floor(performance.now() / 80) % 2 === 0;
        ctx.strokeStyle = flash ? 'rgba(255, 23, 68, 0.85)' : 'rgba(0, 229, 255, 0.45)';
        ctx.lineWidth = 1.8;
        ctx.setLineDash([8, 6]);
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Warning targeting reticle circle around player
        ctx.setLineDash([]);
        ctx.strokeStyle = '#ff1744';
        ctx.lineWidth = 1.8;
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(engine.px, engine.py, engine.playerSize * 1.6, 0, Math.PI * 2);
        ctx.stroke();
      } else if (laser.phase === 'FIRING') {
        // Broad outer plasma glow
        ctx.strokeStyle = laser.glowColor;
        ctx.lineWidth = laser.width + 10;
        ctx.shadowColor = laser.glowColor;
        ctx.shadowBlur = 24;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Pure white core laser
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = Math.max(4, laser.width * 0.38);
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Firing Muzzle Flare at Boss bottom
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = laser.glowColor;
        ctx.shadowBlur = 16;
        ctx.beginPath();
        ctx.arc(startX, startY, laser.width * 0.9, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = laser.glowColor;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(startX, startY, laser.width * 1.4, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.restore();
    }

    // 8.55 Render Meme Boss Hazard Zones (Yarn Web, Water Puddles)
    if (engine.bossCombatController?.hazardZones) {
      for (const z of engine.bossCombatController.hazardZones) {
        ctx.save();
        if (z.type === 'STICKY_YARN') {
          // Pink woven mesh web
          ctx.strokeStyle = 'rgba(255, 64, 129, 0.45)';
          ctx.fillStyle = 'rgba(245, 0, 87, 0.12)';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(z.x, z.y, z.radius, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();

          // Internal web lines
          for (let ang = 0; ang < Math.PI; ang += Math.PI / 4) {
            ctx.beginPath();
            ctx.moveTo(z.x - Math.cos(ang) * z.radius, z.y - Math.sin(ang) * z.radius);
            ctx.lineTo(z.x + Math.cos(ang) * z.radius, z.y + Math.sin(ang) * z.radius);
            ctx.stroke();
          }
        } else if (z.type === 'WATER_PUDDLE') {
          // Glistening light-blue water puddle
          ctx.fillStyle = 'rgba(0, 229, 255, 0.22)';
          ctx.strokeStyle = 'rgba(128, 216, 255, 0.6)';
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.ellipse(z.x, z.y, z.radius * 1.3, z.radius * 0.7, 0, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
        ctx.restore();
      }
    }

    // 8.56 Render Candlestick Barricades (Wojak)
    if (engine.bossCombatController?.barricades) {
      for (const bar of engine.bossCombatController.barricades) {
        ctx.save();
        ctx.translate(bar.x, bar.y);
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 18;
        ctx.fillStyle = '#d50000';
        ctx.fillRect(-bar.width / 2, -bar.height / 2, bar.width, bar.height);
        ctx.strokeStyle = '#ff1744';
        ctx.lineWidth = 2.5;
        ctx.strokeRect(-bar.width / 2, -bar.height / 2, bar.width, bar.height);

        // Upper and lower wick lines
        ctx.beginPath();
        ctx.moveTo(0, -bar.height / 2 - 14);
        ctx.lineTo(0, -bar.height / 2);
        ctx.moveTo(0, bar.height / 2);
        ctx.lineTo(0, bar.height / 2 + 14);
        ctx.stroke();
        ctx.restore();
      }
    }

    // 8.57 Render Cross Laser (GigaChad)
    const cross = engine.bossCombatController?.crossLaser;
    if (cross && cross.active) {
      ctx.save();
      const length = Math.max(engine.width, engine.height) * 1.5;
      for (const angle of [cross.angle1, cross.angle2]) {
        const dx = Math.cos(angle) * length;
        const dy = Math.sin(angle) * length;
        if (cross.phase === 'AIMING') {
          ctx.setLineDash([8, 8]);
          ctx.strokeStyle = 'rgba(255, 215, 0, 0.45)';
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.moveTo(cross.centerX - dx, cross.centerY - dy);
          ctx.lineTo(cross.centerX + dx, cross.centerY + dy);
          ctx.stroke();
        } else if (cross.phase === 'FIRING') {
          ctx.setLineDash([]);
          // Gold outer glow
          ctx.strokeStyle = '#ffd700';
          ctx.lineWidth = 10;
          ctx.shadowColor = '#ffab00';
          ctx.shadowBlur = 18;
          ctx.beginPath();
          ctx.moveTo(cross.centerX - dx, cross.centerY - dy);
          ctx.lineTo(cross.centerX + dx, cross.centerY + dy);
          ctx.stroke();

          // White inner core
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 3;
          ctx.shadowBlur = 6;
          ctx.beginPath();
          ctx.moveTo(cross.centerX - dx, cross.centerY - dy);
          ctx.lineTo(cross.centerX + dx, cross.centerY + dy);
          ctx.stroke();
        }
      }
      ctx.restore();
    }

    // 8.58 Render Vertical Wick Strike (Wojak)
    const wick = engine.bossCombatController?.wickStrike;
    if (wick) {
      ctx.save();
      if (wick.phase === 'AIMING') {
        ctx.setLineDash([6, 6]);
        ctx.strokeStyle = 'rgba(255, 23, 68, 0.55)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(wick.x, 0);
        ctx.lineTo(wick.x, engine.height);
        ctx.stroke();
      } else if (wick.phase === 'STRIKING') {
        ctx.setLineDash([]);
        ctx.strokeStyle = '#ff1744';
        ctx.lineWidth = 10;
        ctx.shadowColor = '#d50000';
        ctx.shadowBlur = 18;
        ctx.beginPath();
        ctx.moveTo(wick.x, 0);
        ctx.lineTo(wick.x, engine.height);
        ctx.stroke();

        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(wick.x, 0);
        ctx.lineTo(wick.x, engine.height);
        ctx.stroke();
      }
      ctx.restore();
    }

    // 8.6 Render Boss Bullets
    for (const b of engine.bossBullets) {
      ctx.save();
      ctx.translate(b.x, b.y);

      if (b.type === 'CRESCENT_SLASH') {
        // Glowing Crescent Blade (Wasp & Spectre)
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 20;
        ctx.fillStyle = b.color;

        // Draw curved crescent blade shape
        ctx.beginPath();
        ctx.arc(0, -6, 24, 0.25 * Math.PI, 0.75 * Math.PI, false);
        ctx.arc(0, 7, 16, 0.82 * Math.PI, 0.18 * Math.PI, true);
        ctx.closePath();
        ctx.fill();

        // Sharp white cutting edge highlight
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2.2;
        ctx.beginPath();
        ctx.arc(0, -6, 24, 0.28 * Math.PI, 0.72 * Math.PI, false);
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'SPREAD_ORB') {
        // Nova Floral Spread Orb (Whale King Lifesteal)
        ctx.shadowColor = b.isLifesteal ? '#00e676' : b.glowColor;
        ctx.shadowBlur = 16;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();

        // Concentric ripple aura (green for lifesteal)
        ctx.strokeStyle = b.isLifesteal ? 'rgba(0, 230, 118, 0.85)' : b.glowColor;
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius * 1.5, 0, Math.PI * 2);
        ctx.stroke();

        // Core white bullet center
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, b.radius * 0.45, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        continue;
      }

      if (b.type === 'FED_CASH') {
        // Spinning green banknote bullet
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 14;
        ctx.fillStyle = b.color;
        ctx.fillRect(-10, -5, 20, 10);
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 9px monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('$', 0, 0);
        ctx.restore();
        continue;
      }

      if (b.type === 'HASH_MINE') {
        // Burning orange hexagonal mine
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 16;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'MEME_DOGE') {
        // Golden doge chaos bouncing bullet
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 16;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ff6f00';
        ctx.beginPath();
        ctx.arc(-2, -2, 2.5, 0, Math.PI * 2);
        ctx.arc(2, -2, 2.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        continue;
      }

      if (b.type === 'HFT_SLICE') {
        // Silver razor slice with motion blur
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 12;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.moveTo(0, -14);
        ctx.lineTo(4, 14);
        ctx.lineTo(-4, 14);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
        continue;
      }

      if (b.type === 'BEANIE_DISC') {
        // Spinning pink knit beanie disc
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = '#ff4081';
        ctx.shadowBlur = 18;
        ctx.fillStyle = '#ff4081';
        ctx.beginPath();
        ctx.ellipse(0, 0, 15, 9, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'YARN_BOMB') {
        // Pink yarn ball mine
        ctx.shadowColor = '#f50057';
        ctx.shadowBlur = 16;
        ctx.fillStyle = '#ff4081';
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#f50057';
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(-b.radius * 0.7, 0);
        ctx.lineTo(b.radius * 0.7, 0);
        ctx.moveTo(0, -b.radius * 0.7);
        ctx.lineTo(0, b.radius * 0.7);
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'VIKING_AXE') {
        // Blazing blue Viking battleaxe
        ctx.rotate(b.angle || 0);
        ctx.shadowColor = '#00e5ff';
        ctx.shadowBlur = b.phase === 'HOVERING' ? 24 : 18;

        if (b.phase === 'HOVERING') {
          // Blade Whirlpool ring
          ctx.strokeStyle = 'rgba(0, 229, 255, 0.45)';
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.arc(0, 0, 22, 0, Math.PI * 2);
          ctx.stroke();
        }

        ctx.fillStyle = '#00b0ff';
        ctx.fillRect(-3, -14, 6, 28);
        ctx.fillStyle = '#e0f7fa';
        ctx.beginPath();
        ctx.arc(9, -5, 12, -0.4 * Math.PI, 0.4 * Math.PI);
        ctx.fill();
        ctx.restore();
        continue;
      }

      if (b.type === 'WATER_SPLASH') {
        // Deep blue glistening water droplet
        ctx.shadowColor = '#00b0ff';
        ctx.shadowBlur = 14;
        ctx.fillStyle = '#00e5ff';
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(-2, -2, b.radius * 0.4, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
        continue;
      }

      if (b.type === 'RED_CANDLE_DROP') {
        // Down-Only Plummeting Red Candlestick
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 20;
        ctx.fillStyle = '#d50000';
        ctx.fillRect(-6, -14, 12, 28);
        ctx.strokeStyle = '#ff1744';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, -20);
        ctx.lineTo(0, 20);
        ctx.stroke();
        ctx.restore();
        continue;
      }

      if (b.type === 'EXPLOIT_RUNES') {
        // Dark red rotating exploit rune
        ctx.shadowColor = b.glowColor;
        ctx.shadowBlur = 15;
        ctx.fillStyle = b.color;
        ctx.beginPath();
        ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#d50000';
        ctx.lineWidth = 1.5;
        ctx.stroke();
        ctx.restore();
        continue;
      }

      ctx.fillStyle = b.color;
      ctx.shadowColor = b.glowColor;
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(0, 0, b.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 9. Render Orbit Burn Shield (Options Hedging Shield)
    const orbitCount = engine.weaponManager ? engine.weaponManager.orbiter.count : engine.orbitCount;
    const orbitAngle = engine.weaponManager ? engine.weaponManager.orbiter.angle : engine.orbitAngle;
    const orbitRadius = 45;

    if (orbitCount > 0) {
      // Faint defensive golden orbit ring around player
      ctx.save();
      ctx.strokeStyle = 'rgba(255, 214, 0, 0.22)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 6]);
      ctx.beginPath();
      ctx.arc(engine.px, engine.py, orbitRadius, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    for (let o = 0; o < orbitCount; o++) {
      const angle = orbitAngle + (o * Math.PI * 2) / orbitCount;
      const ox = engine.px + Math.cos(angle) * orbitRadius;
      const oy = engine.py + Math.sin(angle) * orbitRadius;

      ctx.save();
      ctx.translate(ox, oy);
      ctx.rotate(angle + Math.PI / 2); // face outwards

      // 1. Fiery protective aura behind shield
      ctx.shadowColor = '#ff3d00';
      ctx.shadowBlur = 14;
      ctx.fillStyle = 'rgba(255, 145, 0, 0.35)';
      ctx.beginPath();
      ctx.arc(0, 0, 13, 0, Math.PI * 2);
      ctx.fill();

      // 2. SVG Hedge Options Shield Path2D
      const shieldPath = getSurvivorPath2D('shield');
      if (shieldPath) {
        ctx.scale(20 / 512, 20 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = '#ffd600';
        ctx.shadowColor = '#ff6d00';
        ctx.shadowBlur = 12;
        ctx.fill(shieldPath);

        // Silver/White edge stroke
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 14;
        ctx.shadowBlur = 0;
        ctx.stroke(shieldPath);
      } else {
        ctx.fillStyle = '#ffd600';
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    // 10. Render Normal & Elite Enemies
    for (const e of engine.enemies) {
      ctx.save();
      ctx.translate(e.x, e.y);

      if (e.isElite) {
        ctx.save();
        const auraPhase = (performance.now() / 400) % Math.PI;
        const pulseRadius = (e.auraRadius || 160) * (0.88 + Math.sin(auraPhase) * 0.12);
        ctx.strokeStyle = 'rgba(255, 215, 0, 0.35)';
        ctx.lineWidth = 2;
        ctx.setLineDash([8, 8]);
        ctx.lineDashOffset = -performance.now() / 40;
        ctx.beginPath();
        ctx.arc(0, 0, pulseRadius, 0, Math.PI * 2);
        ctx.stroke();

        // Elite golden indicator aura under monster
        ctx.fillStyle = 'rgba(255, 215, 0, 0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, e.size * 1.6, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      if (e.type === 'RED_CANDLE') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#ff1744';
        ctx.shadowBlur = 10;

        // K-line candlestick upper & lower shadow wick lines
        ctx.strokeStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#ff8a80';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(0, -e.size / 2 - 6);
        ctx.lineTo(0, e.size / 2 + 6);
        ctx.stroke();

        const cPath = getSurvivorPath2D('candle');
        if (cPath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#ff1744';
          ctx.fill(cPath);
        } else {
          ctx.fillStyle = engine.freezeTimer > 0 ? '#00b0ff' : '#d50000';
          ctx.fillRect(-e.size / 2, -e.size / 2, e.size, e.size * 1.6);
        }
      } else if (e.type === 'LIQUIDATION_REAPER') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#e040fb';
        ctx.shadowBlur = 12;
        const reaperPath = getSurvivorPath2D('reaper');
        if (reaperPath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#e040fb';
          ctx.fill(reaperPath);
        } else {
          ctx.fillStyle = '#e040fb';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.type === 'FLASH_BEETLE') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#c6ff00';
        ctx.shadowBlur = 12;
        const beetlePath = getSurvivorPath2D('beetle');
        if (beetlePath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#c6ff00';
          ctx.fill(beetlePath);
        } else {
          ctx.fillStyle = '#c6ff00';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.type === 'BLACK_SWAN') {
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#7c4dff';
        ctx.shadowBlur = 18;
        ctx.globalAlpha = 0.85 + Math.sin(engine.elapsedTime * 4) * 0.15;
        const spectrePath = getSurvivorPath2D('spectre');
        if (spectrePath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#b388ff';
          ctx.fill(spectrePath);
        } else {
          ctx.fillStyle = '#7c4dff';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else {
        // BEAR
        ctx.shadowColor = engine.freezeTimer > 0 ? '#00e5ff' : '#ff1744';
        ctx.shadowBlur = 12;
        ctx.fillStyle = engine.freezeTimer > 0 ? 'rgba(0, 229, 255, 0.25)' : 'rgba(213, 0, 0, 0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, e.size, 0, Math.PI * 2);
        ctx.fill();

        const bearPath = getSurvivorPath2D('bear');
        if (bearPath) {
          ctx.scale((e.size * 2) / 512, (e.size * 2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = engine.freezeTimer > 0 ? '#80d8ff' : '#d50000';
          ctx.fill(bearPath);
        }
      }
      ctx.restore();
    }

    // 10.5 Render Boss Special Hazards (Telegraphs, Bombs, Shockwaves, Hooks) & Entity
    if (engine.currentBoss) {
      const b = engine.currentBoss;

      // 10.5.1 Ground Telegraphs (Red Warning Bands & Danger Circles)
      if (b.telegraphs && b.telegraphs.length > 0) {
        ctx.save();
        for (const tel of b.telegraphs) {
          const progress = Math.max(0, Math.min(1, 1 - (tel.duration / tel.maxDuration)));
          if (tel.type === 'LINE' && tel.startX !== undefined && tel.startY !== undefined) {
            ctx.save();
            ctx.strokeStyle = `rgba(255, 23, 68, ${0.4 + Math.sin(performance.now() / 80) * 0.3})`;
            ctx.lineWidth = tel.width || 24;
            ctx.setLineDash([12, 8]);
            ctx.lineDashOffset = -performance.now() / 20;
            ctx.beginPath();
            ctx.moveTo(tel.startX, tel.startY);
            ctx.lineTo(tel.targetX, tel.targetY);
            ctx.stroke();

            // Inner charging indicator line
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2.5;
            ctx.setLineDash([]);
            ctx.beginPath();
            ctx.moveTo(tel.startX, tel.startY);
            ctx.lineTo(
              tel.startX + (tel.targetX - tel.startX) * progress,
              tel.startY + (tel.targetY - tel.startY) * progress
            );
            ctx.stroke();
            ctx.restore();
          } else if (tel.type === 'CIRCLE' && tel.radius) {
            ctx.save();
            ctx.fillStyle = `rgba(255, 23, 68, ${0.15 + progress * 0.25})`;
            ctx.strokeStyle = '#ff1744';
            ctx.lineWidth = 2.5;
            ctx.setLineDash([8, 6]);
            ctx.lineDashOffset = performance.now() / 30;
            ctx.beginPath();
            ctx.arc(tel.targetX, tel.targetY, tel.radius * progress, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(tel.targetX, tel.targetY, tel.radius, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
          }
        }
        ctx.restore();
      }

      // 10.5.2 Boss Bombs (Fed Cash Bundles / Hash Mines)
      if (b.bombs && b.bombs.length > 0) {
        for (const bomb of b.bombs) {
          ctx.save();
          ctx.translate(bomb.x, bomb.y);

          // Danger circle pulsing on ground
          const pulse = Math.sin(performance.now() / 100) * 4;
          ctx.strokeStyle = bomb.type === 'FED_CASH' ? 'rgba(0, 230, 118, 0.6)' : 'rgba(255, 109, 0, 0.6)';
          ctx.lineWidth = 1.8;
          ctx.setLineDash([6, 4]);
          ctx.beginPath();
          ctx.arc(0, 0, bomb.radius + pulse, 0, Math.PI * 2);
          ctx.stroke();

          // Render Bomb Icon / Entity
          ctx.shadowBlur = 16;
          if (bomb.type === 'FED_CASH') {
            ctx.shadowColor = '#00e676';
            const cashPath = getSurvivorPath2D('cash');
            if (cashPath) {
              const scale = 28 / 512;
              ctx.scale(scale, scale);
              ctx.translate(-256, -256);
              ctx.fillStyle = '#00e676';
              ctx.fill(cashPath);
            } else {
              ctx.fillStyle = '#00e676';
              ctx.fillRect(-12, -8, 24, 16);
            }
          } else {
            ctx.shadowColor = '#ff6d00';
            const powPath = getSurvivorPath2D('pow_titan');
            if (powPath) {
              const scale = 26 / 512;
              ctx.scale(scale, scale);
              ctx.translate(-256, -256);
              ctx.fillStyle = '#ff6d00';
              ctx.fill(powPath);
            } else {
              ctx.fillStyle = '#ff6d00';
              ctx.beginPath();
              ctx.arc(0, 0, 12, 0, Math.PI * 2);
              ctx.fill();
            }
          }
          ctx.restore();
        }
      }

      // 10.5.3 Shockwaves Expansion Rings
      if (b.shockwaves && b.shockwaves.length > 0) {
        for (const sw of b.shockwaves) {
          ctx.save();
          const alpha = Math.max(0, 1 - sw.radius / sw.maxRadius);
          ctx.strokeStyle = sw.color;
          ctx.globalAlpha = alpha;
          ctx.lineWidth = 4.0;
          ctx.shadowColor = sw.color;
          ctx.shadowBlur = 18;
          ctx.beginPath();
          ctx.arc(sw.x, sw.y, sw.radius, 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();
        }
      }

      // 10.5.4 Liquidation Hook (CEX Void Chain & Hook Claw)
      if (b.hook && b.hook.active) {
        ctx.save();
        // Chain from Boss to Hook Claw
        ctx.strokeStyle = '#b388ff';
        ctx.lineWidth = 3.5;
        ctx.shadowColor = '#7c4dff';
        ctx.shadowBlur = 12;
        ctx.setLineDash([8, 5]);
        ctx.lineDashOffset = -performance.now() / 20;
        ctx.beginPath();
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.hook.currX, b.hook.currY);
        ctx.stroke();

        // Hook Claw Head
        ctx.translate(b.hook.currX, b.hook.currY);
        const hookAngle = Math.atan2(b.hook.targetY - b.hook.startY, b.hook.targetX - b.hook.startX);
        ctx.rotate(hookAngle);
        ctx.fillStyle = '#e040fb';
        ctx.shadowColor = '#e040fb';
        ctx.shadowBlur = 16;
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, Math.PI * 2);
        ctx.fill();

        // Dual Hook Prongs
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(4, -8, 12, 0.2 * Math.PI, 0.8 * Math.PI, false);
        ctx.arc(4, 8, 12, 1.2 * Math.PI, 1.8 * Math.PI, false);
        ctx.stroke();
        ctx.restore();
      }

      if (b.type === 'WHALE_KING') {
        const mouthX = b.x;
        const mouthY = b.y + b.size * 0.4;
        const suctionRadius = 240;

        ctx.save();
        const timeSec = performance.now() / 1000;
        const ripple1 = (timeSec * 65) % suctionRadius;
        const ripple2 = ((timeSec * 65) + suctionRadius * 0.5) % suctionRadius;

        ctx.strokeStyle = 'rgba(0, 229, 255, 0.22)';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius - ripple1, 0, Math.PI * 2);
        ctx.stroke();

        ctx.strokeStyle = 'rgba(0, 230, 118, 0.25)';
        ctx.lineWidth = 2.0;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius - ripple2, 0, Math.PI * 2);
        ctx.stroke();

        ctx.strokeStyle = 'rgba(0, 176, 255, 0.35)';
        ctx.lineWidth = 1.5;
        ctx.setLineDash([8, 6]);
        ctx.lineDashOffset = -timeSec * 35;
        ctx.beginPath();
        ctx.arc(mouthX, mouthY, suctionRadius, 0, Math.PI * 2);
        ctx.stroke();

        // Render Siphon Tendrils connecting Whale King to nearby retail enemies
        const nearby: any[] = [];
        for (let j = 0; j < engine.enemies.length; j++) {
          const e = engine.enemies[j];
          if (e.isBoss) continue;
          const d = Math.hypot(mouthX - e.x, mouthY - e.y);
          if (d < suctionRadius + 20) {
            nearby.push(e);
          }
        }
        nearby.sort((a, bMob) => Math.hypot(mouthX - a.x, mouthY - a.y) - Math.hypot(mouthX - bMob.x, mouthY - bMob.y));
        const tethered = nearby.slice(0, 3);

        ctx.setLineDash([6, 4]);
        ctx.lineDashOffset = -timeSec * 60;
        for (const e of tethered) {
          ctx.strokeStyle = 'rgba(0, 230, 118, 0.75)';
          ctx.lineWidth = 2.2;
          ctx.shadowColor = '#00e676';
          ctx.shadowBlur = 12;

          ctx.beginPath();
          ctx.moveTo(mouthX, mouthY);
          const midX = (mouthX + e.x) / 2 + Math.sin(timeSec * 8 + e.x) * 12;
          const midY = (mouthY + e.y) / 2 + Math.cos(timeSec * 8 + e.y) * 12;
          ctx.quadraticCurveTo(midX, midY, e.x, e.y);
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(e.x, e.y, e.size + 4, 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.restore();
      }

      ctx.save();
      ctx.translate(b.x, b.y);

      if (b.state === 'DIVING') {
        const diveAngle = Math.atan2(b.diveTargetY - b.y, b.diveTargetX - b.x) - Math.PI / 2;
        ctx.rotate(diveAngle);
      } else if (b.state === 'PREPARE_DIVE' || b.state === 'TELEGRAPH_DASH') {
        const shake = (Math.random() - 0.5) * 6;
        ctx.translate(shake, 0);
      } else if (b.state === 'STUNNED') {
        // Stunned stars circling around boss head
        const starTime = performance.now() / 250;
        ctx.save();
        ctx.fillStyle = '#ffd700';
        ctx.shadowColor = '#ffea00';
        ctx.shadowBlur = 8;
        for (let s = 0; s < 3; s++) {
          const sAngle = starTime + (s * Math.PI * 2) / 3;
          const sx = Math.cos(sAngle) * (b.size * 0.85);
          const sy = -b.size * 0.8 + Math.sin(sAngle) * 8;
          ctx.beginPath();
          ctx.arc(sx, sy, 3.5, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }

      const isFlashing = b.hitFlashTimer > 0;
      ctx.shadowColor = isFlashing ? '#ffffff' : b.color;
      ctx.shadowBlur = isFlashing ? 28 : 22;

      const auraPulse = Math.sin(performance.now() / 120) * 4;
      ctx.strokeStyle = isFlashing ? '#ffffff' : b.color;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.arc(0, 0, b.size * 1.15 + auraPulse, 0, Math.PI * 2);
      ctx.stroke();

      // NG+ Cycle Prismatic Double Aura
      if (b.cycle && b.cycle > 1) {
        ctx.save();
        ctx.strokeStyle = 'rgba(255, 215, 0, 0.75)';
        ctx.lineWidth = 2.0;
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 14;
        ctx.setLineDash([8, 5]);
        ctx.lineDashOffset = performance.now() / 25;
        ctx.beginPath();
        ctx.arc(0, 0, b.size * 1.35, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      if (b.healPulseTimer && b.healPulseTimer > 0) {
        const pulseRatio = b.healPulseTimer / 600;
        ctx.save();
        ctx.strokeStyle = `rgba(0, 230, 118, ${pulseRatio * 0.9})`;
        ctx.lineWidth = 3;
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 18;
        ctx.beginPath();
        ctx.arc(0, 0, b.size * (1.2 + (1 - pulseRatio) * 0.7), 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      // Render Boss Sprite Sheet Animation or Fallback
      let renderedSprite = false;
      if (b.spriteSheetUrl) {
        const spriteImg = getBossSprite(b.spriteSheetUrl);
        if (spriteImg && spriteImg.complete && spriteImg.naturalWidth > 0) {
          ctx.save();
          const frameWidth = spriteImg.naturalWidth / 3;
          const frameHeight = spriteImg.naturalHeight;
          const aspect = frameWidth / frameHeight;
          const renderHeight = b.size * 2.8;
          const renderWidth = renderHeight * aspect;

          // Frame determination: 0=Idle, 1=Windup, 2=Attack
          let frameIdx = b.frameIndex || 0;
          if (b.animState === 'WINDUP') frameIdx = 1;
          else if (b.animState === 'ATTACK') frameIdx = 2;

          // Procedural breath scale during idle
          const breath = b.animState === 'IDLE' ? 1 + Math.sin(performance.now() / 250) * 0.03 : 1;
          ctx.scale(breath, breath);

          // Hit flash brightness filter
          if (isFlashing) {
            ctx.filter = 'brightness(2.4) contrast(1.2)';
          }

          ctx.drawImage(
            spriteImg,
            frameIdx * frameWidth, 0, frameWidth, frameHeight,
            -renderWidth / 2, -renderHeight / 2, renderWidth, renderHeight
          );
          ctx.restore();
          renderedSprite = true;
        }
      }

      if (!renderedSprite) {
        let iconKey = 'bee';
        if (b.type === 'REAPER_UFO' || (b.type as string) === 'PEPE_FROG') iconKey = 'ufo';
        else if (b.type === 'WHALE_KING' || (b.type as string) === 'WHALE_GOD') iconKey = 'whale';
        else if (b.type === 'FED_GOLEM' || (b.type as string) === 'WIF_HAT') iconKey = 'fed_golem';
        else if (b.type === 'POW_TITAN' || (b.type as string) === 'BONK_MASTER') iconKey = 'pow_titan';
        else if (b.type === 'VOID_CEX' || (b.type as string) === 'POPCAT_OVERLORD' || (b.type as string) === 'CEX_VOID') iconKey = 'cex_void';
        else if (b.type === 'MEME_SHIBA' || (b.type as string) === 'FLOKI_VIKING') iconKey = 'meme_shiba';
        else if (b.type === 'HFT_CYBORG' || (b.type as string) === 'MOODENG_TERROR') iconKey = 'hft_cyborg';
        else if (b.type === 'EXPLOIT_DEMON' || (b.type as string) === 'WOJAK_TRADER') iconKey = 'exploit_demon';
        else if (b.type === 'BLACK_SWAN_OMEGA' || (b.type as string) === 'GIGACHAD_OMEGA') iconKey = 'spectre';

        const bossPath = getSurvivorPath2D(iconKey);
        if (bossPath) {
          ctx.save();
          const scale = (b.size * 2.3) / 512;
          ctx.scale(scale, scale);
          ctx.translate(-256, -256);
          ctx.fillStyle = isFlashing ? '#ffffff' : b.color;
          ctx.fill(bossPath);
          ctx.restore();
        } else {
          ctx.fillStyle = b.color;
          ctx.beginPath();
          ctx.arc(0, 0, b.size, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      const crownPath = getSurvivorPath2D('crown');
      if (crownPath) {
        ctx.save();
        ctx.translate(0, -b.size * 0.95);
        ctx.scale(18 / 512, 18 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = '#ffd700';
        ctx.shadowColor = '#ffd700';
        ctx.shadowBlur = 10;
        ctx.fill(crownPath);
        ctx.restore();
      }

      ctx.restore();

      // 10.6 Render Boss Clones & Emerald Tether Link
      if (b.clones && b.clones.length > 0) {
        for (const clone of b.clones) {
          // Emerald Tether Line between Main Boss and Clone
          ctx.save();
          ctx.strokeStyle = `rgba(0, 229, 255, ${0.45 + Math.sin(performance.now() / 90) * 0.25})`;
          ctx.lineWidth = 2.5;
          ctx.shadowColor = '#00e5ff';
          ctx.shadowBlur = 10;
          ctx.setLineDash([8, 6]);
          ctx.lineDashOffset = -performance.now() / 25;
          ctx.beginPath();
          ctx.moveTo(b.x, b.y);
          ctx.lineTo(clone.x, clone.y);
          ctx.stroke();
          ctx.restore();

          // Render Clone Entity
          ctx.save();
          ctx.translate(clone.x, clone.y);
          const cFlash = clone.hitFlashTimer && clone.hitFlashTimer > 0;

          // Resonant ethereal glow ring
          ctx.save();
          ctx.shadowColor = cFlash ? '#ffffff' : '#00e5ff';
          ctx.shadowBlur = cFlash ? 26 : 18;
          ctx.strokeStyle = cFlash ? '#ffffff' : 'rgba(0, 229, 255, 0.75)';
          ctx.lineWidth = 2.5;
          ctx.beginPath();
          ctx.arc(0, 0, clone.size * 1.15, 0, Math.PI * 2);
          ctx.stroke();
          ctx.restore();

          let renderedCloneSprite = false;
          if (clone.spriteSheetUrl) {
            const spriteImg = getBossSprite(clone.spriteSheetUrl);
            if (spriteImg && spriteImg.complete && spriteImg.naturalWidth > 0) {
              ctx.save();
              const frameWidth = spriteImg.naturalWidth / 3;
              const frameHeight = spriteImg.naturalHeight;
              const aspect = frameWidth / frameHeight;
              const renderHeight = clone.size * 2.8;
              const renderWidth = renderHeight * aspect;

              let frameIdx = clone.frameIndex || 0;
              if (clone.animState === 'WINDUP') frameIdx = 1;
              else if (clone.animState === 'ATTACK') frameIdx = 2;

              const breath = clone.animState === 'IDLE' ? 1 + Math.sin((performance.now() + 500) / 250) * 0.03 : 1;
              ctx.scale(breath, breath);

              if (cFlash) {
                ctx.filter = 'brightness(2.4) contrast(1.2)';
              } else {
                ctx.globalAlpha = 0.92;
              }

              ctx.drawImage(
                spriteImg,
                frameIdx * frameWidth, 0, frameWidth, frameHeight,
                -renderWidth / 2, -renderHeight / 2, renderWidth, renderHeight
              );
              ctx.restore();
              renderedCloneSprite = true;
            }
          }

          if (!renderedCloneSprite) {
            let iconKey = 'bee';
            if (clone.type === 'PEPE_FROG' || (clone.type as string) === 'REAPER_UFO') iconKey = 'ufo';
            else if (clone.type === 'POPCAT_OVERLORD' || (clone.type as string) === 'VOID_CEX') iconKey = 'cex_void';

            const bossPath = getSurvivorPath2D(iconKey);
            if (bossPath) {
              ctx.save();
              const scale = (clone.size * 2.3) / 512;
              ctx.scale(scale, scale);
              ctx.translate(-256, -256);
              ctx.fillStyle = cFlash ? '#ffffff' : clone.color;
              ctx.fill(bossPath);
              ctx.restore();
            } else {
              ctx.fillStyle = clone.color;
              ctx.beginPath();
              ctx.arc(0, 0, clone.size, 0, Math.PI * 2);
              ctx.fill();
            }
          }

          // Overhead mini-shield health bar & title label
          if (clone.maxHp > 0) {
            const cRatio = Math.max(0, Math.min(1.0, clone.hp / clone.maxHp));
            const barW = Math.max(46, clone.size * 1.5);
            const barH = 5;
            const barY = -clone.size - 16;

            // Bar background & border
            ctx.fillStyle = 'rgba(10, 16, 26, 0.9)';
            ctx.fillRect(-barW / 2, barY, barW, barH);
            ctx.strokeStyle = '#00e5ff';
            ctx.lineWidth = 1;
            ctx.strokeRect(-barW / 2, barY, barW, barH);

            // Cyan shield fill
            ctx.fillStyle = '#00e5ff';
            ctx.shadowColor = '#00e5ff';
            ctx.shadowBlur = 6;
            ctx.fillRect(-barW / 2, barY, barW * cRatio, barH);
            ctx.shadowBlur = 0;

            // Overhead clone tag
            ctx.font = '900 9px system-ui, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillStyle = '#00e5ff';
            const cloneTag = clone.type === 'PEPE_FROG' ? '🐸 雙生幻影' : '🐱 啵啵分身';
            ctx.fillText(cloneTag, 0, barY - 4);
          }
          ctx.restore();
        }
      }

      // 10.7 Render Main Boss Aegis Shield Barrier when Immune
      if (b.isImmune && b.shieldHp && b.shieldHp > 0) {
        ctx.save();
        ctx.translate(b.x, b.y);
        const shieldPulse = Math.sin(performance.now() / 100) * 3;
        ctx.strokeStyle = 'rgba(0, 229, 255, 0.85)';
        ctx.lineWidth = 3;
        ctx.shadowColor = '#00e5ff';
        ctx.shadowBlur = 18;
        ctx.setLineDash([12, 6]);
        ctx.lineDashOffset = performance.now() / 30;
        ctx.beginPath();
        ctx.arc(0, 0, b.size * 1.35 + shieldPulse, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }
    }

    // 11. Render Player (SNEK Mascot Face)
    ctx.save();
    ctx.translate(engine.px, engine.py);

    if (engine.invulnerableTimer > 0 && Math.floor(performance.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.45;
    }

    if (engine.rocketTimer > 0) {
      ctx.strokeStyle = '#ff3d00';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 16;
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize * 1.5, 0, Math.PI * 2);
      ctx.stroke();
    } else {
      ctx.strokeStyle = engine.isFever ? 'rgba(255, 215, 0, 0.8)' : 'rgba(0, 230, 118, 0.4)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize * 1.35, 0, Math.PI * 2);
      ctx.stroke();
    }

    if (engine.imageLoaded && engine.headImage.complete) {
      const renderSize = engine.playerSize * 2.2;
      ctx.drawImage(engine.headImage, -renderSize / 2, -renderSize / 2, renderSize, renderSize);
    } else {
      ctx.fillStyle = '#4ade80';
      ctx.beginPath();
      ctx.arc(0, 0, engine.playerSize, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    // 12. Floating Heal Texts
    for (const ft of engine.bossFloatingTexts) {
      ctx.save();
      const alpha = Math.max(0, ft.life / ft.maxLife);
      ctx.fillStyle = ft.color;
      ctx.globalAlpha = alpha;
      ctx.font = '900 13px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.shadowColor = ft.color;
      ctx.shadowBlur = 8;
      ctx.fillText(ft.text, ft.x, ft.y);
      ctx.restore();
    }

    // 13. Siphon Energy Orbs
    for (const orb of engine.siphonOrbs) {
      ctx.save();
      const alpha = Math.max(0, 1 - orb.progress);
      ctx.fillStyle = orb.color;
      ctx.globalAlpha = alpha;
      ctx.shadowColor = orb.color;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(orb.x, orb.y, 4.5, 0, Math.PI * 2);
      ctx.fill();

      // Incandescent pure white energy essence core
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(orb.x, orb.y, 2.0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 14. Arcade Mega Boss Health Bar at Top
    if (engine.currentBoss && engine.bossWarningTimer <= 0) {
      const b = engine.currentBoss;
      ctx.save();
      const barW = Math.min(320, engine.width - 32);
      const barH = 9;
      const barX = (engine.width - barW) / 2;
      const barY = 20;

      ctx.fillStyle = 'rgba(10, 15, 26, 0.9)';
      ctx.fillRect(barX - 2, barY - 2, barW + 4, barH + 4);
      ctx.strokeStyle = b.color;
      ctx.lineWidth = 1.5;
      ctx.shadowColor = b.color;
      ctx.shadowBlur = 12;
      ctx.strokeRect(barX - 2, barY - 2, barW + 4, barH + 4);

      const ratio = Math.max(0, Math.min(1.0, b.hp / b.maxHp));
      const fillW = Math.round(barW * ratio);
      if (fillW > 0) {
        const hpGrad = ctx.createLinearGradient(barX, barY, barX + barW, barY);
        hpGrad.addColorStop(0, '#ff1744');
        hpGrad.addColorStop(0.5, b.color);
        hpGrad.addColorStop(1, '#ffffff');
        ctx.fillStyle = hpGrad;
        ctx.fillRect(barX, barY, fillW, barH);
      }

      // Secondary Cyan Shield Bar Overlay
      if (b.shieldHp && b.shieldHp > 0 && b.maxShieldHp) {
        const sRatio = Math.max(0, Math.min(1.0, b.shieldHp / b.maxShieldHp));
        const sW = Math.round(barW * sRatio);
        if (sW > 0) {
          ctx.save();
          ctx.fillStyle = 'rgba(0, 229, 255, 0.88)';
          ctx.shadowColor = '#00e5ff';
          ctx.shadowBlur = 10;
          ctx.fillRect(barX, barY - 1, sW, barH + 2);
          ctx.restore();
        }
        ctx.save();
        ctx.font = '900 10px system-ui, sans-serif';
        ctx.fillStyle = '#00e5ff';
        ctx.textAlign = 'center';
        ctx.fillText(`🛡️ 共振護盾 SHIELD: ${Math.ceil(b.shieldHp)} / ${b.maxShieldHp}`, barX + barW / 2, barY + barH + 11);
        ctx.restore();
      }

      ctx.shadowBlur = 0;
      ctx.font = '900 11px system-ui, sans-serif';
      ctx.textAlign = 'left';
      ctx.fillStyle = b.color;
      ctx.fillText(b.title, barX, barY - 5);

      ctx.textAlign = 'right';
      ctx.font = '700 10px system-ui, sans-serif';
      ctx.fillStyle = '#f8fafc';
      ctx.fillText(`${Math.ceil(b.hp)} / ${b.maxHp}`, barX + barW, barY - 5);
      ctx.restore();
    }

    // 15. Boss Approaching Warning Banner
    if (engine.bossWarningTimer > 0) {
      ctx.save();
      const bannerY = engine.height / 2 - 38;
      const bannerH = 76;
      const flash = Math.floor(performance.now() / 120) % 2 === 0;

      ctx.fillStyle = flash ? 'rgba(183, 28, 28, 0.94)' : 'rgba(136, 14, 79, 0.94)';
      ctx.fillRect(0, bannerY, engine.width, bannerH);

      ctx.strokeStyle = '#ffd600';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 14;
      ctx.strokeRect(0, bannerY, engine.width, bannerH);

      ctx.textAlign = 'center';
      ctx.font = '900 16px system-ui, sans-serif';
      ctx.fillStyle = '#ffd600';
      ctx.shadowColor = '#ff6d00';
      ctx.shadowBlur = 12;
      ctx.fillText('⚠️ WARNING: BOSS APPROACHING ⚠️', engine.width / 2, bannerY + 28);

      ctx.font = '700 12px system-ui, sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.shadowBlur = 6;
      ctx.fillText('GALAGA AIR RAID DETECTED', engine.width / 2, bannerY + 54);
      ctx.restore();
    }

    // 16. Stage Clear Victory Banner
    if (engine.stageClearTimer > 0) {
      ctx.save();
      const bannerY = engine.height / 2 - 40;
      const bannerH = 80;

      ctx.fillStyle = 'rgba(6, 78, 59, 0.94)';
      ctx.fillRect(0, bannerY, engine.width, bannerH);

      ctx.strokeStyle = '#10b981';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = '#34d399';
      ctx.shadowBlur = 14;
      ctx.strokeRect(0, bannerY, engine.width, bannerH);

      ctx.textAlign = 'center';
      ctx.font = '900 18px system-ui, sans-serif';
      ctx.fillStyle = '#a7f3d0';
      ctx.fillText(`🏆 ${engine.stageClearTitle}`, engine.width / 2, bannerY + 32);

      const cycle = Math.floor((engine.stage - 1) / 4) + 1;
      const cycleText = cycle > 1 ? ` (輪迴 ${cycle})` : '';

      ctx.font = '700 12px system-ui, sans-serif';
      ctx.fillStyle = '#ffffff';
      ctx.shadowBlur = 0;
      ctx.fillText(`STAGE ${engine.stage}${cycleText} NOW COMMENCING`, engine.width / 2, bannerY + 58);
      ctx.restore();
    }

    // 16.5 Stage & Macro Event Alert Banner
    if (engine.stageAlert && engine.stageAlert.timer > 0) {
      ctx.save();
      const elapsed = engine.stageAlert.maxTimer - engine.stageAlert.timer;
      let alpha = 1.0;
      if (elapsed < 0.3) {
        alpha = Math.max(0.3, elapsed / 0.3);
      } else if (engine.stageAlert.timer < 0.4) {
        alpha = Math.max(0, engine.stageAlert.timer / 0.4);
      }
      ctx.globalAlpha = alpha;

      const bannerY = engine.height / 2 - 36;
      ctx.fillStyle = 'rgba(6, 10, 18, 0.92)';
      ctx.fillRect(0, bannerY, engine.width, 70);

      ctx.strokeStyle = '#ffd700';
      ctx.lineWidth = 2;
      ctx.shadowColor = '#ffd700';
      ctx.shadowBlur = 16;
      ctx.strokeRect(0, bannerY, engine.width, 70);

      ctx.textAlign = 'center';
      ctx.font = '900 15px system-ui, sans-serif';
      ctx.fillStyle = '#ffd700';
      ctx.fillText(engine.stageAlert.title, engine.width / 2, bannerY + 28);

      ctx.font = '500 11px system-ui, sans-serif';
      ctx.fillStyle = '#cbd5e1';
      ctx.shadowBlur = 0;
      ctx.fillText(engine.stageAlert.subtitle, engine.width / 2, bannerY + 52);
      ctx.restore();
    }

    // 17. Nuke Screen Flash
    if (engine.nukeFlashTimer > 0) {
      ctx.save();
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(0.85, engine.nukeFlashTimer * 2.5)})`;
      ctx.fillRect(0, 0, engine.width, engine.height);
      ctx.restore();
    }

    ctx.restore();
  }
}
