import { Enemy, BossEntity, Projectile, BattlefieldPickup, BossCloneEntity } from '../types.ts';

export interface PlayerCollisionState {
  x: number;
  y: number;
  size: number;
  damageReduction?: number;
}

export class CollisionSystem {
  /**
   * Simple circle vs circle collision check.
   */
  public checkCircleOverlap(
    x1: number,
    y1: number,
    r1: number,
    x2: number,
    y2: number,
    r2: number
  ): boolean {
    return Math.hypot(x1 - x2, y1 - y2) < r1 + r2;
  }

  /**
   * Resolve collisions between Player and regular Enemies (or rocket ramming).
   */
  public resolvePlayerEnemyCollisions(params: {
    player: PlayerCollisionState;
    enemies: Enemy[];
    rocketTimer: number;
    freezeTimer: number;
    invulnerableTimer: number;
    getMonsterContactDamage: (e: Enemy) => number;
    onPlayerDamage: (damage: number) => void;
    onRocketHitEnemy: (index: number, enemy: Enemy, damage: number) => void;
  }): void {
    const {
      player,
      enemies,
      rocketTimer,
      freezeTimer,
      invulnerableTimer,
      getMonsterContactDamage,
      onPlayerDamage,
      onRocketHitEnemy,
    } = params;

    for (let i = enemies.length - 1; i >= 0; i--) {
      const e = enemies[i];
      const dist = Math.hypot(player.x - e.x, player.y - e.y);

      if (dist < player.size + e.size) {
        if (rocketTimer > 0) {
          // Bottom-fishing Rocket Ramming
          onRocketHitEnemy(i, e, 120);
        } else if (freezeTimer <= 0 && invulnerableTimer <= 0) {
          const rawDmg = getMonsterContactDamage(e);
          const reduction = player.damageReduction || 0;
          const finalDmg = Math.max(3, Math.floor(rawDmg * (1 - Math.min(0.4, reduction))));
          onPlayerDamage(finalDmg);
        }
      }
    }
  }

  /**
   * Resolve collisions between Player during Rocket Dash and Boss entity.
   */
  public resolveRocketBossCollision(params: {
    player: PlayerCollisionState;
    boss: BossEntity | null;
    rocketTimer: number;
    onBossHit: (boss: BossEntity, damage: number) => void;
  }): void {
    const { player, boss, rocketTimer, onBossHit } = params;
    if (!boss || rocketTimer <= 0) return;

    const bossDist = Math.hypot(player.x - boss.x, player.y - boss.y);
    if (bossDist < player.size + boss.size + 10) {
      onBossHit(boss, 180);
    }
  }

  /**
   * Resolve collisions between active projectiles and entities (Boss prioritized over enemies).
   */
  public resolveProjectileCollisions(params: {
    projectiles: Projectile[];
    enemies: Enemy[];
    boss: BossEntity | null;
    clones?: BossCloneEntity[];
    damageMultiplier: number;
    onHitBoss: (boss: BossEntity, damage: number, p: Projectile) => void;
    onHitClone?: (clone: BossCloneEntity, damage: number, p: Projectile) => void;
    onHitEnemy: (enemyIndex: number, enemy: Enemy, damage: number, p: Projectile) => void;
  }): void {
    const { projectiles, enemies, boss, clones, damageMultiplier, onHitBoss, onHitClone, onHitEnemy } = params;

    for (let i = projectiles.length - 1; i >= 0; i--) {
      const p = projectiles[i];
      let hit = false;

      // 1. Check clone hit first (protecting boss)
      if (clones && clones.length > 0) {
        for (const clone of clones) {
          if (Math.hypot(p.x - clone.x, p.y - clone.y) < clone.size + 8) {
            const dmg = p.damage * damageMultiplier;
            onHitClone?.(clone, dmg, p);
            hit = true;
            break;
          }
        }
      }

      // 2. Check boss hit
      if (!hit && boss && Math.hypot(p.x - boss.x, p.y - boss.y) < boss.size + 8) {
        const dmg = p.damage * damageMultiplier;
        onHitBoss(boss, dmg, p);
        hit = true;
      }

      // 3. If no boss or clone hit, check enemies
      if (!hit) {
        for (let j = enemies.length - 1; j >= 0; j--) {
          const e = enemies[j];
          if (Math.hypot(p.x - e.x, p.y - e.y) < e.size + 6) {
            const dmg = p.damage * damageMultiplier;
            onHitEnemy(j, e, dmg, p);
            hit = true;
            break;
          }
        }
      }

      if (hit) {
        projectiles.splice(i, 1);
      }
    }
  }

  /**
   * Resolve player pickup collection.
   */
  public resolvePickupCollisions(params: {
    player: PlayerCollisionState;
    pickups: BattlefieldPickup[];
    onCollectPickup: (pickup: BattlefieldPickup) => void;
  }): void {
    const { player, pickups, onCollectPickup } = params;

    for (let i = pickups.length - 1; i >= 0; i--) {
      const p = pickups[i];
      const dist = Math.hypot(player.x - p.x, player.y - p.y);
      if (dist < player.size + 16) {
        onCollectPickup(p);
        pickups.splice(i, 1);
      }
    }
  }
}
