import { BossEntity, BossType } from '../types.ts';
import { I18nService } from '../../../platform/I18nService.ts';

export class BossFactory {
  public static createBoss(stage: number, arenaWidth: number): BossEntity {
    const cycle = Math.floor((stage - 1) / 10) + 1;
    const stageInCycle = ((stage - 1) % 10) + 1;

    let type: BossType = 'DOGE_KING';
    let baseTitle = '始祖神犬 · DOGE KING';
    let baseHp = 2200;
    let size = 38;
    let color = '#ffd700';
    let svgIconPath = './assets/bosses/boss_doge_spritesheet.png';
    let hoverSpeedBase = 1.8;

    switch (stageInCycle) {
      case 1:
        type = 'DOGE_KING';
        baseTitle = '始祖神犬 · DOGE KING';
        baseHp = 12000;
        size = 38;
        color = '#ffd700';
        svgIconPath = './assets/bosses/boss_doge_spritesheet.png';
        hoverSpeedBase = 1.8;
        break;
      case 2:
        type = 'PEPE_FROG';
        baseTitle = '悲傷蛙神 · PEPE THE FROG';
        baseHp = 35000;
        size = 40;
        color = '#00e676';
        svgIconPath = './assets/bosses/boss_pepe_spritesheet.png';
        hoverSpeedBase = 2.2;
        break;
      case 3:
        type = 'WHALE_GOD';
        baseTitle = '萬億巨鯨 · WHALE GOD';
        baseHp = 80000;
        size = 48;
        color = '#00b0ff';
        svgIconPath = './assets/bosses/boss_whale_spritesheet.png';
        hoverSpeedBase = 1.2;
        break;
      case 4:
        type = 'WIF_HAT';
        baseTitle = '戴帽神柴 · DOGWIFHAT';
        baseHp = 160000;
        size = 42;
        color = '#ff4081';
        svgIconPath = './assets/bosses/boss_wif_spritesheet.png';
        hoverSpeedBase = 1.5;
        break;
      case 5:
        type = 'BONK_MASTER';
        baseTitle = '球棒制裁者 · BONK MASTER';
        baseHp = 300000;
        size = 46;
        color = '#ff9100';
        svgIconPath = './assets/bosses/boss_bonk_spritesheet.png';
        hoverSpeedBase = 1.4;
        break;
      case 6:
        type = 'POPCAT_OVERLORD';
        baseTitle = '魔性啵啵貓 · POPCAT OVERLORD';
        baseHp = 550000;
        size = 44;
        color = '#00e5ff';
        svgIconPath = './assets/bosses/boss_popcat_spritesheet.png';
        hoverSpeedBase = 2.0;
        break;
      case 7:
        type = 'FLOKI_VIKING';
        baseTitle = '維京海盜王 · FLOKI THE VIKING';
        baseHp = 950000;
        size = 44;
        color = '#ffab00';
        svgIconPath = './assets/bosses/boss_floki_spritesheet.png';
        hoverSpeedBase = 2.2;
        break;
      case 8:
        type = 'MOODENG_TERROR';
        baseTitle = '暴躁彈跳豬 · MOO DENG';
        baseHp = 1600000;
        size = 42;
        color = '#ea80fc';
        svgIconPath = './assets/bosses/boss_moodeng_spritesheet.png';
        hoverSpeedBase = 2.6;
        break;
      case 9:
        type = 'WOJAK_TRADER';
        baseTitle = '麥當勞哭哭男 · WOJAK DOWN-ONLY';
        baseHp = 2800000;
        size = 46;
        color = '#ff1744';
        svgIconPath = './assets/bosses/boss_wojak_spritesheet.png';
        hoverSpeedBase = 1.6;
        break;
      case 10:
        type = 'GIGACHAD_OMEGA';
        baseTitle = '終極完美型男 · GIGACHAD ASCENDED';
        baseHp = 5000000;
        size = 54;
        color = '#ffd700';
        svgIconPath = './assets/bosses/boss_gigachad_spritesheet.png';
        hoverSpeedBase = 2.5;
        break;
    }

    const hpMult = 1.0 + (cycle - 1) * 1.10;
    const stageDmgMult = 1.0 + (stageInCycle - 1) * 0.15;
    const cycleDmgMult = 1.0 + (cycle - 1) * 0.30;
    const dmgMult = Number((stageDmgMult * cycleDmgMult).toFixed(2));
    const speedMult = Math.min(1.45, 1.0 + (cycle - 1) * 0.12);

    const hp = Math.floor(baseHp * hpMult);
    const i18n = I18nService.getInstance();
    const localizedTitle = i18n.t(`boss.${type}`) || baseTitle;
    const loopPrefix = i18n.getLocale() === 'en' ? `[NG+${cycle}] ` : `【輪迴 ${cycle}】`;
    const title = cycle > 1 ? `${loopPrefix}${localizedTitle} Mk-${cycle}` : localizedTitle;
    const hasLaser = type === 'PEPE_FROG' || type === 'GIGACHAD_OMEGA';

    return {
      id: `boss_${type}_${Date.now()}`,
      type,
      title,
      stage,
      cycle,
      damageMultiplier: dmgMult,
      whaleMobSpawnTimer: 0,
      siphonTendrilTimer: 0,
      x: arenaWidth / 2,
      y: -60,
      size,
      hp,
      maxHp: hp,
      color,
      svgIconPath,
      spriteSheetUrl: svgIconPath,
      frameIndex: 0,
      animState: 'IDLE',
      animTimer: 0,
      state: 'ENTERING',
      stateTimer: 0,
      hoverBaseY: 130,
      hoverAngle: 0,
      hoverSpeed: hoverSpeedBase * speedMult,
      diveStartX: arenaWidth / 2,
      diveStartY: 90,
      diveTargetX: arenaWidth / 2,
      diveTargetY: 600,
      diveControlX: arenaWidth / 2,
      diveControlY: 300,
      diveProgress: 0,
      shootTimer: 0,
      tractorBeamActive: false,
      tractorTimer: 0,
      hitFlashTimer: 0,
      isBerserk: false,
      telegraphs: [],
      bombs: [],
      shockwaves: [],
      hook: type === 'POPCAT_OVERLORD' ? {
        active: false,
        phase: 'IDLE',
        startX: arenaWidth / 2,
        startY: 130,
        currX: arenaWidth / 2,
        currY: 130,
        targetX: arenaWidth / 2,
        targetY: 600,
        speed: 12,
        hasCaughtPlayer: false,
        damage: Math.round(15 * dmgMult),
      } : undefined,
      laser: hasLaser ? {
        active: false,
        phase: 'NONE',
        timer: 0,
        startX: arenaWidth / 2,
        startY: 90,
        angle: Math.PI / 2,
        targetAngle: Math.PI / 2,
        sweepSpeed: 0,
        width: type === 'GIGACHAD_OMEGA' ? 32 : 24,
        damage: Math.round((type === 'GIGACHAD_OMEGA' ? 24 : 15) * dmgMult),
        color: type === 'GIGACHAD_OMEGA' ? '#ffd700' : '#00e676',
        glowColor: type === 'GIGACHAD_OMEGA' ? '#ffab00' : '#00b0ff',
      } : undefined,
      laserAttackTimer: 0,
      healPulseTimer: 0,
      spreadWaveTimer: 0,
      specialCooldown: 0,
    };
  }
}
