import { CURRENT_SAVE_SCHEMA_VERSION, SurvivorSaveData } from './types.ts';

type MigrationFn = (oldData: any) => any;

export class SaveMigrationEngine {
  private static migrations: Record<number, MigrationFn> = {
    // Migration to Version 1 (Handles unversioned legacy or baseline schema)
    1: (raw: any): SurvivorSaveData => {
      const highestStage = Number(raw?.highestStageUnlocked);
      const defeatedBossStages = Array.isArray(raw?.defeatedBossStages)
        ? raw.defeatedBossStages.map(Number).filter((n: number) => !isNaN(n))
        : [];
      const bossSnapshots =
        typeof raw?.bossSnapshots === 'object' && raw.bossSnapshots !== null
          ? raw.bossSnapshots
          : {};

      return {
        version: 1,
        lastSavedAt: typeof raw?.lastSavedAt === 'number' ? raw.lastSavedAt : Date.now(),
        highestStageUnlocked: isNaN(highestStage) || highestStage < 1 ? 1 : highestStage,
        defeatedBossStages,
        bossSnapshots,
      };
    },
  };

  public static createDefaultSaveData(): SurvivorSaveData {
    return {
      version: CURRENT_SAVE_SCHEMA_VERSION,
      lastSavedAt: Date.now(),
      highestStageUnlocked: 1,
      defeatedBossStages: [],
      bossSnapshots: {},
    };
  }

  public static migrate(rawData: any): SurvivorSaveData {
    if (!rawData || typeof rawData !== 'object') {
      return this.createDefaultSaveData();
    }

    try {
      let currentData = { ...rawData };
      let currentVersion = typeof currentData.version === 'number' ? currentData.version : 0;

      while (currentVersion < CURRENT_SAVE_SCHEMA_VERSION) {
        const nextVersion = currentVersion + 1;
        const migrationFn = this.migrations[nextVersion];
        if (typeof migrationFn === 'function') {
          currentData = migrationFn(currentData);
          currentVersion = nextVersion;
        } else {
          break;
        }
      }

      if (
        typeof currentData.version !== 'number' ||
        !Array.isArray(currentData.defeatedBossStages) ||
        typeof currentData.bossSnapshots !== 'object' ||
        currentData.bossSnapshots === null
      ) {
        return this.createDefaultSaveData();
      }

      return currentData as SurvivorSaveData;
    } catch {
      return this.createDefaultSaveData();
    }
  }
}
