import { Enemy } from '../types.ts';

export class LevelCurves {
  public static getNextExpForLevel(lvl: number): number {
    if (lvl === 1) return 12;
    if (lvl === 2) return 24;
    if (lvl === 3) return 45;
    if (lvl === 4) return 75;
    if (lvl === 5) return 120;
    if (lvl <= 10) return 120 + (lvl - 5) * 45;
    if (lvl <= 15) return 345 + (lvl - 10) * 75;
    if (lvl <= 20) return 720 + (lvl - 15) * 110;
    if (lvl <= 25) return 1270 + (lvl - 20) * 150;
    return 2020 + Math.floor(Math.pow(lvl - 25, 1.35) * 260);
  }

  public static getMonsterContactDamage(e: Enemy, stage: number, elapsedTime: number): number {
    let base = 12;
    if (e.type === 'RED_CANDLE') base = 12;
    else if (e.type === 'FLASH_BEETLE') base = 15;
    else if (e.type === 'BEAR') base = 18;
    else if (e.type === 'LIQUIDATION_REAPER') base = 26;
    else if (e.type === 'BLACK_SWAN') base = 32;
    else if (e.isBoss) base = 35;

    const stageMult = 1 + (stage - 1) * 0.4;
    const timeMult = 1 + (elapsedTime / 120) * 0.2;
    return Math.round(base * stageMult * timeMult);
  }

  public static getTargetLevelForStage(stage: number): number {
    return Math.max(1, stage) * 10;
  }
}
