import { SurvivorEngine } from '../games/survivor/SurvivorEngine.ts';
import { I18nService } from '../platform/I18nService.ts';

export function isDebugMode(): boolean {
  if (typeof window === 'undefined') return false;
  try {
    if (window.location.href.includes('debug=snek')) return true;
    if (
      window.parent &&
      window.parent !== window &&
      window.parent.location.href.includes('debug=snek')
    ) {
      return true;
    }
    if (
      localStorage.getItem('snek_debug') === 'snek' ||
      localStorage.getItem('snek_debug') === 'true'
    ) {
      return true;
    }
  } catch {}
  return false;
}

export interface GMTelemetry {
  fps: number;
  stage: number;
  level: number;
  hp: number;
  maxHp: number;
  enemiesCount: number;
  projectilesCount: number;
  pickupsCount: number;
  bossActive: boolean;
  bossType?: string;
  bossHp?: number;
}

export class GMDebugOverlay {
  private engine: SurvivorEngine;
  private visible: boolean = false;
  private godMode: boolean = false;
  private damageBoosted: boolean = false;
  private container: HTMLDivElement | null = null;
  private triggerBtn: HTMLButtonElement | null = null;
  private onKeyDownBound: (e: KeyboardEvent) => void;
  private updateIntervalId: number | null = null;

  // FPS tracking
  private lastFpsUpdate: number = typeof performance !== 'undefined' ? performance.now() : 0;
  private frameCount: number = 0;
  private currentFps: number = 60;

  constructor(engine: SurvivorEngine) {
    this.engine = engine;
    this.onKeyDownBound = this.handleKeyDown.bind(this);

    if (typeof window !== 'undefined') {
      window.addEventListener('keydown', this.onKeyDownBound);
      this.createUI();
    }
  }

  private handleKeyDown(e: KeyboardEvent): void {
    if (e.code === 'Backquote') {
      e.preventDefault();
      this.toggle();
    }
  }

  public isVisible(): boolean {
    return this.visible;
  }

  public show(): void {
    this.visible = true;
    if (this.container) {
      this.container.style.display = 'block';
      this.startUpdating();
    }
  }

  public hide(): void {
    this.visible = false;
    if (this.container) {
      this.container.style.display = 'none';
      this.stopUpdating();
    }
  }

  public toggle(): void {
    if (this.visible) {
      this.hide();
    } else {
      this.show();
    }
  }

  public isGodMode(): boolean {
    return this.godMode;
  }

  public setGodMode(enabled: boolean): void {
    this.godMode = enabled;
    if (this.godMode) {
      this.applyGodModeUpdate();
    }
  }

  public applyGodModeUpdate(): void {
    if (this.godMode) {
      this.engine.hp = this.engine.maxHp;
    }
  }

  public isDamageBoosted(): boolean {
    return this.damageBoosted;
  }

  public setDamageBoost(enabled: boolean): void {
    this.damageBoosted = enabled;
    this.engine.damageMultiplier = enabled ? 50.0 : 1.0;
  }

  public toggleDamageBoost(): boolean {
    this.setDamageBoost(!this.damageBoosted);
    return this.damageBoosted;
  }

  public cutBossHp(fraction: number = 0.15): void {
    const boss = this.engine.currentBoss;
    if (!boss) return;

    // If boss is shielded, deduct from the shield bar first and trigger floating damage
    if (boss.isImmune && boss.shieldHp && boss.shieldHp > 0 && boss.maxShieldHp) {
      const shieldCut = Math.max(1, Math.round(boss.maxShieldHp * (fraction * 2.5)));
      this.engine.bossCombatController.cloneSystem.handleBossShieldDamage(boss, shieldCut);
      boss.hitFlashTimer = 150;
      this.engine.bossCombatController.deflectBossDamage(boss, boss.x, boss.y, shieldCut);
      return;
    }

    const cutAmount = Math.max(1, Math.round(boss.maxHp * fraction));
    boss.hp = Math.max(1, boss.hp - cutAmount);
    boss.hitFlashTimer = 150;
  }

  public setBossHpPercent(percent: number): void {
    const boss = this.engine.currentBoss;
    if (!boss) return;
    boss.hp = Math.max(1, Math.floor(boss.maxHp * percent));
    boss.hitFlashTimer = 150;
  }

  public warpToStage(stage: number): void {
    this.engine.stage = stage;
    this.engine.level = this.engine.getTargetLevelForStage(stage);
    this.engine.hp = this.engine.maxHp;

    // Clear existing non-boss mobs and any active boss
    this.engine.enemies = [];
    this.engine.bossCombatController.clear();
    this.engine.bossWarningTimer = 0;
    this.engine.stageClearTimer = 0;

    // Trigger target stage boss
    this.engine.triggerBossEncounter(stage);
  }

  public nukeAll(): void {
    let nonBossCount = 0;
    for (const e of this.engine.enemies) {
      if (!e.isBoss) {
        nonBossCount++;
        this.engine.particleSystem.emitDeath(e.x, e.y);
      }
    }
    this.engine.enemies = this.engine.enemies.filter(e => e.isBoss);
    this.engine.kills += nonBossCount;
  }

  public getTelemetry(): GMTelemetry {
    return {
      fps: this.currentFps,
      stage: this.engine.stage,
      level: this.engine.level,
      hp: this.engine.hp,
      maxHp: this.engine.maxHp,
      enemiesCount: this.engine.enemies.length,
      projectilesCount: this.engine.projectiles.length,
      pickupsCount: this.engine.pickups.length,
      bossActive: !!this.engine.currentBoss,
      bossType: this.engine.currentBoss?.type,
      bossHp: this.engine.currentBoss?.hp,
    };
  }

  private createUI(): void {
    if (typeof document === 'undefined') return;
    const i18n = I18nService.getInstance();

    this.container = document.createElement('div');
    this.container.id = 'gm-debug-overlay';
    this.container.style.cssText = `
      position: fixed;
      top: 12px;
      right: 12px;
      width: 300px;
      background: rgba(10, 16, 26, 0.94);
      border: 1px solid rgba(0, 230, 118, 0.6);
      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.8), 0 0 15px rgba(0, 230, 118, 0.2);
      border-radius: 8px;
      padding: 12px;
      color: #e0e0e0;
      font-family: monospace;
      font-size: 12px;
      z-index: 999999;
      display: none;
      user-select: none;
      backdrop-filter: blur(8px);
    `;

    this.container.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 6px; margin-bottom: 8px;">
        <span style="font-weight: bold; color: #00e676; font-size: 13px;">🛠️ ${i18n.t('gm.toolboxTitle')}</span>
        <button id="gm-btn-close" style="background: none; border: none; color: #888; font-size: 16px; cursor: pointer;">✕</button>
      </div>

      <div id="gm-telemetry" style="background: rgba(0,0,0,0.4); padding: 8px; border-radius: 4px; margin-bottom: 10px; line-height: 1.5;">
        <div>FPS: <span id="gm-fps" style="color: #ffd700;">60</span> | STAGE: <span id="gm-stage" style="color: #00e676;">1</span> (LV.<span id="gm-level">1</span>)</div>
        <div>HP: <span id="gm-hp">100/100</span></div>
        <div>MOBS: <span id="gm-mobs">0</span> | PROJ: <span id="gm-proj">0</span> | LOOT: <span id="gm-loot">0</span></div>
        <div id="gm-boss-info" style="color: #ff3d00; display: none;">BOSS: <span id="gm-boss-name">None</span> (<span id="gm-boss-hp">0</span> HP)</div>
      </div>

      <div style="margin-bottom: 8px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
        <button id="gm-btn-god" style="padding: 6px; background: #263238; border: 1px solid #455a64; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">🛡️ ${i18n.t('gm.godModeOff')}</button>
        <button id="gm-btn-nuke" style="padding: 6px; background: #b71c1c; border: 1px solid #e53935; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">💣 ${i18n.t('gm.nukeMobs')}</button>
        <button id="gm-btn-heal" style="padding: 6px; background: #1b5e20; border: 1px solid #2e7d32; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">❤️ ${i18n.t('gm.maxHp')}</button>
        <button id="gm-btn-lvl5" style="padding: 6px; background: #4a148c; border: 1px solid #7b1fa2; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">⬆️ ${i18n.t('gm.addLevels')}</button>
        <button id="gm-btn-lvl99" style="padding: 6px; background: #e65100; border: 1px solid #ff9800; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">⚡ ${i18n.t('gm.level99')}</button>
        <button id="gm-btn-spawn-heart" style="padding: 6px; background: #004d40; border: 1px solid #00bfa5; color: #64ffda; border-radius: 4px; cursor: pointer; font-size: 11px;">💚 ${i18n.t('gm.spawnHeart')}</button>
        <button id="gm-btn-victory" style="padding: 6px; background: #f57f17; border: 1px solid #ffd600; color: #000; font-weight: bold; border-radius: 4px; cursor: pointer; font-size: 11px;">🏆 ${i18n.t('gm.triggerVictory')}</button>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.1); padding-top: 6px; margin-bottom: 8px;">
        <div style="margin-bottom: 4px; color: #ff5252; font-size: 11px; font-weight: bold;">⚡ BOSS 測試與傷害倍增:</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
          <button id="gm-btn-dmg-boost" style="padding: 6px; background: #37474f; border: 1px solid #78909c; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px; font-weight: bold;">${i18n.t('gm.dmgBoostOff')}</button>
          <button id="gm-btn-cut-boss-hp" style="padding: 6px; background: #880e4f; border: 1px solid #ad1457; color: #fff; border-radius: 4px; cursor: pointer; font-size: 11px;">${i18n.t('gm.cutBossHp')}</button>
          <button id="gm-btn-hp-81" style="padding: 6px; background: #1b5e20; border: 1px solid #00e676; color: #00e676; border-radius: 4px; cursor: pointer; font-size: 11px;">${i18n.t('gm.setHp81')}</button>
          <button id="gm-btn-hp-51" style="padding: 6px; background: #01579b; border: 1px solid #00b0ff; color: #00b0ff; border-radius: 4px; cursor: pointer; font-size: 11px;">${i18n.t('gm.setHp51')}</button>
        </div>
      </div>

      <div style="border-top: 1px solid rgba(255,255,255,0.1); padding-top: 8px;">
        <div style="margin-bottom: 4px; color: #ffd700; font-size: 11px;">🚀 ${i18n.t('gm.warpBoss')}:</div>
        <select id="gm-select-stage" style="width: 100%; padding: 5px; background: #1e2638; border: 1px solid #3f51b5; color: #fff; border-radius: 4px; font-size: 11px; cursor: pointer;">
          <option value="1">Stage 1 - ${i18n.t('boss.DOGE_KING')}</option>
          <option value="2">Stage 2 - ${i18n.t('boss.PEPE_FROG')}</option>
          <option value="3">Stage 3 - ${i18n.t('boss.WHALE_GOD')}</option>
          <option value="4">Stage 4 - ${i18n.t('boss.WIF_HAT')}</option>
          <option value="5">Stage 5 - ${i18n.t('boss.BONK_MASTER')}</option>
          <option value="6">Stage 6 - ${i18n.t('boss.POPCAT_OVERLORD')}</option>
          <option value="7">Stage 7 - ${i18n.t('boss.FLOKI_VIKING')}</option>
          <option value="8">Stage 8 - ${i18n.t('boss.MOODENG_TERROR')}</option>
          <option value="9">Stage 9 - ${i18n.t('boss.WOJAK_TRADER')}</option>
          <option value="10">Stage 10 - ${i18n.t('boss.GIGACHAD_OMEGA')}</option>
        </select>
        <button id="gm-btn-warp" style="width: 100%; margin-top: 6px; padding: 6px; background: #00b0ff; border: none; color: #000; font-weight: bold; border-radius: 4px; cursor: pointer; font-size: 11px;">⚡ ${i18n.t('gm.jumpBtn')}</button>
      </div>
      <div style="margin-top: 8px; text-align: center; color: #666; font-size: 10px;">${i18n.t('gm.hotkeyTip')}</div>
    `;

    document.body.appendChild(this.container);

    // Floating GM button that is always accessible on screen
    this.triggerBtn = document.createElement('button');
    this.triggerBtn.id = 'gm-floating-trigger';
    this.triggerBtn.textContent = '🛠️ GM';
    this.triggerBtn.title = '切換 GM 除錯面板 (或按 ~ 鍵)';
    this.triggerBtn.style.cssText = `
      position: fixed;
      bottom: 18px;
      right: 18px;
      z-index: 999998;
      background: rgba(10, 16, 26, 0.92);
      border: 1px solid #00e676;
      color: #00e676;
      padding: 7px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 900;
      cursor: pointer;
      box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6), 0 0 12px rgba(0, 230, 118, 0.3);
      backdrop-filter: blur(8px);
      user-select: none;
    `;
    this.triggerBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggle();
    });
    document.body.appendChild(this.triggerBtn);

    // Bind UI actions
    this.container.querySelector('#gm-btn-close')?.addEventListener('click', () => this.hide());

    const btnGod = this.container.querySelector('#gm-btn-god') as HTMLButtonElement;
    btnGod?.addEventListener('click', () => {
      this.setGodMode(!this.godMode);
      btnGod.textContent = this.godMode ? `🛡️ ${i18n.t('gm.godModeOn')}` : `🛡️ ${i18n.t('gm.godModeOff')}`;
      btnGod.style.background = this.godMode ? '#00e676' : '#263238';
      btnGod.style.color = this.godMode ? '#000' : '#fff';
    });

    this.container.querySelector('#gm-btn-nuke')?.addEventListener('click', () => this.nukeAll());

    this.container.querySelector('#gm-btn-heal')?.addEventListener('click', () => {
      this.engine.hp = this.engine.maxHp;
    });

    this.container.querySelector('#gm-btn-lvl5')?.addEventListener('click', () => {
      for (let i = 0; i < 5; i++) {
        this.engine.level++;
      }
      this.engine.nextExp = this.engine.getNextExpForLevel(this.engine.level);
    });

    this.container.querySelector('#gm-btn-lvl99')?.addEventListener('click', () => {
      this.engine.level = 99;
      this.engine.nextExp = this.engine.getNextExpForLevel(99);
      this.engine.callbacks.onExpChange(this.engine.exp, this.engine.nextExp, this.engine.level);
    });

    this.container.querySelector('#gm-btn-spawn-heart')?.addEventListener('click', () => {
      this.engine.pickups.push({
        id: `gm_heart_${Date.now()}`,
        x: this.engine.px + 30,
        y: this.engine.py,
        type: 'HEART',
        life: 25000,
        bobAngle: 0,
      });
      this.engine.addFloatingText('💚 治癒之心已生成', '#00e676');
    });

    this.container.querySelector('#gm-btn-victory')?.addEventListener('click', () => {
      if (typeof this.engine.triggerGameClear === 'function') {
        this.engine.triggerGameClear();
      }
    });

    // Boss testing & stat boost actions
    const btnDmg = this.container.querySelector('#gm-btn-dmg-boost') as HTMLButtonElement;
    btnDmg?.addEventListener('click', () => {
      const active = this.toggleDamageBoost();
      btnDmg.textContent = active ? i18n.t('gm.dmgBoostOn') : i18n.t('gm.dmgBoostOff');
      btnDmg.style.background = active ? '#d50000' : '#37474f';
      btnDmg.style.borderColor = active ? '#ff1744' : '#78909c';
    });

    this.container.querySelector('#gm-btn-cut-boss-hp')?.addEventListener('click', () => {
      this.cutBossHp(0.15);
    });

    this.container.querySelector('#gm-btn-hp-81')?.addEventListener('click', () => {
      this.setBossHpPercent(0.81);
    });

    this.container.querySelector('#gm-btn-hp-51')?.addEventListener('click', () => {
      this.setBossHpPercent(0.51);
    });

    const selectStage = this.container.querySelector('#gm-select-stage') as HTMLSelectElement;
    this.container.querySelector('#gm-btn-warp')?.addEventListener('click', () => {
      const stage = parseInt(selectStage.value, 10) || 1;
      this.warpToStage(stage);
    });
  }

  private startUpdating(): void {
    if (this.updateIntervalId !== null) return;
    this.updateIntervalId = window.setInterval(() => {
      this.renderTelemetry();
      if (this.godMode) {
        this.applyGodModeUpdate();
      }
    }, 200);
  }

  private stopUpdating(): void {
    if (this.updateIntervalId !== null) {
      clearInterval(this.updateIntervalId);
      this.updateIntervalId = null;
    }
  }

  private renderTelemetry(): void {
    if (!this.container) return;

    if (typeof performance !== 'undefined') {
      const now = performance.now();
      this.frameCount++;
      const delta = now - this.lastFpsUpdate;
      if (delta >= 1000) {
        this.currentFps = Math.max(1, Math.round((this.frameCount * 1000) / delta));
        this.frameCount = 0;
        this.lastFpsUpdate = now;
      }
    }

    const t = this.getTelemetry();

    const fpsEl = this.container.querySelector('#gm-fps');
    const stageEl = this.container.querySelector('#gm-stage');
    const levelEl = this.container.querySelector('#gm-level');
    const hpEl = this.container.querySelector('#gm-hp');
    const mobsEl = this.container.querySelector('#gm-mobs');
    const projEl = this.container.querySelector('#gm-proj');
    const lootEl = this.container.querySelector('#gm-loot');
    const bossInfoEl = this.container.querySelector('#gm-boss-info') as HTMLElement;
    const bossNameEl = this.container.querySelector('#gm-boss-name');
    const bossHpEl = this.container.querySelector('#gm-boss-hp');

    if (fpsEl) fpsEl.textContent = t.fps.toString();
    if (stageEl) stageEl.textContent = t.stage.toString();
    if (levelEl) levelEl.textContent = t.level.toString();
    if (hpEl) hpEl.textContent = `${t.hp}/${t.maxHp}`;
    if (mobsEl) mobsEl.textContent = t.enemiesCount.toString();
    if (projEl) projEl.textContent = t.projectilesCount.toString();
    if (lootEl) lootEl.textContent = t.pickupsCount.toString();

    if (bossInfoEl) {
      if (t.bossActive) {
        bossInfoEl.style.display = 'block';
        if (bossNameEl) bossNameEl.textContent = t.bossType || 'BOSS';
        if (bossHpEl) bossHpEl.textContent = (t.bossHp || 0).toString();
      } else {
        bossInfoEl.style.display = 'none';
      }
    }
  }

  public destroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('keydown', this.onKeyDownBound);
    }
    this.stopUpdating();
    if (this.container && this.container.parentNode) {
      this.container.parentNode.removeChild(this.container);
      this.container = null;
    }
    if (this.triggerBtn && this.triggerBtn.parentNode) {
      this.triggerBtn.parentNode.removeChild(this.triggerBtn);
      this.triggerBtn = null;
    }
  }
}
