import { BossCloneEntity, BossEntity } from '../types.ts';

export class BossCloneSystem {
  public clones: BossCloneEntity[] = [];

  /**
   * Evaluates if boss HP passed threshold for cloning (PEPE <= 80%, POPCAT <= 50%).
   */
  public checkCloneThresholds(boss: BossEntity, arenaWidth: number): boolean {
    if (boss.hasCloned) return false;

    // 1. PEPE Dual-Body Shield-Link (HP <= 80%)
    if (boss.type === 'PEPE_FROG' || boss.type === 'REAPER_UFO') {
      if (boss.hp <= boss.maxHp * 0.8) {
        boss.hasCloned = true;
        // Balanced shield amount: ~2,000 HP for tangible, rewarding shield depletion feel
        const shieldAmount = Math.min(2400, Math.max(1200, Math.round(boss.maxHp * 0.07)));
        boss.shieldHp = shieldAmount;
        boss.maxShieldHp = shieldAmount;
        boss.isImmune = true;

        const clone: BossCloneEntity = {
          id: `clone_${boss.id}_1`,
          type: boss.type,
          x: Math.max(boss.size + 16, boss.x - 90),
          y: Math.max(80, boss.y),
          size: boss.size,
          color: boss.color,
          hp: shieldAmount,
          maxHp: shieldAmount,
          hitFlashTimer: 0,
          shootTimer: 0,
          hoverAngle: (boss.hoverAngle || 0) + Math.PI,
          hoverSpeed: (boss.hoverSpeed || 1.8) * 1.2,
          hoverBaseY: Math.max(120, boss.hoverBaseY || 140),
          animState: 'IDLE',
          frameIndex: 0,
          spriteSheetUrl: boss.spriteSheetUrl,
          aspectRatio: boss.aspectRatio,
        };

        this.clones.push(clone);
        boss.clones = this.clones;
        return true;
      }
    }

    // 2. POPCAT Mitosis Split (HP <= 50%)
    if (boss.type === 'POPCAT_OVERLORD') {
      if (boss.hp <= boss.maxHp * 0.5) {
        boss.hasCloned = true;
        boss.size = Math.round(boss.size * 0.8);

        const clone: BossCloneEntity = {
          id: `clone_popcat_${boss.id}_1`,
          type: boss.type,
          x: Math.min(arenaWidth - boss.size - 16, boss.x + 90),
          y: Math.max(80, boss.y),
          size: boss.size,
          color: boss.color,
          hp: Math.round(boss.hp / 2),
          maxHp: Math.round(boss.hp / 2),
          hitFlashTimer: 0,
          shootTimer: 0,
          hoverAngle: (boss.hoverAngle || 0) + Math.PI,
          hoverSpeed: (boss.hoverSpeed || 1.8) * 1.25,
          hoverBaseY: boss.hoverBaseY || 130,
          animState: 'IDLE',
          frameIndex: 0,
          spriteSheetUrl: boss.spriteSheetUrl,
          aspectRatio: boss.aspectRatio,
        };

        this.clones.push(clone);
        boss.clones = this.clones;
        return true;
      }
    }

    return false;
  }

  /**
   * Checks whether the main boss is currently protected by an active shield link.
   */
  public isBossImmune(boss: BossEntity): boolean {
    return !!boss.isImmune && (boss.shieldHp || 0) > 0 && this.clones.length > 0;
  }

  /**
   * Attempts to deal damage to the main boss.
   * If immune shield is active, the damage is absorbed and deducted from the shield,
   * preserving the Boss's real HP while weakening the resonant shield.
   * Returns false if damage was absorbed by active shield, true if direct HP was damaged.
   */
  public attemptBossDamage(boss: BossEntity, damage: number): boolean {
    if (this.isBossImmune(boss)) {
      this.handleBossShieldDamage(boss, damage);
      return false;
    }
    boss.hp = Math.max(0, boss.hp - damage);
    return true;
  }

  /**
   * Deducts damage directly from the Boss shield when hitting either the Main Boss or Clones.
   * Synchronizes linked clone HP and triggers shatter when shield reaches 0.
   */
  public handleBossShieldDamage(boss: BossEntity, damage: number): void {
    if (boss.shieldHp === undefined) return;

    boss.shieldHp = Math.max(0, boss.shieldHp - damage);

    // Synchronize clone HP with shield and trigger hit flash
    for (const clone of this.clones) {
      clone.hp = boss.shieldHp;
      clone.hitFlashTimer = 120;
    }

    if (boss.shieldHp <= 0) {
      this.shatterShield(boss);
    }
  }

  /**
   * Deals damage to a living clone, subtracting from the Boss shield bar.
   */
  public handleCloneDamage(boss: BossEntity, clone: BossCloneEntity, damage: number): void {
    clone.hitFlashTimer = 140;

    if (boss.shieldHp !== undefined) {
      this.handleBossShieldDamage(boss, damage);
    } else {
      // Shared damage for split bosses without shield
      clone.hp = Math.max(0, clone.hp - damage);
      boss.hp = Math.max(0, boss.hp - damage);
      if (clone.hp <= 0) {
        this.removeClone(boss, clone);
      }
    }
  }

  /**
   * Shatters the shield and removes all twin clones without stunning the boss.
   */
  public shatterShield(boss: BossEntity): void {
    boss.shieldHp = 0;
    boss.isImmune = false;
    this.clones = [];
    boss.clones = [];
  }

  /**
   * Shatters the shield and removes the twin clone without stunning the boss.
   * (Maintains backwards compatibility for single clone removal)
   */
  public shatterShieldAndClone(boss: BossEntity, clone: BossCloneEntity): void {
    boss.shieldHp = 0;
    boss.isImmune = false;
    this.removeClone(boss, clone);
  }

  private removeClone(boss: BossEntity, clone: BossCloneEntity): void {
    const idx = this.clones.indexOf(clone);
    if (idx !== -1) {
      this.clones.splice(idx, 1);
      boss.clones = this.clones;
    }
  }

  /**
   * Updates dynamic 3D-like motion, wing flanking, and combat state machine for active clones.
   */
  public update(
    dt: number,
    player: { x: number; y: number },
    arenaWidth: number,
    _arenaHeight: number,
    onCloneShoot?: (clone: BossCloneEntity) => void
  ): void {
    const dtSec = dt / 1000;

    for (let i = this.clones.length - 1; i >= 0; i--) {
      const c = this.clones[i];
      if (c.hitFlashTimer && c.hitFlashTimer > 0) c.hitFlashTimer -= dt;

      // 1. Dynamic Flanking & Tactical Positioning (X-axis)
      const margin = c.size + 24;
      c.hoverAngle = (c.hoverAngle || 0) + (c.hoverSpeed || 1.8) * dtSec;
      const wingOffset = (i % 2 === 0 ? -120 : 120) + Math.cos(c.hoverAngle * 1.3) * 60;
      const targetX = Math.max(margin, Math.min(arenaWidth - margin, player.x + wingOffset));
      c.x += (targetX - c.x) * Math.min(1.0, dtSec * 4.2);

      // 2. Vertical 3D Airspace Patrol: dynamic breathing across Y ∈ [95, 255]
      const targetY = Math.max(90, Math.min(260, 160 + Math.sin(c.hoverAngle * 0.95) * 65));
      c.y += (targetY - c.y) * Math.min(1.0, dtSec * 3.6);

      // 3. Attack State Machine & Telegraphing
      c.shootTimer = (c.shootTimer || 0) + dtSec;
      if (c.shootTimer >= 2.0 && c.shootTimer < 2.4) {
        c.animState = 'WINDUP';
        c.frameIndex = 1;
      } else if (c.shootTimer >= 2.4 && c.shootTimer < 2.7) {
        if (c.animState !== 'ATTACK') {
          c.animState = 'ATTACK';
          c.frameIndex = 2;
          onCloneShoot?.(c);
        }
      } else if (c.shootTimer >= 2.7) {
        c.animState = 'IDLE';
        c.frameIndex = 0;
        c.shootTimer = 0;
      }
    }
  }

  public clear(): void {
    this.clones = [];
  }
}
