import { I18nService } from '../../../platform/I18nService.ts';
import { SaveManager } from '../save/SaveManager.ts';
import { BossDefeatSnapshot } from '../save/types.ts';

export interface BossSelectModalOptions {
  saveManager?: SaveManager;
  onStartNewRun: () => void;
  onSelectBoss: (snapshot: BossDefeatSnapshot) => void;
  onClose?: () => void;
}

export interface BossRosterItem {
  stage: number;
  type: string;
  nameZh: string;
  nameEn: string;
  portrait: string;
}

export const BOSS_ROSTER: BossRosterItem[] = [
  { stage: 1, type: 'DOGE_KING', nameZh: '始祖神犬', nameEn: 'Doge King', portrait: './assets/bosses/portraits/boss_doge_portrait.png' },
  { stage: 2, type: 'PEPE_FROG', nameZh: '悲傷蛙神', nameEn: 'Pepe the Frog', portrait: './assets/bosses/portraits/boss_pepe_portrait.png' },
  { stage: 3, type: 'WHALE_GOD', nameZh: '萬億巨鯨', nameEn: 'Whale God', portrait: './assets/bosses/portraits/boss_whale_portrait.png' },
  { stage: 4, type: 'WIF_HAT', nameZh: '戴帽神柴', nameEn: 'Dogwifhat', portrait: './assets/bosses/portraits/boss_wif_portrait.png' },
  { stage: 5, type: 'BONK_MASTER', nameZh: '球棒制裁者', nameEn: 'Bonk Master', portrait: './assets/bosses/portraits/boss_bonk_portrait.png' },
  { stage: 6, type: 'POPCAT_OVERLORD', nameZh: '魔性啵啵貓', nameEn: 'Popcat Overlord', portrait: './assets/bosses/portraits/boss_popcat_portrait.png' },
  { stage: 7, type: 'FLOKI_VIKING', nameZh: '維京海盜王', nameEn: 'Floki the Viking', portrait: './assets/bosses/portraits/boss_floki_portrait.png' },
  { stage: 8, type: 'MOODENG_TERROR', nameZh: '暴躁彈跳豬', nameEn: 'Moo Deng', portrait: './assets/bosses/portraits/boss_moodeng_portrait.png' },
  { stage: 9, type: 'WOJAK_TRADER', nameZh: '麥當勞哭哭男', nameEn: 'Wojak Down-Only', portrait: './assets/bosses/portraits/boss_wojak_portrait.png' },
  { stage: 10, type: 'GIGACHAD_OMEGA', nameZh: '終極完美型男', nameEn: 'GigaChad Ascended', portrait: './assets/bosses/portraits/boss_gigachad_portrait.png' },
];

export class BossSelectModal {
  private saveManager: SaveManager;
  private onStartNewRun: () => void;
  private onSelectBoss: (snapshot: BossDefeatSnapshot) => void;
  private onClose?: () => void;
  private element: HTMLElement | null = null;
  private unsubscribeLocale: (() => void) | null = null;

  constructor(options: BossSelectModalOptions) {
    this.saveManager = options.saveManager ?? SaveManager.getInstance();
    this.onStartNewRun = options.onStartNewRun;
    this.onSelectBoss = options.onSelectBoss;
    this.onClose = options.onClose;
  }

  public render(): HTMLElement {
    const i18n = I18nService.getInstance();
    const modalEl = document.createElement('div');
    modalEl.id = 'boss-select-modal';
    modalEl.className = 'modal-overlay boss-select-overlay active';

    this.element = modalEl;
    this.updateContent();

    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
    }
    this.unsubscribeLocale = i18n.onLocaleChange(() => {
      this.updateContent();
    });

    return modalEl;
  }

  public updateContent(): void {
    if (!this.element) return;
    const i18n = I18nService.getInstance();

    const title = i18n.t('bossSelect.title') || 'BOSS & STAGE SELECT';
    const subtitle = i18n.t('bossSelect.subtitle') || 'Select starting stage or challenge a boss directly';
    const newRunTitle = i18n.t('bossSelect.newRunTitle') || 'NEW RUN (STAGE 1)';
    const newRunDesc = i18n.t('bossSelect.newRunDesc') || 'Start fresh from Stage 1 with default level 1 stats';
    const defeatedBadge = i18n.t('bossSelect.challengeBtn') || '可挑戰';
    const lockedBadge = i18n.t('bossSelect.lockedBadge') || '未解鎖';
    const stageLabel = i18n.t('hud.stage') || 'STAGE';

    const cardsHtml = BOSS_ROSTER.map((item) => {
      const isDefeated = this.saveManager.isBossDefeated(item.stage);
      const badgeText = isDefeated ? defeatedBadge : lockedBadge;
      const isFinalBoss = item.stage === 10;
      const finalClass = isFinalBoss ? ' final-boss' : '';

      return `
        <button class="boss-card${finalClass} ${isDefeated ? 'unlocked' : 'locked'}" data-stage="${item.stage}" ${!isDefeated ? 'disabled' : ''}>
          <div class="boss-card-media">
            <img src="${item.portrait}" alt="${item.nameEn}" class="boss-card-img ${isDefeated ? 'unlocked' : 'locked'}" />
          </div>
          <div class="boss-card-meta">
            <span class="boss-card-stage">${stageLabel} ${item.stage}</span>
            <div class="boss-card-names">
              <span class="boss-name-zh">${item.nameZh}</span>
              <span class="boss-name-en">${item.nameEn}</span>
            </div>
            <span class="boss-card-badge ${isDefeated ? 'defeated' : 'locked'}">${badgeText}</span>
          </div>
        </button>
      `;
    }).join('');

    this.element.innerHTML = `
      <div class="game-modal boss-select-modal">
        <div class="boss-select-header">
          <h2 class="boss-select-title">${title}</h2>
          <p class="boss-select-subtitle">${subtitle}</p>
        </div>

        <div class="boss-select-quickstart">
          <button id="btn-new-run" class="btn-new-run">
            <div class="new-run-content">
              <span class="new-run-title">${newRunTitle}</span>
              <span class="new-run-desc">${newRunDesc}</span>
            </div>
          </button>
        </div>

        <div class="boss-grid-2col">
          ${cardsHtml}
        </div>
      </div>
    `;

    // Event Bindings
    const newRunBtn = this.element.querySelector('#btn-new-run');
    newRunBtn?.addEventListener('click', () => {
      this.hide();
      this.onStartNewRun();
    });

    const unlockedCards = this.element.querySelectorAll<HTMLElement>('.boss-card.unlocked');
    unlockedCards.forEach((card) => {
      card.addEventListener('click', () => {
        const stageStr = card.getAttribute('data-stage');
        const stage = Number(stageStr);
        const snapshot = this.saveManager.getSnapshot(stage);
        if (snapshot) {
          this.hide();
          this.onSelectBoss(snapshot);
        }
      });
    });
  }

  public show(): void {
    if (this.element) {
      this.updateContent();
      this.element.classList.add('active');
      this.element.style.display = 'flex';
    }
  }

  public hide(): void {
    if (this.element) {
      this.element.classList.remove('active');
      this.element.style.display = 'none';
    }
    this.onClose?.();
  }

  public destroy(): void {
    if (this.unsubscribeLocale) {
      this.unsubscribeLocale();
      this.unsubscribeLocale = null;
    }
    if (this.element && this.element.parentElement) {
      this.element.parentElement.removeChild(this.element);
    }
    this.element = null;
  }
}
